#define ll long long

using namespace std;

pair<bool,ll> co(ll n,ll aa,ll bb)
{
	ll i=0,a=max(aa,bb),b=min(aa,bb);
	while(a*i<=n)
	{
		if((n-a*i)%b)i++;
		else return {true,i+(n-a*i)/b};
	}
	return {false,-1};
}

int main(int argc, char *argv[])
{

	ios::sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);

	ll n,i,a[3],x;
	pair<bool,ll>p;
	cin>>n>>a[0]>>a[1]>>a[2];
	sort(a,a+3);
	i=n/a[0]*a[0];
	while(true)
	{
		p=co(n-a[0]*i,a[1],a[2]);
		if(p.first)
		{
			cout<<i+p.second;
			return 0;
		}
	}
}

