#define CLR0(a) CLR(a,0)

#define maxn 1500

int n, m, k, q;

map<string, int> names;
int eu[maxn], ev[maxn];


struct group
{
    set<int> people;
    set<int> keys;
    friend bool operator < (const group &a, const group &b)
    {
        if (a.people != b.people) return a.people < b.people;
        return a.keys < b.keys;
    }
    friend bool operator == (const group &a, const group &b)
    {
        return a.people == b.people && a.keys == b.keys;
    }
    void reset()
    {
        people.clear();
        keys.clear();
    }
    bool haskey(int x)
    {
        return keys.find(x) != keys.end();
    }
};

int getname(char *s)
{
    if (names.find(string(s)) == names.end())
    {
        names[s] = q++;
    }
    return names[s];
}

group g[maxn];
char s[1000];
int wh[maxn];
bool f[maxn], dead[maxn];

vector<group> calc()
{
    vector<group> res;
    for (int i = 0; i < n; i++) g[i].reset();
    for (int i = 0; i < k; i++)
    {
        int room, cnt;
        scanf("%s%d%d", s, &room, &cnt);
        room--;
        g[room].people.insert(getname(s));
        for (int j = 0; j < cnt; j++)
        {
            int x;
            scanf("%d", &x);
            x--;
            g[room].keys.insert(x);
        }
    }
    for (int i = 0; i < n; i++) wh[i] = i;

    CLR(f, false);
    CLR(dead, false);
    bool ok = true;
    while (ok)
    {
        ok = false;
        for (int i = 0; i < m; i++) if (wh[eu[i]] != wh[ev[i]])
        {
            if (g[wh[eu[i]]].haskey(i) || g[wh[ev[i]]].haskey(i))
            {
                ok = true;
                //f[i] = true;
                int g1 = wh[ev[i]];
                int g2 = wh[eu[i]];
                for (int j = 0; j < n; j++) if (wh[j] == g2) wh[j] = g1;
                dead[g2] = true;
                g[g1].keys.insert(ALL(g[g2].keys));
                g[g1].people.insert(ALL(g[g2].people));
            }
        }
    }
    for (int i = 0; i < n; i++) if (!dead[i]) res.PB(g[i]);
    sort(ALL(res));
    return res;
}

void solve() {
    scanf("%d%d%d", &n, &m, &k);
    for (int i = 0; i < m; i++)
    {
        scanf("%d%d", &eu[i], &ev[i]);
        eu[i]--;
        ev[i]--;
    }
