#define inf 1000000000
#define eps 1e-9

inline int sgn(double a) {if (a > eps) return 1; else if (a < -eps) return -1; return 0;}

struct point {
    double x, y;
    double ang, l;
    point(double x, double y) : x(x), y(y) {l = len(); if (sgn(x) && sgn(y)) ang = angle();}
    point() {}
    inline void read() {int a, b; scanf("%d%d", &a, &b); x = a, y = b; *this = point(x, y);}
    inline double len() const {return sqrt(x * x + y * y);}
    inline double len2() const {return x * x + y * y;}
    inline double angle() {return atan2(y, x);}
    inline double slope() {return y / x;}
    inline int part() {
        return (int)(y > 0 || (sgn(y) == 0 && x > 0));
    }
    inline void normalize() {
        double r = 1.0 / len();
        x *= r; y *= r;
    }
    inline point getNormal() {
        point ret = *this;
        ret.normalize();
        return ret;
    }
};

inline point operator -(const point &a, const point &b) {return point(a.x - b.x, a.y - b.y);}
inline point operator +(const point &a, const point &b) {return point(a.x + b.x, a.y + b.y);}
inline point operator *(const point &a, double b) {return point(b * a.x, b * a.y);}
inline point operator *(double b, const point &a) {return point(b * a.x, b * a.y);}
inline double operator *(const point &a, const point &b) {return a.x * b.x + a.y * b.y;}
inline double operator %(const point &a, const point &b) {return a.x * b.y - a.y * b.x;}
inline bool operator ==(const point &a, const point &b) {return sgn(a.x - b.x) == 0 && sgn(a.y - b.y) == 0;}
inline bool operator !=(const point &a, const point &b) {return !(a == b);}
inline double dist(const point &a, const point &b) {return (a - b).len();}

bool operator <(point a, point b) {
    if (a.part() != b.part()) return b.part();
    int tmp = sgn(a % b);
    if (tmp) return tmp == 1;
    return a.len() + eps < b.len();
}

int n;

set<point> S;

typedef set<point>::iterator it;

void print() {
    for (it i = S.begin(); i != S.end(); i++) printf("%lf %lf %lf\n", i->x, i->y, i->ang);
}

it getPrev(it p) {
    if (p == S.begin()) p = S.end();
    p--;
    return p;
}

it getNext(it p) {
    p++;
    if (p == S.end()) p = S.begin();
    return p;
}

bool Inside(point p) {
//  print();
    it t1 = S.upper_bound(p);
    if (t1 == S.end()) t1 = S.begin();
    it t0 = getPrev(t1);
//  printf("%lf %lf\n", t0->x, t0->y);
//  printf("%lf %lf\n", t1->x, t1->y);
    return sgn((p - *t0) % (*t1 - *t0)) <= 0;
}

void Insert(point p) {
    if (Inside(p)) return;
    S.insert(p);
    it tmp = S.lower_bound(p);
    if (tmp != S.begin()) {
        tmp--;
        if (sgn(tmp->ang == p.ang)) S.erase(tmp);
    }
    while (true && S.size() > 3) {
        it t0 = getPrev(S.lower_bound(p)), t1 = getPrev(t0);
        if (sgn((*t0 - p) % (*t1 - p)) >= 0) S.erase(t0);
        else break;
    }
    while (true && S.size() > 3) {
        it t0 = getNext(S.lower_bound(p)), t1 = getNext(t0);
        if (sgn((*t0 - p) % (*t1 - p)) <= 0) S.erase(t0);
        else break;
    }
}


