#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

double cartesian_distance(const vector<double>& a, 
      const vector<double>& b) {
   double square_sum = 0;

   for(int i = 0; i < 3; ++i) {
      square_sum += (b[i] - a[i]) * (b[i] - a[i]);
   }

   return sqrt(square_sum);
}

inline void read_point(vector<double>& dest) {
   for(int j = 0; j < 3; ++j) {
      int a;
      cin >> a;
      dest[j] = a;
   }
}

int main() {
   ios_base::sync_with_stdio(false);

   cout.setf(ios_base::fixed, ios_base::floatfield);
   cout.precision(10);

   int n;
   cin >> n;

   vector<vector<double> > lines(n + 1, vector<double>(3));

   for(int i = 0; i <= n; ++i) {
      read_point(lines[i]);
   }

   int v_potter, v_snitch;
   cin >> v_potter >> v_snitch;

   vector<double> potter_start(3);
   read_point(potter_start);

   // General idea: Do a binary search on the time Harry will catch
   // the snitch. 
   // Let t_left and t_right be the range of times where
   // you are searching in, and t_middle = (t_left + t_right) / 2.
   // If Harry can reach the ball at t_middle (i.e, if the time it takes
   // Harry to reach the point where the snitch is at t_middle is <= 
   // t_middle), then we'll search in [t_left, t_middle], otherwise
   // we'll search in [t_middle, t_right]. Notice that, because 
   // v_potter >= v_snitch, if Harry can catch the snitch at time
   // t_a, then he will be able to catch it at time t_b > t_a. So the
   // algorithm will always find the correct answer if it exists.
   // Also, if Harry can't reach the last point fast enough (i.e before
   // the snitch), then there is no answer.
   //
   // We'll need to compute the time it takes reach each particular 
   // line so we know the point where the snitch is at a particular time t

   vector<double> times(n + 1);

   for(int i = 1; i <= n; ++i) {
      times[i] = times[i - 1] + 
         cartesian_distance(lines[i], lines[i - 1]) / v_snitch;
   }

   if (times[n] < cartesian_distance(potter_start, lines[n]) /
         v_potter) {
      cout << "NO\n";
   } else {
      // Possible, start binary search
      double t_left = 0, 
             t_right = times[n],
             t_middle;

      const double eps = 1e-12;
      vector<double> point(3);

      while(true) {
        t_middle = (t_left + t_right) / 2;

        // Find the line where t_middle belongs
        // index is the second point of the line
        int index = upper_bound(times.begin(), times.end(), t_middle) -
           times.begin();

        double segment_time = t_middle - times[index - 1];
        double factor = segment_time / (times[index] - times[index - 1]);

        // Compute point
        for(int i = 0; i < 3; ++i) {
           point[i] = lines[index - 1][i] + 
              factor * (lines[index][i] - lines[index - 1][i]);
        }

        double potter_distance = cartesian_distance(point, potter_start);
        double potter_time = potter_distance / v_potter;

        if (abs(potter_time - t_middle) <= eps) {
           break;
        } else if (potter_time > t_middle) {
           // Search right
           t_left = t_middle;
        } else {
           t_right = t_middle;
        }
      }

      cout << "YES\n";
      cout << t_middle << '\n';
      cout << point[0] << ' ' << point[1] << ' ' << point[2] << '\n';
   }
}

