	for(int i = 0 ; i < n ; i ++){
		for(int j = 0 ; j <= n ; j ++){
			int t = (a[i + 1] - a[i]) * j;
			for(int k = 0 ; k <= m - t ; k ++){
				(f[i + 1][j][k + t] += f[i][j][k] * (j + 1) % MOD) %= MOD;
				if(j != n) (f[i + 1][j + 1][k + t] += f[i][j][k]) %= MOD;
				if(j != 0) (f[i + 1][j - 1][k + t] += f[i][j][k] * j % MOD)  %= MOD;
			}
		}
	}
}
