using namespace std;

#define forn(i, n) for (int i = 0; i < (n); ++i)
#define foreach(it, a) for (__typeof((a).begin()) it = (a).begin(); it != (a).end(); ++it)

int main(void) {
	int n, k, p, q;
	cin >> n >> k;
	p = n / k;
	vector<int> prof(n);
	forn(i, n)
		cin >> prof[i];
	cin >> q;
	vector<bool> mark(n, false);
	double minProf = numeric_limits<double>::max();
	double maxProf = 0;

	forn(i, q) {
		double average = 0;
		forn(j, p) {
			int index;
			cin >> index;
			--index;
			mark[index] = true;
			average += prof[index];
		}
		average /= p;
		minProf = min(minProf, average);
		maxProf = max(maxProf, average);
	}

	vector<int> remaining;
	forn(i, n)
		if (not mark[i])
			remaining.push_back(prof[i]);

	int m = remaining.size();
	if (m >= p && m < k * p) {
		sort(remaining.begin(), remaining.end());
		double minMean = 0;
		double maxMean = 0;
		forn(i, p) {
			minMean += remaining[i];
			maxMean += remaining[m - i - 1];
		}
		minMean /= p;
		maxMean /= p;
		minProf = min(minProf, minMean);
		maxProf = max(maxProf, maxMean);
	}

	printf("%.10lf %.10lf\n", minProf, maxProf);

	return 0;
}

