ll dp[2*MAXN][MAXN],val[MAXN];
int main()
{
    ios::sync_with_stdio(false); cin.tie(0); cout.tie(0);
    ll n;
    string s;
    cin >> n >> s;
    s=' '+s;
    val[n]=1;
    for (ll i=n-1;i>0;i--)
        val[i]=val[i+1]*10;
    for (ll i=1;i<=2*n;i++)
    {
        for (ll j=0;j<=n;j++)
        {
            if (j)
                dp[i][j]=max(dp[i][j],dp[i-1][j-1]+val[j]*(s[i]-'0'));
            if (j<i && i-j<=n)
                dp[i][j]=max(dp[i][j],dp[i-1][j]+val[i-j]*(s[i]-'0'));
        }
    }
    string ans="";
    ll i=2*n,j=n;
    while (true)
