using namespace std;

const double eps = 1e-8;
const int MaxN = 25, MaxSize = MaxN * MaxN;

int N, M, SA, SB, tot;
bool g[MaxN][MaxN];
int deg[MaxN];
double P[MaxN], ans[MaxSize];

int lab(int a, int b) {
    return (a - 1) * N + (b - 1);
}

struct Matrix {
    double a[MaxSize][MaxSize];
    void init() {
        for (int i = 0; i < tot; ++i)
            for (int j = 0; j <= tot; ++j) 
                a[i][j] = 0;
        for (int i = 0; i < tot; ++i)
            a[i][i] = 1;
        a[lab(SA, SB)][tot] = 1;
        for (int i = 1; i <= N; ++i)
            for (int j = 1; j <= N; ++j) 
                    for (int ii = 1; ii <= N; ++ii)
                        for (int jj = 1; jj <= N; ++jj) if (ii != jj && g[i][ii] && g[j][jj]) {
                            double pi = (i == ii) * P[ii] + (i != ii) * (1 - P[ii]) / deg[ii];
                            double pj = (j == jj) * P[jj] + (j != jj) * (1 - P[jj]) / deg[jj];
                            int t1 = lab(i, j), t2 = lab(ii, jj);
                            a[t1][t2] -= pi * pj;
                        }         
    }  
    void elimiate() {
        int i, j, k, p;
        for (i = 0, j = 0; i < tot; ++i, ++j) {
            for (k = i; k < tot; ++k) if (fabs(a[k][j]) > eps) break;
            for (p = i; p <= tot; ++p) swap(a[i][p], a[k][p]);
            for (k = i + 1; k < tot; ++k) if (fabs(a[k][j]) > eps) {
                double t = a[k][j] / a[i][j];
                for (p = j; p <= tot; ++p) 
                    a[k][p] = a[k][p] - a[i][p] * t; 
            }
        }
    } 
    void solve() {
        for (int i = tot - 1; i >= 0; --i) {
            ans[i] = a[i][tot];
            for (int j = i + 1; j < tot; ++j)
                ans[i] -= ans[j] * a[i][j];
            ans[i] /= a[i][i];
        }
    }    
}mat;

int main() {

    scanf("%d%d%d%d", &N, &M, &SA, &SB);
    tot = N * N;
    int x, y;
    memset(g, 0, sizeof(g));
    memset(deg, 0, sizeof(deg));
    for (int i = 1; i <= N; ++i) g[i][i] = true;
    for (int i = 0; i < M; ++i) {
        scanf("%d%d", &x, &y);
        g[x][y] = g[y][x] = true;
        deg[x]++; deg[y]++;
    }
    for (int i = 1; i <= N; ++i) scanf("%lf", P + i);
    mat.init();
    mat.elimiate();
    mat.solve();
    for (int i = 1; i < N; ++i) printf("%.8f ", ans[lab(i, i)]);
    printf("%.8f\n", ans[lab(N, N)]);

    return 0;

}

