#include<bits/stdc++.h>

using namespace std;
using lint = long long int;

const int MAX_N = 2e5;
const int MAX_M =  3001;
const lint MOD = 998244353;

lint dp1[MAX_M][MAX_M];
lint dp2[MAX_M][MAX_M];
int state[MAX_N];
lint wi[MAX_N];
lint SA, SB;

lint pow(lint x, lint N) {
	lint ret = 1;

	while (N) {
		if (N & 1) 
			(ret *= x) %= MOD;
		(x *= x) %= MOD;
		N >>= 1;
	}
	return ret;
}

lint inv(lint x) {
	return pow(x, MOD-2);
}

lint solve1(int i, int j, int M) {
	if (dp1[i][j] != -1)
		return dp1[i][j];

	lint &ret = dp1[i][j];
	ret = 0;


	if (i+j == M)
		return ret = 1;

	lint ri = SA + i, rj = SB - j;
	(ret += solve1(i+1, j, M) * (ri + 1) % MOD * inv(ri+rj) % MOD) %= MOD;
	if (SB-j-1 >= 0)
		(ret += solve1(i, j+1, M) * rj % MOD * inv(ri+rj) % MOD) %= MOD;

	return ret;
}

lint solve2(int i, int j, int M) {
	if (dp2[i][j] != -1)
		return dp2[i][j];

	lint &ret = dp2[i][j];
	ret = 0;

	if (i+j == M)
		return ret = 1;

	lint ri = SA + i, rj = SB - j;

	if (rj-1 >= 0) 
		(ret += solve2(i, j+1, M) * (rj - 1) % MOD * inv(ri+rj) % MOD) %= MOD;
	(ret += solve2(i+1, j, M) * ri % MOD * inv(ri+rj) % MOD) %= MOD;

	return ret;
}

int main(void) {
	ios_base::sync_with_stdio(false), cin.tie(NULL);
	memset(dp1, -1, sizeof dp1);
	memset(dp2, -1, sizeof dp2);

	int N, M;	cin >> N >> M;

	for (int i = 0; i < N; i ++) 
		cin >> state[i];

	for (int i = 0; i < N; i ++) {
		cin >> wi[i];

		(state[i]?SA:SB) += wi[i];
	}

	for (int i = 0; i < N; i ++) 
		cout << (wi[i]*(state[i]?solve1(0, 0, M):solve2(0, 0, M)))%MOD << '\n';
}

