const int maxn = 2e5, maxm = 3000;

int n, m;
int type[maxn], wei[maxn];
// int n1, w1[maxn], s1;
// int n0, w0[maxn], s0;
int s0, s1;
int pro[maxm + 2][maxm + 2];

int _inv[4 * maxm + 1], *inv = _inv + 2 * maxm;

int main(void) {
  scanf("%d%d", &n, &m);
  for (int i = 0; i < n; ++i) {
    scanf("%d", type + i);
  }
  for (int i = 0; i < n; ++i) {
    scanf("%d", wei + i);
  }
  for (int i = 0; i < n; ++i) {
    if (type[i] == 0) {
      // w0[n0++] = wei[i];
      Add(s0, wei[i]);
    } else {
      // w1[n1++] = wei[i];
      Add(s1, wei[i]);
    }
  }

  for (int i = -2 * m; i <= 2 * m; ++i) {
    int x = Sub(Add(Add(s0 + s1) + i));
    inv[i] = Pow(x, mod - 2);
  }

  int ans0 = 0, ans1 = 0;

  pro[0][0] = 1;
  for (int i = 0; i < m; ++i) {
    for (int j = 0; i + j < m; ++j) {
      int p = pro[i][j];
      // printf("pro[%d][%d] = %d\n", i, j, p);
      if (p == 0) continue;
      int ss0 = s0 - i;
      int ss1 = s1 + j;
      int pp0 = Mul(ss0, inv[j - i]);
      int pp1 = Mul(ss1, inv[j - i]);
      int p0 = Mul(p, pp0);
      int p1 = Mul(p, pp1);
      Add(pro[i + 1][j], p0);
      Add(pro[i][j + 1], p1);
      Add(ans0, p0);
      Add(ans1, p1);
    }
  }

  ans0 = Mul(ans0, Pow(s0, mod - 2));
  ans1 = Mul(ans1, Pow(s1, mod - 2));
  for (int i = 0; i < n; ++i) {
    int w = wei[i];
    if (type[i] == 0) {
      Sub(w, Mul(ans0, w));
    } else {
      Add(w, Mul(ans1, w));
    }
    printf("%d\n", w);
  }
}

