using namespace std;

long long bfs(int tren, vector<vector <long long>> adj,int n){
    vector<long long> distancia(n,0);
    vector<int> visitado(n,0);
    queue<int> cola;
    cola.push(0);
    while(!cola.empty()){
        int v=cola.front();
        visitado[v]=1;
        cola.pop();
        if(v==n-1){
            return distancia[n-1];
        }
        for(int i=0;i<n;i++){
            if(visitado[i]!=1 and adj[v][i]==tren){
                distancia[i]=distancia[v]+1;
                cola.push(i);

            }
        }
    }
    return -1;
}
int main()
{
	int n;
	long long m;
	scanf("%d %d\n",&n,&m);
	vector<vector<long long>> adj (n,vector<long long>(n,0));
	for(long long i=0;i<m;i++){
	    int a;
	    int b;
	    scanf("%d %d\n",&a,&b);
	    adj[a-1][b-1]=1;
	    adj[b-1][a-1]=1;
	}
	long long resp=0;
	long long r1=bfs(1,adj, n);
	long long r2=bfs(0,adj, n);
	if(r1==-1 or r2==-1){
	    resp=-1;
	}
	else{
	    if(r1>r2){
	        resp=r1;
	    }
	    else{
	        resp=r2;
	    }
	}
	cout<<resp;
}

