//                writer.println("failed " + i);
//                return;
//            }
//        }
        long l = nextLong();
        long r = nextLong();
        writer.println(utils.count(r) - utils.count(l - 1));
    }

    public static void main(String[] args) throws IOException {
        try (A a = new A()) {
            a.solve();
        }
    }

