public class Main
{
	static int total[][],n,m;


	public static void main(String[] args)
	{

		Scanner in = new Scanner(System.in);
		n = in.nextInt();
		m = in.nextInt();

		total = new int[n][m];
		int maxInt = 200;

		for (int i=0;i < n;i++)
			for (int j=0;j < m;j++)
				total[i][j] = maxInt;


		String str;
		int half = m % 2 == 0 ? m / 2 + 1 : m / 2;
		int count =0;

		for (int i=0;i < n;i++)
		{
			str = in.next();

			for (int j=0;j < m;j++)
				if (str.charAt(j) == '1')
				{
					total[i][j] = 0;
					fillLeft(i, j, half);
					fillRight(i, j, half);
				}
				else
					count++;

			if (count == m)
			{
				System.out.println(-1);
				return;
			}

		}//read data

		int min = maxInt,v;

		for (int i =0;i < m;i++)
		{
			if ((v = sumColumn(i)) < min)
				min = v;

			if(v==0)
			{
				System.out.println(-1);
				return;
			}
		}


		System.out.println(min);

	}

	public static int sumColumn(int col)
	{
		int sum = 0;

		for (int i=0;i < n;i++)
			sum += total[i][col];

		return sum;
	}

	public static void fillLeft(int row, int st, int step)
	{


		for (int i =1;i <= step;i++)
		{
			st = st == 0 ? m - 1 : --st;
			total[row][st] = Math.min(total[row][st], i);
		}

	}

	public static void fillRight(int row, int st, int step)
	{


		for (int i =1;i <= step;i++)
		{
			st = st == m - 1 ? 0 : ++st;
			total[row][st] = Math.min(total[row][st], i);
		}

	}

}

