import javax.swing.*;
import java.io.PrintWriter;
import java.util.Scanner;

public class SaveTheCity {
    public static int n;
    public static Vertices[] vertices;
    static class Vertices{
        int x,y;
        Vertices(int x, int y){
            this.x=x;
            this.y=y;
        }
    }

    static long cross(int i, int j, int k){
        long x1= vertices[j].x-vertices[i].x;
        long y1= vertices[j].y-vertices[i].y;
        long x2= vertices[k].x-vertices[i].x;
        long y2= vertices[k].y-vertices[i].y;
        return x1*y2-x2*y1;
    }

    public static void main(String[] args) {
        Scanner cin= new Scanner(System.in);
        PrintWriter pw= new PrintWriter(System.out);
        n=cin.nextInt();
        vertices= new Vertices[n];
        for(int i=0;i<n;i++){
            int x= cin.nextInt();
            int y= cin.nextInt();
            vertices[i]= new Vertices(x,y);
        }
        boolean change= vertices[0].x<vertices[1].x;
        int x=vertices[1].x, y=vertices[1].y;
        for(int i=0;i<n;i++){
            vertices[i].x-=x;
            vertices[i].y-=y;
            if(change){
                vertices[i].x=-vertices[i].x;
                vertices[i].y=-vertices[i].y;
            }
        }
        int l=0,r=vertices[0].x;
        for(int i=2;i+1<n;i++){
            long crossLeft=cross(i,i+1,0);
            long crossRight= cross(i,i+1,1);
            if(crossRight>0 && crossLeft>0){
                pw.println(0);
                return;
            }
            int x0 = vertices[i].x, y0 = vertices[i].y, x1 = vertices[i + 1].x, y1 = vertices[i + 1].y;
            if (crossRight > 0 || crossLeft > 0) {
                long p = (long) x0 * (y1 - y0) - (long) y0 * (x1 - x0);
                long q = y1 - y0;
                if (q < 0) {
                    p = -p; q = -q;
                }
                if (crossRight > 0)
                    r = Math.min(r, (int) (p / q));
                else
                    l = Math.max(l, (int) ((p + q - 1) / q));
            }
        }
        pw.println(l<=r?r-l+1:0);

    }

}

