 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        DTowers solver = new DTowers();
        solver.solve(1, in, out);
        out.close();
    }

    static class DTowers {
        int MAXN = 5005;
        PrintWriter out;
        InputReader in;
        int n;
        long[] pf = new long[MAXN];
        long[][] dp = new long[MAXN][MAXN];

        long go(int ind, int last) {
            if (ind == n + 1)
                return 0;
            if (dp[ind][last] != -1)
                return dp[ind][last];
            long val = 1 + go(ind + 1, last);
            long last_sum = pf[ind - 1] - pf[last];
            int lo = ind, hi = n - 1;
            while (lo <= hi) {
                int mid = (lo + hi) >> 1;
                if (pf[mid] - pf[ind - 1] < last_sum)
                    lo = mid + 1;
                else
                    hi = mid - 1;
            }
            lo++;
            //System.out.println(ind +" "+lo+" "+last);
            long nxt_sum = pf[lo - 1] - pf[ind - 1];
            if (pf[n] - pf[lo - 1] >= nxt_sum) {
                int len = lo - ind;
                long cost = len - 1;
                val = Math.min(val, go(lo, ind - 1) + cost);
            } else {
                int len = n + 1 - ind;
                long cost = len - 1;
                val = Math.min(val, go(n + 1, ind - 1) + cost);
            }
            dp[ind][last] = val;
            return val;
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            this.out = out;
            this.in = in;
            n = ni();
            int i = 0;
            for (i = 1; i <= n; i++)
                pf[i] = pf[i - 1] + nl();
            for (i = 0; i <= n; i++)
                Arrays.fill(dp[i], -1);
            long min = (int) 1e9;
            if (n == 1) {
                pn(0);
                return;
            }
            for (i = 1; i <= n; i++) {
                //pn(i);
                if (pf[n] - pf[i] >= pf[i]) {
                    int len = i;
                    long cost = len - 1;
                    min = Math.min(min, go(i + 1, 0) + cost);
                } else {
                    int len = n;
                    long cost = len - 1;
                    min = Math.min(min, go(n + 1, 0) + cost);
                }
            }
            pn(min);
        }

        int ni() {
            return in.nextInt();
        }

        long nl() {
            return in.nextLong();
        }

        void pn(long zx) {
            out.println(zx);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new UnknownError();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new UnknownError();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuffer res = new StringBuffer();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));

            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }
}

