                if (d < prev - 1) {
                    long w = (k - s)/t;
                    d += w;
                }
                System.out.println(d);
                return;
            }
            prev = d;
        }
    }

    static void segs(int d) {
        for (int i = 1; i <= Math.sqrt(d); i++) {
            a[cnt++] = i;
            a[cnt++] = (d + i - 1)/i;
        }
