        }

        boolean chk(char[][] puzzle, int Y, int X) {
            TreeSet<fullPiece> pieces = new TreeSet<>();
            for (int i = 0; i < puzzle.length; i += Y) {
                for (int j = 0; j < puzzle[0].length; j += X) {
                    pieces.add(new fullPiece(puzzle, Y, X, i, j));
                }
            }
            int all = puzzle.length / Y;
            all *= puzzle[0].length / X;
            if (pieces.size() == all) {
                return true;
            }
            return false;
        }

    }

    static class piece implements Comparable {
        int y;
        int x;

        piece(int y1, int x1) {
            y = y1;
            x = x1;
        }

        public int compareTo(Object o) {
            piece other = (piece) o;
            int oS = other.x * other.y;
            int S = x * y;
            if (S == oS) {
                return y - other.y;
            }
            return S - oS;
        }

        public String toString() {
            return y + " " + x;
        }

    }

    static class fullPiece implements Comparable {
        char[][] data;

        fullPiece(char[][] puzzle, int Y, int X, int top, int left) {
            data = new char[Y][X];
            for (int i = 0; i < Y; i++) {
                for (int j = 0; j < X; j++) {
                    data[i][j] = puzzle[i + top][j + left];
                }
            }
        }

        public int compareTo(Object o) {
            fullPiece other = (fullPiece) o;
            if (eq(other)) {
                return 0;
            }
            return comp(other);
        }

        private int comp(fullPiece other) {
            int Y = data.length;
            int X = data[0].length;
            for (int i = 0; i < Y; i++) {
                for (int j = 0; j < X; j++) {
                    if (data[i][j] > other.data[i][j]) return 1;
                    if (data[i][j] < other.data[i][j]) return -1;
                }
            }
            return 0;
        }

        private boolean eq(fullPiece other) {
            return eq0(other) || eq90(other) || eq180(other) || eq270(other);
        }

        private boolean eq0(fullPiece other) {
            int Y = data.length;
            int X = data[0].length;
            for (int i = 0; i < Y; i++) {
                for (int j = 0; j < X; j++) {
