            for (int i = 0; i < Y; i++) {
                for (int j = 0; j < X; j++) {
                    if (data[j][Y - i - 1] != other.data[i][j]) return false;
                }
            }
            return true;
        }

        private boolean eq270(fullPiece other) {
            int Y = data.length;
            int X = data[0].length;
            if (other.data[0].length != Y) return false;
            if (other.data.length != X) return false;
            for (int i = 0; i < Y; i++) {
                for (int j = 0; j < X; j++) {
                    if (data[X - j - 1][i] != other.data[i][j]) return false;
                }
            }
            return true;
        }

    }

