			int u = sc.nextInt() - 1, v = sc.nextInt() - 1;
			adjList[u].add(v);
			adjList[v].add(u);
		}
		Comp[] comps = new Comp[n];
		int sz = 0;
		boolean[] vis = new boolean[n];
		for(int i = 0; i < n; ++i)
			if(!vis[i])
