					for(int v: adjList[u])
						if(!vis[v])
						{
							vis[v] = true;
							q.add(v);
						}
				}
				comps[sz++] = new Comp(s);
			}
		Arrays.sort(comps, 0, sz);
		int idx = sz - 2, ans = 0, pIdx = sz - 1;
		PriorityQueue<Comp> cand = new PriorityQueue<>(new Selector());
		while(idx >= 0)
		{

			while(pIdx > idx && comps[pIdx].used == comps[pIdx].pt)
				cand.add(comps[pIdx--]);
			if(pIdx == idx)
			{
				++ans;
				Comp best = cand.remove();
				int used = best.used;
				best = new Comp(best.sz + comps[idx].sz);
				best.used = used;
				comps[idx] = best;
			}
			else
			{
				comps[pIdx].used++;
				comps[idx].used++;
			}
			idx--;
		}
		out.println(ans);
		out.close();
	}	

	static class Selector implements Comparator<Comp>
	{
		public int compare(Comp a, Comp b)
		{
			return b.x - a.x; 
		}
	}

	static class Comp implements Comparable<Comp>
	{
		int sz, pt, x, used;

		Comp(int a) { sz = a; pt = Math.min(sz, k); x = k - pt; }

		public int compareTo(Comp c) { return sz - c.sz; }
