class TaskD {
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        int k = in.nextInt();
        DisjointSet dsu = new DisjointSet(n);
        int[] size = new int[n];
        Arrays.fill(size, 1);
        while (m-- > 0) {
            int a = in.nextInt() - 1;
            int b = in.nextInt() - 1;
            int newSize = size[dsu.findSet(a)] + size[dsu.findSet(b)];
            if (dsu.union(a, b)) {
                int newRep = dsu.findSet(a);
                size[newRep] = newSize;
            }
        }
        List<Integer> componentSizes = new LinkedList<Integer>();
        boolean[] u = new boolean[n];
        for (int i = 0; i < n; ++i) {
            int rep = dsu.findSet(i);
            if (!u[rep]) {
                u[rep] = true;
                componentSizes.add(Math.min(size[rep], k));
            }
        }
        if (k == 1) {
            out.println(Math.max(0, componentSizes.size() - 2));
            return;
        }

        Collections.sort(componentSizes);
        int singleComponent = 0;
        while (!componentSizes.isEmpty() && componentSizes.get(0) == 1) {
            ++singleComponent;
            componentSizes.remove(0);
        }
        int freeLinks = 0;
        int edges = 0;
        for (int sz : componentSizes) {
            if (edges < 2) {
                freeLinks += sz - 1;
            } else {
                freeLinks += sz - 2;
            }
            ++edges;
        }
        if (singleComponent == 0) {
            out.println(0);
            return;
        }
        if (edges == 0) {
            singleComponent = (singleComponent + 1) / 2;
            out.println(singleComponent-1);
            return;
        }
        if (edges == 1) {
            ++freeLinks;
        }
        if (singleComponent <= freeLinks) {
            out.println(0);
        } else {
            singleComponent -= freeLinks;
            singleComponent = (singleComponent + 1) / 2;
            out.println(singleComponent);
        }
    }
}

