import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Scanner;
import java.util.Set;

public class Solution {

	private static Scanner sc;

	public static void main(String[] args) {

		sc = new Scanner(System.in);

		int n = sc.nextInt();
		double[][] A = new double [n][2];
		Map<Double, Integer> M1 = new HashMap<Double, Integer>();
		Map<Double, Set<Double>> M2 = new HashMap<Double, Set<Double>>();

		for (int i = 0; i < n ; ++i) {
			A[i][0] = sc.nextDouble();
			A[i][1] = sc.nextDouble();
		}

		for (int i = 0; i < n; ++i) {
			for (int j = i + 1; j < n; ++j) {

				double m;

				if (A[i][0] - A[j][0] == 0) {
					m = 2000000000;
				}
				else {
					m = (A[i][1] - A[j][1]) / ( A[i][0] - A[j][0]);
				}

				if (!M1.containsKey(m)) {
					M1.put(m, 0);
					M2.put(m, new HashSet<Double>());
				}

				int cnt = M1.get(m);

				M1.put(m, cnt + 1);

				if (m == 2000000000) {
					M2.get(m).add(A[i][0]);
				} else {
					M2.get(m).add(A[i][1] - m * A[i][0]);
				}
			}
		}

		long tot = 0;
		long cnt = 0;

		for (double m : M2.keySet()) {
			tot += M2.get(m).size();
		}

		for (double m : M2.keySet()) {
			cnt += (tot - M2.get(m).size()) * M2.get(m).size();
		}

		System.out.println(cnt / 2);

		sc.close();
	}
}

