import java.util.*;

public class LizardsAndBasements2 {

    static int N, a, b;
    static int[] h;
    static Integer[][][][] dp;
    static State[][][][] path;
    static final int INF = (int)1e9;

    static class State {
        int i, p, c, n;
        State(int i, int p, int c, int n) {
            this.i = i;
            this.p = p;
            this.c = c;
            this.n = n;
        }

        @Override
        public String toString() {
            return "(" + i + ", " + p + ", " + c + ", " + n + ")";
        }
    }

    static int solve(int index, int prev, int cur, int next) {
        prev = Math.max(0, prev);
        cur = Math.max(0, cur);
        next = Math.max(0, next);

        if (dp[index][prev][cur][next] != null) {
            return dp[index][prev][cur][next];
        }

        int ans = INF;
        if (index == N - 1) {
            return ans = prev + cur == 0 ? 0 : INF;
        } else if (index == N - 2) {
            if (next > 0) {
                ans = 1 + solve(index, prev - b, cur - a, next - b);
                path[index][prev][cur][next] = new State(index, prev - b, cur - a, next - b);
            } else {
                ans = prev + cur + next == 0 ? 0 : INF;
            }
        } else {
            if (prev > 0) {
                ans = 1 + solve(index, prev - b, cur - a, next - b);
                path[index][prev][cur][next] = new State(index, prev - b, cur - a, next - b);
            } else {
                if (cur > 0) {
                    ans = 1 + solve(index, prev - b, cur - a, next - b);
                    path[index][prev][cur][next] = new State(index, prev - b, cur - a, next - b);
                }
                int nn = index < N - 2 ? h[index + 2] : 0;
                int ans2 = solve(index + 1, cur, next, nn);
                if (ans2 < ans) {
                    ans = ans2;
                    path[index][prev][cur][next] = new State(index + 1, cur, next, nn);
                }
            }
        }
        return dp[index][prev][cur][next] = ans;
    }

    static void printPath() {
        State state = new State(1, h[0], h[1], h[2]);

        while (state != null) {
            if (Math.max(0, state.p) + Math.max(0, state.c) + Math.max(0, state.n) > 0)
                System.out.print((state.i + 1) + " ");
            state = path[state.i][Math.max(0, state.p)][Math.max(0, state.c)][Math.max(0, state.n)];
        }
        System.out.println();
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        N = in.nextInt();
        a = in.nextInt();
        b = in.nextInt();
        h = new int[N];
        for (int i = 0; i < N; i++) {
            h[i] = in.nextInt() + 1;
        }

        dp = new Integer[20][20][20][20];
        path = new State[20][20][20][20];
        int ans = solve(1, h[0], h[1], h[2]);
        System.out.println(ans);
        printPath();

        in.close();
        System.exit(0);
    }
}

