import java.util.*;

public class LizardsAndBasements2 {

    static int N, a, b;
    static int[] h;
    static Integer[][][] dp;
    static int[][][] path;
    static final int INF = (int)1e9;

    static int solve(int index, int prev, int cur) {
        if (index == N - 1) {
            return prev == 0 && cur == 0 ? 0 : INF;
        }

        if (dp[index][prev][cur] != null) {
            return dp[index][prev][cur];
        }
        int ans = INF;
        int shots = 0;
        int next = h[index + 1];
        while (true) {
            if (prev - b * shots <= 0) {
                int tmp = shots + solve(index + 1, Math.max(0, cur - a * shots), Math.max(0, next - b * shots));
                if (tmp < ans) {
                    ans = tmp;
                    path[index][prev][cur] = shots;
                }

            }
            if (prev - b * shots <= 0 && cur - a * shots <= 0 && next - b * shots <= 0)
                break;
            shots++;
        }
        return dp[index][prev][cur] = ans;
    }

    static void printPath(int index, int prev, int cur) {
        if (index == N - 1) return;
        int shots = path[index][prev][cur];
        for (int i = 0; i < shots; i++) {
            System.out.print((index + 1) + " ");
        }
        int next = h[index + 1];
        printPath(index + 1, Math.max(0, cur - a * shots), Math.max(0, next - b * shots));
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        N = in.nextInt();
        a = in.nextInt();
        b = in.nextInt();
        h = new int[N];
        for (int i = 0; i < N; i++) {
            h[i] = in.nextInt() + 1;
        }

