		OutputStream outputStream = System.out;
		InputReader in = new InputReader(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		Task solver = new Task();
		solver.solve(1, in, out);
		out.close();
	}
}

class Task {

	public void solve(int testNumber, InputReader in, PrintWriter out) {
		int n = in.nextInt();
		int m = in.nextInt();
		int[] positive = new int[n];
		int[] negative = new int[n];
		int cnt = 0;
		String[] memo = new String[n];
		for (int k = 0; k < n; ++k) {
			String s = in.next();
			memo[k] = s;
			int id = Integer.parseInt(s.substring(1)) - 1;
			if (s.startsWith("+")) {
				positive[id]++;
			} else {
				negative[id]++;
				cnt++;
			}
		}

		boolean[] maybe = new boolean[n];
		int all = 0;
		for (int k = 0; k < n; ++k) {
			int tmp = cnt + positive[k] - negative[k];
			if (tmp == m) {
				maybe[k] = true;
				all++;
			}
		}

		for (int k = 0; k < n; ++k) {
			String s = memo[k];
			int id = Integer.parseInt(s.substring(1)) - 1;
			if (s.startsWith("+")) {
				if (!maybe[id]) {
					out.println("Lie");
				} else {
					out.println(all == 1 ? "True" : "Not defined");
				}
			} else {
				if (!maybe[id]) {
					out.println("True");
				} else {
					out.println(all == 1 ? "Lie" : "Not defined");
				}
			}
		}

	}
}

