import java.io.*;
import java.util.*;

public class B implements Runnable {

    private static final boolean ONLINE_JUDGE = System.getProperty("ONLINE_JUDGE") != null;

    private BufferedReader in;
    private PrintWriter out;
    private StringTokenizer tok = new StringTokenizer("");

    private void init() throws FileNotFoundException {
        Locale.setDefault(Locale.US);
        String fileName = "";
        if (ONLINE_JUDGE && fileName.isEmpty()) {
            in = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);
        } else {
            if (fileName.isEmpty()) {
                in = new BufferedReader(new FileReader("input.txt"));
                out = new PrintWriter("output.txt");
            } else {
                in = new BufferedReader(new FileReader(fileName + ".in"));
                out = new PrintWriter(fileName + ".out");
            }
        }
    }

    String readString() {
        while (!tok.hasMoreTokens()) {
            try {
                tok = new StringTokenizer(in.readLine());
            } catch (Exception e) {
                return null;
            }
        }
        return tok.nextToken();
    }

    int readInt() {
        return Integer.parseInt(readString());
    }

    long readLong() {
        return Long.parseLong(readString());
    }

    double readDouble() {
        return Double.parseDouble(readString());
    }

    int[] readIntArray(int size) {
        int[] a = new int[size];
        for (int i = 0; i < size; i++) {
            a[i] = readInt();
        }
        return a;
    }

    public static void main(String[] args) {
        //new Thread(null, new _Solution(), "", 128 * (1L << 20)).start();
        new B().run();
    }

    long timeBegin, timeEnd;

    void time() {
        timeEnd = System.currentTimeMillis();
        System.err.println("Time = " + (timeEnd - timeBegin));
    }

    @Override
    public void run() {
        try {
            timeBegin = System.currentTimeMillis();
            init();
            solve();
            out.close();
            time();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(-1);
        }
    }

    int gcd(int a, int b) {
        return a == 0 ? b : gcd(b % a, a);
    }

    long answer = Long.MAX_VALUE;

    private void solve() {
        int n = readInt();

        int A = readInt();
        int B = readInt();
        int[] a = readIntArray(n);

        for (int kFirst = -1; kFirst <= 1; kFirst++) {
            int currentFirst = a[0] + kFirst;
            for (int divisor = 2; divisor * divisor <= currentFirst; divisor++) {
                if (currentFirst % divisor == 0) {
                    answer = Math.min(answer, solveForPrefix(n, a, divisor, A, B));
                }
                while (currentFirst % divisor == 0) {
                    currentFirst /= divisor;
                }
            }
            if (currentFirst > 1) {
                answer = Math.min(answer, solveForPrefix(n, a, currentFirst, A, B));
            }
        }

        int[] b = new int[n];
        for (int i = 0; i < n; i++) {
            b[i] = a[n - i - 1];
        }

        for (int kFirst = -1; kFirst <= 1; kFirst++) {
            int currentFirst = b[0] + kFirst;
            for (int divisor = 2; divisor * divisor <= currentFirst; divisor++) {
                if (currentFirst % divisor == 0) {
                    answer = Math.min(answer, solveForPrefix(n, b, divisor, A, B));
                }
                while (currentFirst % divisor == 0) {
                    currentFirst /= divisor;
                }
            }
            if (currentFirst > 1) {
                answer = Math.min(answer, solveForPrefix(n, b, currentFirst, A, B));
            }
        }
        out.println(answer);
    }

    final int PREFIX = 0;
    final int REMOVED = 1;
    final int SUFFIX = 2;

    long solveForPrefix(int n, int[] a, int gcd, int A, int B) {
        long[][] dp = new long[3][n];
        for (int i = 0; i < 3; i++) {
            Arrays.fill(dp[i], Long.MAX_VALUE);
        }
        dp[PREFIX][0] = a[0] % gcd == 0 ? 0 : B;
        for (int i = 1; i < n; i++) {
            if (dp[PREFIX][i - 1] < Long.MAX_VALUE) {
