                }
            }

            if (dp[REMOVED][i - 1] < Long.MAX_VALUE) {
                dp[REMOVED][i] = Math.min(dp[REMOVED][i], dp[REMOVED][i - 1] + A);
            }
            if (dp[PREFIX][i - 1] < Long.MAX_VALUE) {
                dp[REMOVED][i] = Math.min(dp[REMOVED][i], dp[PREFIX][i - 1] + A);
