                    dp[SUFFIX][i] = Long.MAX_VALUE;
                } else {
                    dp[SUFFIX][i] = Math.min(dp[SUFFIX][i], dp[PREFIX][i - 1] + (a[i] % gcd == 0 ? 0 : B));
                }
            }
        }
