import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

import geometry.Point;
import geometry.Vector;

public class CF_166_B_POLYGONS {

	static final double EPS = 10e-10;

	static double angle(Point a, Point o, Point b) {
		Vector oa = new Vector(o, a), ob = new Vector(o, b);
		return Math.acos(oa.dot(ob) / Math.sqrt(oa.norm2() * ob.norm2()));
	}

	static boolean ccw(Point p, Point q, Point r) {
		return new Vector(p, q).cross(new Vector(p, r)) > 0;
	}

	public static void main(String[] args) throws Exception {
		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();

		Point[] p = new Point[n + 1];

		for (int i = 0; i < n; i++)
			p[i] = new Point(sc.nextDouble(), sc.nextDouble());

		p[n] = p[0];

		int m = sc.nextInt();

		while (m-- > 0)
			if (!inPolygon(p, new Point(sc.nextDouble(), sc.nextDouble()))) {
				System.out.println("NO");
				return;
			}

		System.out.println("YES");

	}

	static boolean inPolygon(Point[] p, Point target) {
		int low = 1;
		int high = p.length - 1;

		boolean ccw = crossPrdouct(p[0], p[1], p[p.length - 1]) == 1;

		if(!ccw)
		{
			int temp = low ;
			low = high;
			high = temp;

		}

		while (Math.abs(low - high) > 1) {
				int mid = (low + high) /2;

				if (crossPrdouct(p[0], p[mid], target) > 0)
					low = mid;
				else
					high = mid;

			}


		return crossPrdouct(p[low], p[high],target ) >0;


	}

	static double crossPrdouct(Point p, Point q, Point r)
	{
		Vector pq = new Vector(p, q);
		Vector pr = new Vector(p, r);
		double cross = pq.cross(pr);

		if(Math.abs(cross) > EPS)
			return cross > 0 ? 1 : -1;

		return 0;


	}

	static class Vector {

		double x, y;

		Vector(double a, double b) {
			x = a;
			y = b;
		}

		Vector(Point a, Point b) {
			this(b.x - a.x, b.y - a.y);
		}

		Vector scale(double s) {
			return new Vector(x * s, y * s);
		} // s is a non-negative value

		double dot(Vector v) {
			return (x * v.x + y * v.y);
		}

		double cross(Vector v) {
			return x * v.y - y * v.x;
		}

		double norm2() {
			return x * x + y * y;
		}

		Vector reverse() {
			return new Vector(-x, -y);
		}

		Vector normalize() {
			double d = Math.sqrt(norm2());
			return scale(1 / d);
		}
	}

	static class Point implements Comparable<Point> {

		static final double EPS = 1e-9;

		double x, y;

		Point(double a, double b) {
			x = a;
			y = b;
		}

		public int compareTo(Point p) {
			if (Math.abs(y - p.y) > EPS)
				return y > p.y ? 1 : -1;

			return 0;
		}

		public double dist(Point p) {
			return Math.sqrt(sq(x - p.x) + sq(y - p.y));
		}

		boolean between(Point p, Point q)
		{
			return x < Math.max(p.x, q.x) + EPS && x + EPS > Math.min(p.x, q.x)
					&& y < Math.max(p.y, q.y) + EPS && y + EPS > Math.min(p.y, q.y);
		}

		static double sq(double x) {
			return x * x;
		}

	}

	static class Scanner {
		StringTokenizer st;
		BufferedReader br;

		public Scanner(InputStream s) {
			br = new BufferedReader(new InputStreamReader(s));
		}

		public String next() throws IOException {
			while (st == null || !st.hasMoreTokens())
				st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}

		public int nextInt() throws IOException {
			return Integer.parseInt(next());
		}

		public long nextLong() throws IOException {
			return Long.parseLong(next());
		}

		public String nextLine() throws IOException {
			return br.readLine();
		}

		public double nextDouble() throws IOException {
			String x = next();
			StringBuilder sb = new StringBuilder("0");
			double res = 0, f = 1;
			boolean dec = false, neg = false;
			int start = 0;
			if (x.charAt(0) == '-') {
				neg = true;
				start++;
			}
			for (int i = start; i < x.length(); i++)
				if (x.charAt(i) == '.') {
					res = Long.parseLong(sb.toString());
					sb = new StringBuilder("0");
					dec = true;
				} else {
					sb.append(x.charAt(i));
					if (dec)
						f *= 10;
				}
			res += Long.parseLong(sb.toString()) / f;
			return res * (neg ? -1 : 1);
		}

		public boolean ready() throws IOException {
			return br.ready();
		}

	}

}

