		Arrays.fill(cnt, -1);
		long ans=0;
		for(int i=0;i<=SA.idx;i++){
			long x=dfs(i);
			int cnt=SA.len[i]-SA.len[SA.link[i]];
			ans+=x*(x+1)*cnt/2;
		}
		pw.println(ans);
		pw.flush();
		pw.close();
	}
	static SuffixAutomaton SA;
	static boolean [] acceptState;
	static long [] cnt;

	static long dfs(int u){
		if(cnt[u]!=-1)
			return cnt[u];
		long ans=acceptState[u]? 1 : 0;
		for(Entry<Character, Integer> e : SA.nxt[u].entrySet()){
			int v=e.getValue();
			ans+=dfs(v);
		}
		return cnt[u]=ans;
	}

	static class SuffixAutomaton {
		int [] link,len;
		TreeMap<Character, Integer> [] nxt;
		int lst, idx;

		SuffixAutomaton(char [] s){
			int n=s.length;
			link=new int [n<<1];
			len=new int [n<<1];
			nxt=new TreeMap [n<<1];
			nxt[0]=new TreeMap<Character, Integer>();
			for(char c : s)
				addLeter(c);
		}

		void addLeter(char c){
			int cur = ++idx;
			int p=lst;
			while(!nxt[p].containsKey(c)){
				nxt[p].put(c, cur);
				p=link[p];
			}
			int q=nxt[p].get(c);

			// a node containing an edge with character c stopped me and it is not the root
			if(q!=cur){
				if(len[q]==len[p]+1)
					link[cur]=q;
				else{
					int clone=++idx;
					len[clone]=len[p]+1;
					link[clone]=link[q];
					nxt[clone]=new TreeMap<Character, Integer>(nxt[q]);
					link[cur]=link[q]=clone;
					while(nxt[p].get(c)==q){
						nxt[p].put(c, clone);
						p=link[p];
					}
				}
			}
			len[cur]=len[lst]+1;
			nxt[cur]=new TreeMap<Character, Integer>();
			lst=cur;
		}

	}

	static class MyScanner {
		BufferedReader br;
		StringTokenizer st;
		public MyScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}
