import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Stack;
import java.util.StringTokenizer;

public class D {
	static char[] s;
	static int n, cor[];
	static int[][][][] memo;
	static int mod = (int) 1e9 + 7;

	static int dp(int i, int j, int ci, int cj) {
		if (i >= j)
			return 1;
		if (memo[i][j][ci][cj] != -1)
			return memo[i][j][ci][cj];
		long res = 0;
		if(j != cor[i] || cj != 2)
			res = (res + 1l*dp(i+1, cor[i]-1, ci, 2)*dp(cor[i]+1, j, 2, cj)%mod) % mod;
		if(j != cor[i] || cj != 1)
			res = (res + 1l*dp(i+1, cor[i]-1, ci, 1)*dp(cor[i]+1, j, 1, cj)%mod) % mod;
		if(ci == 0){
			res = (res + 1l*dp(i+1, cor[i]-1, 1, 0)*dp(cor[i]+1, j, 0, cj)%mod) % mod;
			res = (res + 1l*dp(i+1, cor[i]-1, 2, 0)*dp(cor[i]+1, j, 0, cj)%mod) % mod;
		}
		else{
			res = (res + 1l*dp(i+1, cor[i]-1, ci==1?2:1, 0)*dp(cor[i]+1, j, 0, cj)%mod) % mod;
		}
//		System.out.println(i + " " + j + " " + ci + " " + cj + " " + res);
		return memo[i][j][ci][cj] = (int) res;
	}

	public static void main(String[] args) throws NumberFormatException, IOException {
		Scanner sc = new Scanner();
		PrintWriter out = new PrintWriter(System.out);
		s = sc.next().toCharArray();
		n = s.length;
		memo = new int[n + 1][n + 1][3][3];
		for (int[][][] i : memo)
			for (int[][] j : i)
				for (int[] k : j)
					Arrays.fill(k, -1);
		cor = new int[n];
		Stack<Integer> st = new Stack<>();
		for (int i = 0; i < s.length; i++) {
			if (s[i] == '(')
				st.add(i);
			else {
				int tmp = st.pop();
				cor[i] = tmp;
				cor[tmp] = i;
			}
		}
//		System.out.println(Arrays.toString(cor));
		out.println(dp(0, n-1, 0, 0));
		out.flush();
		out.close();
	}

	static class Scanner {
		BufferedReader bf;
		StringTokenizer st;

		public Scanner() {
			bf = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() throws IOException {
			while (st == null || !st.hasMoreTokens())
				st = new StringTokenizer(bf.readLine());
			return st.nextToken();
		}

		public int nextInt() throws NumberFormatException, IOException {
			return Integer.parseInt(next());
		}

		public double nextDouble() throws NumberFormatException, IOException {
			return Double.parseDouble(next());
		}

		public long nextLong() throws NumberFormatException, IOException {
			return Long.parseLong(next());
		}
	}
}

