import java.io.*;
import java.util.*;

public class D
{
    private static int [] pair;
    private static final int MOD = 1000000000 + 7;
    private static long [][][][] memo;
    public static void main(String[] strings) throws IOException
    {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        char [] str = reader.readLine().toCharArray();
        int n = str.length;
        int [] last = new int[n/2+1];
        Arrays.fill(last, -1);

        pair = new int[n];
        int sum = 0;
        for(int i = 0 ; i < n ; i++)
        {
            sum += str[i] == '(' ? 1 : -1;
            if(str[i] == ')')
            {
                pair[last[sum+1]] = i;
                pair[i] = last[sum+1];
            }
            else
                last[sum] = i;
        }

        memo = new long[n][n][3][3];
        for(long [][][] fill1 : memo)
            for(long [][] fill2 : fill1)
                for(long [] fill3 : fill2)
                    Arrays.fill(fill3, -1);

        long res = rec(0, n-1, 2, 2);
        System.out.println(res);
    }

    private static long rec(int left, int right, int pLeft, int pRight)
    {
        if(left > right)
            return 1;

        if(memo[left][right][pLeft][pRight] != -1)
            return memo[left][right][pLeft][pRight];

        int mid = pair[left];
        long res = 0;

        res += (pLeft*(rec(left+1, mid-1, 1, 2) * rec(mid+1, right, 2, pRight))%MOD)%MOD;
        res %= MOD;
        res += ((right == mid ? pRight : 2)*(rec(left+1, mid-1, 2, 1) * rec(mid+1, right, 1, pRight))%MOD)%MOD;
        res %= MOD;

        return memo[left][right][pLeft][pRight] = res;
    }
}

