    def inter_ask(self, lst):
        # CFäº¤äºé¢è¾åºè¯¢é®å¹¶è¯»åç»æ
        self.st(lst)
        sys.stdout.flush()
        res = self.read_int()
        # è®°å¾ä»»ä½ä¸ä¸ªè¾åºä¹åé½è¦ sys.stdout.flush() å·æ°
        return res

    def inter_out(self, lst):
