class SegmentTreeUpdateQueryMin:
    # æ¨¡æ¿ï¼çº¿æ®µæ åºé´æ´æ°ãæç»­åå°æå°å¼
    def __init__(self, n):
        self.height = [inf]*(4*n)
        self.lazy = [inf]*(4*n)
        self.n = n

    def build(self, nums: List[int]):
        # ä½¿ç¨æ°ç»åå§åçº¿æ®µæ 
        stack = [[0, self.n - 1, 1]]
        while stack:
            s, t, ind = stack.pop()
            if ind >= 0:
                if s == t:
                    self.make_tag(ind, nums[s])
                else:
                    stack.append([s, t, ~ind])
                    m = s + (t - s) // 2
                    stack.append([s, m, 2 * ind])
                    stack.append([m + 1, t, 2 * ind + 1])
            else:
                ind = ~ind
                self.push_up(ind)
        return

    def get(self):
        # æ¥è¯¢åºé´çææå¼
        stack = [[0, self.n-1, 1]]
        nums = [inf]*self.n
        while stack:
            s, t, i = stack.pop()
            if s == t:
                nums[s] = self.height[i]
                continue
            m = s + (t - s) // 2
            self.push_down(i)
            stack.append([s, m, 2 * i])
            stack.append([m + 1, t, 2 * i + 1])
        return nums

    @staticmethod
    def min(a, b):
        return a if a < b else b

    def push_down(self, i):
        # ææ è®°ä¸æ¾ï¼æ³¨æåæå°å¼
        if self.lazy[i] != inf:
            self.height[2 * i] = self.min(self.height[2 * i], self.lazy[i])
            self.height[2 * i + 1] = self.min(self.height[2 * i + 1], self.lazy[i])

            self.lazy[2 * i] = self.min(self.lazy[2 * i], self.lazy[i])
            self.lazy[2 * i + 1] = self.min(self.lazy[2 * i + 1], self.lazy[i])

            self.lazy[i] = inf
        return

    def make_tag(self, i, val):
        self.height[i] = self.min(self.height[i], val)
        self.lazy[i] = self.min(self.lazy[i], val)
        return

    def push_up(self, i):
        self.height[i] = self.min(self.height[2 * i], self.height[2 * i + 1])
        return

    def update_range(self, left, right, s, t, val, i):
        # æ´æ°åºé´æå°å¼
        stack = [[s, t, i]]
        while stack:
            a, b, i = stack.pop()
            if i >= 0:
                if left <= a and b <= right:
                    self.make_tag(i, val)
                    continue

                self.push_down(i)
                stack.append([a, b, ~i])
                m = a + (b - a) // 2
                if left <= m:  # æ³¨æå·¦å³å­æ çè¾¹çä¸èå´
                    stack.append([a, m, 2 * i])
                if right > m:
                    stack.append([m + 1, b, 2 * i + 1])
            else:
                i = ~i
                self.push_up(i)
        return

    def update_point(self, left, right, s, t, val, i):
        # æ´æ°åç¹æå°å¼
        while True:
            if left <= s and t <= right:
                self.make_tag(i, val)
                break
            self.push_down(i)
            m = s + (t - s) // 2
            if left <= m:  # æ³¨æå·¦å³å­æ çè¾¹çä¸èå´
                s, t, i = s, m, 2 * i
            if right > m:
                s, t, i = m + 1, t, 2 * i + 1

        while i > 1:
            i //= 2
            self.push_up(i)
        return

    def query_range(self, left, right, s, t, i):
        # æ¥è¯¢åºé´çæå°å¼
        stack = [[s, t, i]]
        floor = inf
        while stack:
            a, b, i = stack.pop()
            if left <= a and b <= right:
                floor = self.min(floor, self.height[i])
                continue
            self.push_down(i)
            m = a + (b - a) // 2
            if left <= m:
                stack.append([a, m, 2*i])
            if right > m:
                stack.append([m+1, b, 2*i + 1])
        return floor

    def query_point(self, left, right, s, t, i):
        # æ¥è¯¢åç¹çæå°å¼
        a, b, i = s, t, i
        while True:
            if left <= a and b <= right:
                ans = self.height[i]
                break
            self.push_down(i)
            m = a + (b - a) // 2
            if left <= m:
                a, b, i = a, m, 2 * i
            if right > m:
                a, b, i = m + 1, b, 2 * i + 1
        return ans

class Solution:
    def __init__(self):
        return

    @staticmethod
    def main(ac=FastIO()):
        n, k = ac.read_list_ints()
        s = ac.read_str()
        tree = SegmentTreeUpdateQueryMin(n)
        one = -1
        for i in range(n):
            if s[i] == "1":
                left = ac.max(0, i-k)
                right = ac.min(n-1, i+k)
                if left < one:
                    left = one+k+1
                if left > i:
                    left = i
                pre = tree.query_range(left-1, left-1, 0, n-1, 1) if left else 0
                cur = pre + i+1
                tree.update_range(i, right, 0, n-1, cur, 1)
                one = i
            else:
                pre = tree.query_point(i-1, i-1, 0, n-1, 1) if i else 0
                cur = pre + i+1
                tree.update_point(i, i, 0, n-1, cur, 1)
        ac.st(tree.query_point(n-1, n-1, 0, n-1, 1))
        return


Solution().main()

