#define M  100000
struct card{
       int f;
       int b;
       int g; 
       }card[M];
struct color{
       int c;
       int num;
       int same;
       }front[M];
struct color1{
       int c;
       int num;
       }back[M];   
int cmp1(const void *a,const void *b){
    struct card *c=(struct card *)a;
    struct card *d=(struct card *)b;
    return c->f-d->f;
}
int cmp2(const void *a,const void *b){
    struct card *c=(struct card *)a;
    struct card *d=(struct card *)b;
    return c->b-d->b;
}
int cmp3(const void *a,const void *b){
    struct color *c=(struct color *)a;
    struct color *d=(struct color *)b;
    return d->num-c->num;
}
int main(){
    int N,i,j,t,k,fnum,bnum,move,min,same,count;
    while(scanf("%d",&N),N){
        memset(card,0,sizeof(card));
        memset(front,0,sizeof(front));
        memset(back,0,sizeof(back));
        for(i=0;i<N;i++){
            scanf("%d %d",&card[i].f,&card[i].b);
            if(card[i].f==card[i].b)card[i].g=1;
            else card[i].g=0;
        }
        qsort(card,N,sizeof(card[0]),cmp1); 
        t=1;j=0;
        for(i=1;i<N;i++)
            if(card[i].f==card[i-1].f) t++;
            else {
                front[j].c=card[i-1].f;
                front[j].num=t;
                same=0;
                for(k=i-t;k<i;k++){if(card[k].g==1)same++;}
                front[j++].same=same;
                t=1;
            }
        front[j].c=card[i-1].f;front[j].num=t;
        fnum=j+1;
        qsort(card,N,sizeof(card[0]),cmp2);
        t=1;j=0;
        for(i=1;i<N;i++)
            if(card[i].b==card[i-1].b)   t++;
            else {
                back[j].c=card[i-1].b;
                back[j++].num=t;
                t=1;
            }
        back[j].c=card[i].b;back[j].num=t;
        bnum=j+1;
        qsort(front,fnum,sizeof(front[0]),cmp3);
        min=N;move=N;
        for(i=0;i<fnum;i++){
            if(front[i].num>=(N+1)/2){ move=0;break;}
            else{
                for(j=0;j<bnum;j++)
                    if(back[j].c==front[i].c){
                        count=back[j].num+front[i].num-front[i].same;
                        if(count>=(N+1)/2)move=back[j].num-front[i].same;
                        if(move<min)min=move;
                        break;
                    }
            }
        }
        if(move==0)printf("%d\n",move);
        else if(move==N)printf("-1\n");
        else printf("%d\n",min);
    }
    return 0;
}

