#define oo 1000000000
#define pi 3.14159265359
#define zero(a) (abb(a)<=1e-7)
#define lowbit(a) ((a)&(-(a)))
#define min(a,b) ((a)<(b)?(a):(b))
#define max(a,b) ((a)>(b)?(a):(b))
#define abb(a) ((a)>0?(a):(-(a)))
#define cj(x1,y1,x2,y2) ((x1)*(y2)-(x2)*(y2))
#define dj(x1,y1,x2,y2) ((x1)*(y1)+(y1)*(y2))
#define dis(x1,y1,x2,y2) sqrt(((x2)-(x1))*((x2)-(x1))+((y2)-(y1))*((y2)-(y1)))

long min[1001]={0},rec[1001]={0},ed[1001][2]={0},post[1001]={0},f[1001]={0},stay[1001][1001]={0},ps[1001]={0},head[1001]={0},e[2001]={0},next[2001]={0},v[2001]={0};
char str[15]={0},th[1001][1001]={0},town[1001][1001]={0},hash[1001][1001]={0},own[1001][1001]={0},name[1001][15]={0};
long n,m,totm=0,flag=0;

void add(long a,long b,long c)
{
   e[++totm]=b;
   next[totm]=head[a];
   head[a]=totm;
   v[totm]=c;
}

long getf(long now)
{
   if (f[now]==now)
      return now;
   return f[now]=getf(f[now]);
}

void dfs(long now,long x)
{
   long i,j,fa;
   hash[x][now]=1;
   stay[now][++ps[now]]=x;
   flag++;
   for (i=1;i<ps[now];i++)
      if (x!=(fa=getf(stay[now][i])))
      {
         f[fa]=x;
         for (j=1;j<=m;j++)
            if (own[fa][j]&&!own[x][j])
            {
               own[x][j]=1;
               rec[j]=flag;
            }
         for (j=1;j<=n;j++)
            hash[x][j]|=hash[fa][j];
      }
   for (i=1;i<=m;i++)
      if (rec[i]==flag)
      {
         if (hash[x][ed[i][0]]&&!hash[x][ed[i][1]])
            dfs(ed[i][1],x);
         else if (hash[x][ed[i][1]]&&!hash[x][ed[i][0]])
            dfs(ed[i][0],x);
      }
   for (i=head[now];i;i=next[i])
      if (!hash[x][e[i]]&&own[x][v[i]])
         dfs(e[i],x);
}

