long long cross2(long long x1, long long y1, long long x2, long long y2) {
	return x1 * y2 - x2 * y1;
}

struct P {
	int x, y;
} *pl, *pr;

typedef struct P *T[(X + X + 1) * 4];

long long cross(struct P *o, struct P *p, struct P *q) {
	return cross2(p->x - o->x, p->y - o->y, q->x - o->x, q->y - o->y);
}

struct P *min(struct P *p, struct P *q) {
	return p != NULL && q != NULL ? (p->x < q->x ? p : q) : (p == NULL ? q : p);
}

struct P *max(struct P *p, struct P *q) {
	return p != NULL && q != NULL ? (p->x > q->x ? p : q) : (p == NULL ? q : p);
}

void update(T tl, T tr, int k, int l, int r, int x, struct P *p) {
	int m;

	if (r - l == 1) {
		tl[k] = tr[k] = p;
		return;
	}
	m = (l + r) / 2;
	if (x < m)
		update(tl, tr, k * 2 + 1, l, m, x, p);
	else
		update(tl, tr, k * 2 + 2, m, r, x, p);
	tr[k] = min(tr[k * 2 + 1], tr[k * 2 + 2]);
	tl[k] = max(tl[k * 2 + 1], tl[k * 2 + 2]);
}

void query(T tl, T tr, int k, int l, int r, int x) {
	int m;

	if (r - l == 1) {
		pl = max(pl, tl[k]);
		pr = min(pr, tr[k]);
		return;
	}
	m = (l + r) / 2;
	if (x < m) {
		pr = min(pr, tr[k * 2 + 2]);
		query(tl, tr, k * 2 + 1, l, m, x);
	} else {
		pl = max(pl, tl[k * 2 + 1]);
		query(tl, tr, k * 2 + 2, m, r, x);
	}
}

int query_(T tl_up, T tr_up, T tl_dn, T tr_dn, struct P *p, int insert) {
	struct P *q;
	int inside = 1;

	pl = pr = NULL;
