	return *((int*)a)-*((int*)b);
}

int a[200], n, k;
LL dp[2][201][1001];
const LL mod=1000000007;

LL get(int i, int num, int s){
	if(s>k || num<0) return 0;
	return dp[i&1][num][s];
}

int main(){
	int i, j, l, add;
	scanf("%d %d", &n, &k);
	for(i=0;i<n;++i) scanf("%d", a+i);
	for(i=0;i<=k;++i) dp[n&1][0][i]=1;
	for(i=1;i<=n;++i) for(j=0;j<=k;++j) dp[n&1][i][j]=0;
	qsort(a, n, sizeof(int), comp);
	for(i=n-1;i>0;--i){
		for(j=0;j<=n;++j){
			add=j*(a[i]-a[i-1]);
			for(l=0;l<=k;++l){
				dp[i&1][j][l]=(get(i+1, j+1, l+add)+j*get(i+1, j-1, l+add)+
						(j+1)*get(i+1, j, l+add))%mod;
			}
		}
	}
	printf("%I64d\n", (get(1, 1, 0)+get(1, 0, 0))%mod);
	return 0;
}

