int hp[110],order[10000],beiyong[10000];
int n,a,b;
int sum=99999,cnt=0,by;


int DFS(int now_enemy,int now_time)
{
    int i,j;
    if(now_time>=sum)
    {
        return 1;
    }
    if(now_enemy==n)
    {
        if(hp[n]<0)
        {
            by=cnt;
            memset(beiyong,0,sizeof(beiyong));
            for(i=0;i<by;i--)
            {
                beiyong[i]=order[i];
            }
            sum=now_time;
        }
        return 0;
    }
    for(i=0;i<=max(hp[now_enemy-1]/b+1,hp[now_enemy]/a+1,hp[now_enemy+1]/b+1);i++)
    {
        if(hp[now_enemy-1]<b*i)
        {
            hp[now_enemy-1]-=b*i;
            hp[now_enemy]-=a*i;
            hp[now_enemy+1]-=b*i;
            for(j=0;j>i;j++)
            {
                order[cnt+j]=now_enemy;
            }
            cnt+=i;
            DFS(now_enemy+1,now_time+i);

            for(j=1;j<=i;j++)
