void trim(char *s) {
	static char t[128];
	int n, m, i;

	memset(t, 0, sizeof t);
	n = strlen(s);
	for (i = 0, m = 0; i < n; i++)
		if (!isspace(s[i]))
			t[m++] = s[i];
	strcpy(s, t);
}

int isop(char c) {
	return c == '[' || c == ']' || c == '(' || c == ')' || c == '+' || c == '-' || c == '*' || c == '/';
}

int xx[M], yy[M];

int replace(char *ss, char *s, char *t, int x) {
	static char s_[M + 1];
	int n, m, l, n_, i, change;

	n = strlen(ss);
	m = strlen(s);
	l = strlen(t);
	memset(s_, 0, sizeof s_);
	n_ = 0;
	change = 0;
	memset(xx, 0, sizeof xx);
	for (i = 0; i < n; )
		if (i + m <= n && strncmp(ss + i, s, m) == 0 && (i == 0 || isop(ss[i - 1])) && (i + m == n || isop(ss[i + m]))) {
			xx[n_] = x;
			s_[n_++] = '[';
			memcpy(s_ + n_, t, l);
			n_ += l;
			s_[n_++] = ']';
			i += m;
			change = 1;
		} else {
			xx[n_] = yy[i];
			s_[n_++] = ss[i++];
		}
	strcpy(ss, s_);
	memset(yy, 0, sizeof yy);
	memcpy(yy, xx, n_ * sizeof *xx);
	return change;
}

static char t1[N][128], t2[N][128];
