				aa[x] = bb[x] = cc[x] = 0;
				return;
			}
			if (bb[x_] && cnt_ == 0)
				bb[x] = 1;
			if (cc[x_] && cnt_ == 0)
				cc[x] = 1;
		}
		if ((ss[j] == '+' || ss[j] == '-') && cnt_ == 0)
