#include <stdio.h>

#define N	19

int bcnt(int x) {
	return x == 0 ? 0 : bcnt(x & (x - 1)) + 1;
}

int main() {
	static int adj[N][N], dp[1 << N][N];
	int n, m, i_, h, i, j, v, cnt;

	scanf("%d%d", &n, &m);
	while (m-- > 0) {
		scanf("%d%d", &i, &j);
		i--, j--;
		adj[i][j] = adj[j][i] = 1;
	}
	cnt = 0;
	for (i_ = 0; i_ < n; i_++) {
		for (v = 1 << (i_ + 1); v < 1 << n; v += 1 << (i_ + 1))
			for (i = i_ + 1; i < n; i++)
				dp[v][i] = 0;
		for (i = i_ + 1; i < n; i++)
			if (adj[i_][i])
				dp[1 << i][i] = 1;
		for (h = 1; h <= n - i_ - 1; h++)
			for (v = 1 << (i_ + 1); v < 1 << n; v += 1 << (i_ + 1))
				if (bcnt(v) == h)
					for (i = i_ + 1; i < n; i++)
						for (j = i_ + 1; j < n; j++)
							if ((v & 1 << j) == 0 && adj[i][j])
								dp[v | (1 << j)][j] += dp[v][i];
		for (v = 1 << (i_ + 1); v < 1 << n; v += 1 << (i_ + 1))
			if (bcnt(v) > 1)
				for (i = i_ + 1; i < n; i++)
					if ((v & 1 << i) > 0 && adj[i_][i])
						cnt += dp[v][i];
	}
	printf("%d\n", cnt / 2);
	return 0;
}

