    class Program
    {
        static List<int> roots = new List<int>(); 
        static bool[,] graph;
        static bool[,] graph2;
        static bool[] used;
        static int n;
        static int count;
        static int cycleCount = 0;

        static void Main(string[] args)
        {
            string[] str = Console.ReadLine().Split(' ');
            n = int.Parse(str[0]);
            int m = int.Parse(str[1]);
            used = new bool[n];
            graph = new bool[n, n];
            graph2 = new bool[n, n];
            int a;
            int b;

            for (int i = 0; i < m; i++)
            {
                str = Console.ReadLine().Split(' ');
                a = int.Parse(str[0]) - 1;
                b = int.Parse(str[1]) - 1;
                graph[a, b] = true;
                graph[b, a] = true;
            }

            Solve();

            if (cycleCount == 1 && count == 1)
            {
                Console.WriteLine("FNTAGN!");
            } else
            {
                Console.WriteLine("NO");
            }
        }

        static void Solve()
        {
            used = new bool [n];
            count = 0;

            for (int i = 0; i < n; i++)
            {
                if (!used[i])
                {
                    count++;
                    DFS(i);
                }
            }
        }

        static void DFS(int v) 
        {
            used[v] = true;
            for (int j = 0; j < n; j++)
            {
                if (j != v && used[j] && graph[v, j] && !graph2[v,j])
                {
                    cycleCount++;
                }
                graph2[v, j] = true;
                graph2[j, v] = true;
                if (!used[j] && graph[v,j])
                {
                    DFS(j);
                }
            }
        }
    }
}

