namespace ProgrammingContest.Codeforces.Round80
{
    class B
    {
        static int[] ReadInts() { return Console.ReadLine().Split(' ').Select<string, int>(int.Parse).ToArray(); }

        static bool[] used;
        static List<int>[] e;
        static Stack<int> vis = new Stack<int>();
        static HashSet<int> roots = new HashSet<int>();
        static bool find;
        static int count = 0;

        static int edge(int u, int v) { return Math.Max(u, v) * 1000 + Math.Min(u, v); }

        static bool dfs(int idx)
        {
            int prev = vis.Any() ? vis.Peek() : -1;
            used[idx] = true;
            count++;
            vis.Push(idx);
            //Console.Write("edge: {0}:", idx + 1);
            //foreach (int i in e[idx])                Console.Write(" {0}", i + 1);
            //Console.WriteLine();
            foreach (int i in e[idx])
            {
                //Console.WriteLine("checked: {0} -> {1}", idx+1, i+1);
                if (!used[i])
                {
                    if (!dfs(i))
                        return false;
                }
                else if (prev != i)
                {
                    //Console.WriteLine("prev: {0} != {1}", prev+ 1, i + 1);
                    if (find)
                    {
                        //Console.WriteLine("infind: {0}", roots.Contains(edge(idx, i)));
                        if (!roots.Contains(edge(idx, i)))
                            return false;
                        continue;
                    }
                    find = true;
                    List<int> xs = new List<int>();
                    foreach (var v in vis)
                    {
                        xs.Add(v);
                        if (v == i)
                            break;
                    }
                    for (int j = 0; j < xs.Count; j++)
                    {
                        //Console.WriteLine("check: {0} {1}", xs[j], xs[j+1]);
                        roots.Add(edge(xs[j], xs[(j + 1) % xs.Count]));
                    }
                }
            }
            vis.Pop();
            return true;
        }

        static void Main()
        {
            var xs = ReadInts();
            int n = xs[0],
                m = xs[1];

            used = new bool[n];
            e = new List<int>[n];
            for (int i = 0; i < n; i++)
                e[i] = new List<int>();

            for (int i = 0; i < m; i++)
            {
                xs = ReadInts();
                for (int j = 0; j < 2; j++)
                    e[xs[j] - 1].Add(xs[j ^ 1] - 1);
            }

            Console.WriteLine(dfs(0) && find && count==n ? "FHTAGN!" : "NO");
        }
    }
}

