using System;
using System.Collections.Generic;
using System.Collections;
using System.Linq;
using System.Numerics;




namespace contest
{

    class contest
    {


        static void Main(string[] args)
        {


            //int n = int.Parse(Console.ReadLine());
            //var input = Console.ReadLine().Split().Select(int.Parse).ToArray();

            //var num = Console.ReadLine().Split().Select(int.Parse).ToArray();



            //int n = int.Parse(Console.ReadLine());
            //var num = Console.ReadLine().Split().Select(int.Parse).ToArray();


            var n = int.Parse(Console.ReadLine());
            var input = new int[n][];

            var front = new Dictionary<int, int>();
            var back = new Dictionary<int, int>();
            var memo = new Dictionary<Tuple<int, int>, int>();
            for(int i =0; i< n; i++)
            {
                input[i] = Console.ReadLine().Split().Select(int.Parse).ToArray();
                int l = input[i][0];
                int r = input[i][1];

                if (!front.Keys.Contains(l)) front[l] = 1;
                else front[l]++;

                if (!back.Keys.Contains(r)) back[r] = 1;
                else back[r]++;

                if (!memo.Keys.Contains(Tuple.Create(l,r))) memo[Tuple.Create(l,r)]=1;
                else memo[Tuple.Create(l, r)]++;

            }

            int num = n / 2 + n % 2;
            int turn = int.MaxValue;

            foreach(var item in front)
            {
                if (item.Value >= num)
                {
                    turn = 0;
                    break;
                }
                else if(back.Keys.Contains(item.Key))
                {
                    int tmp = 0;
                    if(memo.Keys.Contains(Tuple.Create(item.Key, item.Key)))
                    {
                        tmp = memo[Tuple.Create(item.Key, item.Key)];
                    }

                    if(item.Value + back[item.Key]-tmp >= num)
                    {
                        turn = Math.Min(turn , num - item.Value);
                    }

                }
            }

            foreach (var item in back)
            {
                if (item.Value >= num)
                {
                    turn = Math.Min(turn, item.Value);

                }

                if (front.Keys.Contains(item.Key))
                {
                    int tmp = 0;
                    if (memo.Keys.Contains(Tuple.Create(item.Key, item.Key)))
                    {
                        tmp = memo[Tuple.Create(item.Key, item.Key)];
                    }

                    if (item.Value + front[item.Key] - tmp >= num)
                    {
                        turn = Math.Min(turn, item.Value-tmp);
                    }

                }
            }


            if (turn == int.MaxValue) turn = -1;

            Console.WriteLine(turn);




        }



    }




}

