using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading;
using System.Globalization;

namespace Codeforces
{
    class Program
    {        
        static int ReadInt()
        {
            return Int32.Parse(Console.ReadLine());
        }
        static long ReadLong()
        {
            return long.Parse(Console.ReadLine());
        }
        static void ReadIntArray(out int[] array, char separator = ' ')
        {
            var input = Console.ReadLine().Split(separator);
            array = new int[input.Length];
            for (int i = 0; i < input.Length; i++)
            {
                array[i] = Int32.Parse(input[i]);
            }

        }

        static int ReadNextInt(string input, int index)
        {
            var ints = input.Split(' ');
            return Int32.Parse(ints[index]);
        }


        static void Main()
        {
            var input = Console.ReadLine();
            var n = ReadNextInt(input, 0);
            var m = ReadNextInt(input, 1);

            var players = new Dictionary<int, string>();
            var enemies = new Dictionary<string, List<string>>();
            for (int i = 0; i < n; i++)
            {
                players.Add(i, Console.ReadLine()); 
            }
            for (int i = 0; i < m; i++)
            {
                var pair = Console.ReadLine().Split(' ');
                if (!enemies.ContainsKey(pair[0]))
                    enemies[pair[0]] = new List<string>();
                enemies[pair[0]].Add(pair[1]);
                if (!enemies.ContainsKey(pair[1]))
                    enemies[pair[1]] = new List<string>();
                enemies[pair[1]].Add(pair[0]);
            }
            int res = 0;
            var resPlaers = new List<string>();
            var maxPlayers = new List<string>();
            int c = 1 << n;
            int count = 0;
            bool isGood = true;
            while (--c > 0)
            {
                count = 0;
                isGood = true;
                resPlaers.Clear();
                for (int i = 0; i < n; i++)
                {
                    if ((c & (1 << i)) == 0)
                        continue;

                    count++;
                    resPlaers.Add(players[i]);

                    for (int j = i + 1; j < n; j++)
                    {
                        if ((c & (1 << j)) == 0)
                            continue;

                        if (enemies.ContainsKey(players[i]) && enemies[players[i]].Contains(players[j]))
                        {
                            isGood = false;
                            break;
                        }
                    }

                    if (!isGood)
                        break;
                }
                if (isGood)
                {
                    if (res < count)
                    {
                        res = count;
                        maxPlayers.Clear();
                        maxPlayers.AddRange(resPlaers);
                    }
                }
            }
            Console.WriteLine(res);           
            maxPlayers.Sort(StringComparer.Create(CultureInfo.InvariantCulture, true));
            foreach (var player in maxPlayers)
                Console.WriteLine(player);
        }
    }
}

