            outputStream.Close();
        }

        void IDisposable.Dispose()
        {
            Close();
        }
    }
    #endregion

    class Program
    {
        #region Program
        MyIo io;

        public Program(MyIo io)
        {
            this.io = io;
        }

        static void Main(string[] args)
        {
#if  LOCAL_TEST
            using (MyIo io = new MyIo(new StreamReader("input.txt")))
#else
                using (MyIo io = new MyIo(System.Console.In))
#endif

            {
                new Program(io)
                    .Solve();

#if  LOCAL_TEST
                Console.ReadLine();
#endif
            }
        }



        #endregion


        public class LexComparer : IComparer<string>
        {
            private static readonly LexComparer lc = new LexComparer();

            public static LexComparer Instance
            {
                get
                {
                    return lc;
                }
            }

            public int Compare(string x, string y)
            {
                for (int i = 0; i < Math.Min(x.Length, y.Length); i++)
                {
                    if (x[i] == y[i])
                        continue;

                    return Comparer.Default.Compare(x[i], y[i]);
                }

                return Comparer.Default.Compare(x.Length, y.Length);
            }
        }


        void Solve()
        {
            int n = io.NextInt();
            int m = io.NextInt();




            List<string> names = new List<string>();


            for (int i = 0; i < n; i++)
                names.Add(io.NextString());

            names.Sort(LexComparer.Instance);



            int[] sts = new int[n];

            for (int i = 0; i < n; i++)
                sts[i] = (1 << (n + 1)) - 1;

            for (int i = 0; i < m; i++)
            {
                int x = names.BinarySearch(io.NextString(), LexComparer.Instance);
                int y = names.BinarySearch(io.NextString(), LexComparer.Instance);

                sts[x] &= ~(1 << y);
                sts[y] &= ~(1 << x);
            }


            int di = 0;
            int dz = 0;


            for (int i = 1 << n; i > 0; i--)
            {
                int xi = i;

                int z = 0;

                bool candidate = true;

                for (int j = 0; j < n; j++)
                {
                    if (xi % 2 > 0)
                    {
                        z++;

                        if ((i & sts[j]) != i)
                        {
                            candidate = false;
                            break;
                        }
                    }
                    xi >>= 1;    
                }

                if (candidate && z >= dz)
                {
                    dz  = z;
                    di = i;
                }
            }


            if (dz > 0)
            {
                io.PrintLine(dz);

                for (int i = 0; i < n; i++)
			    {
                    if (((1 << i) & di) > 0)
                        io.PrintLine(names[i]);
                }
            }
        }


    }
}

