using System.IO;

namespace codeforces_43_B
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.SetIn(new StreamReader("input.txt"));
            StringBuilder letter = new StringBuilder(Console.ReadLine().Trim());
            StringBuilder message = new StringBuilder(Console.ReadLine().Trim());

            Dictionary<char, uint> dict = new Dictionary<char, uint>();
            int i = -1;
            while (i < letter.Length-1)
            {
                i++;
                if (letter[i] == ' ')
                    continue;
                char curChar = letter[i];
                if (dict.ContainsKey(curChar))
                {
                    dict[curChar]++;
                }
                else
                {
                    dict.Add(curChar, 0);
                }
            }
            bool canWrite = true;
            int j = -1;
            while (j < message.Length-1)
            {
                j++;
                if (message[j] == ' ')
                    continue;
                char curChar = message[j];
                if (!dict.ContainsKey(curChar))
                {
                    canWrite = false;
                    break;
                }
                else
                {
                    dict[curChar]--;
                }
            }
            foreach (char curChar in dict.Keys)
                if (dict[curChar] < 0)
                {
                    canWrite = false;
                    break;
                }
            Console.Write((canWrite) ? "YES" : "NO");
            Console.ReadKey();
        }
    }
}

