namespace Problems
{
    class _8A
    {
        public static  void  Main()
        {
            var forward = "forward";
            var backward = "backward";
            var both = "both";
            var fantasy = "fantasy";
            var len = 25000;
            var stations = new string('a', len * 2) + new string('b', len*2);
            var a = new string('a', len);
            var b = new string('b', len);
            //var stations = Console.ReadLine();
            //var a = Console.ReadLine();
            //var b = Console.ReadLine();
            var forw = (IsSequencePossible(stations, a, b));
            //var back = (IsSequencePossible(Reverse(stations), a, b));
            var back = (IsRevSequencePossible(stations, a, b));

            if (forw && back)
            {
                Console.WriteLine(both);
            }
            else
            {
                if (forw) Console.WriteLine(forward);
                else if (back) Console.WriteLine(backward);
                else Console.WriteLine(fantasy);
            }

        }

        private static string Reverse(string s)
        {
            Console.WriteLine(" start Reverse " + DateTime.Now.Second + " " + DateTime.Now.Millisecond);
            string result = string.Empty;
            for (int i = s.Length - 1; i >= 0; i-- )
            {
                result += s[i];
            }
            //Console.WriteLine(" end Reverse " + DateTime.Now.Second + " " + DateTime.Now.Millisecond);
            return result;
        }

        private static bool IsSequencePossible(string stations, string a, string b)
        {

            var result = false;
            var ind = FindSubstring(stations, a);
            if (ind > -1)
            {
                Console.WriteLine(" start Substring " + DateTime.Now.Second + " "+ DateTime.Now.Millisecond);
                stations = stations.Substring(ind + a.Length);
                Console.WriteLine(" ebd Substring " + DateTime.Now.Second + " " + DateTime.Now.Millisecond);
                if (FindSubstring(stations, b) > -1)
                {
                    result = true;
                }
            }
            return result;
        }
        private static bool IsRevSequencePossible(string stations, string a, string b)
        {

            var result = false;
            var ind = FindRevSubstring(stations, a);
            if (ind > -1)
            {
                Console.WriteLine(" start Substring " + DateTime.Now.Second + " " + DateTime.Now.Millisecond);
                stations = stations.Substring(ind + a.Length);
                Console.WriteLine(" ebd Substring " + DateTime.Now.Second + " " + DateTime.Now.Millisecond);
                if (FindRevSubstring(stations, b) > -1)
                {
                    result = true;
                }
            }
            return result;
        }
        private static int FindSubstring(string s, string a)
        {
            Console.WriteLine(" start FindSubstring " + DateTime.Now.Second + " " + DateTime.Now.Millisecond);
            if (s.Length < a.Length) return -1;
            ulong x = 257;
            ulong xn = 1;
            for (int i = 1; i < a.Length; i++)
            {
                xn = xn * x;
            }

            ulong ha = 0;
            for (int i = 0; i < a.Length; i++)
            {
                ha = ha * x + a[i];
            }

            ulong hs = 0;
            for (int i = 0; i < a.Length; i++)
            {
                hs = hs * x + s[i];
            }

            if (hs == ha) return 0;

            for(int i = a.Length; i < s.Length; i++)
            {
                hs = (hs - xn*s[i - a.Length]) * x + s[i];
                if (hs == ha) return i-a.Length+1;
            }

            return -1;
        }

        private static int FindRevSubstring(string s, string a)
        {
            Console.WriteLine(" start FindSubstring " + DateTime.Now.Second + " " + DateTime.Now.Millisecond);
            if (s.Length < a.Length) return -1;
            ulong x = 257;
            ulong xn = 1;
            for (int i = 1; i < a.Length; i++)
            {
                xn = xn * x;
            }

            ulong ha = 0;
            for (int i = 0; i < a.Length; i++)
            {
                ha = ha * x + a[i];
            }

            ulong hs = 0;
            for (int i = s.Length-1; i >= 0 ; i--)
            {
                hs = hs * x + s[i];
            }

            if (hs == ha) return 0;

            for (int i = s.Length-1-a.Length; i >= 0; i--)
            {
                hs = (hs - xn * s[i + a.Length]) * x + s[i];
                if (hs == ha) return i + a.Length - 1;
            }

            return -1;
        }
    }
}

