﻿using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;

namespace CF317
{
	internal class Program
	{
		private static void Main(string[] args)
		{
			var sr = new InputReader(Console.In);
			//var sr = new InputReader(new StreamReader("input.txt"));
			var task = new Task();
			using (var sw = Console.Out)
				//using (var sw = new StreamWriter("output.txt"))
			{
				task.Solve(sr, sw);
				//Console.ReadKey();
			}
		}
	}

	internal class Task
	{
		public void Solve(InputReader sr, TextWriter sw)
		{
			var input = sr.ReadArray(Int32.Parse);
			var n = input[0];
			var m = input[1];
			var costs = sr.ReadArray(Int32.Parse);
			var dict = new Dictionary<int, HashSet<int>>();
			for (var i = 0; i < m; i++) {
				input = sr.ReadArray(Int32.Parse);
				if (!dict.ContainsKey(input[0])) {
					dict.Add(input[0], new HashSet<int>());
				}
				dict[input[0]].Add(input[1]);
				if (!dict.ContainsKey(input[1])) {
					dict.Add(input[1], new HashSet<int>());
				}
				dict[input[1]].Add(input[0]);
			}
			var maxCost = -1;
			for (var i = 1; i <= n; i++) {
				for (var j = 1; j <= n; j++) {
					if (dict.ContainsKey(i) && dict[i].Contains(j)) {
						for (var k = 1; k <= n; k++) {
							if (i != j && i != k && j != k) {
								if (dict[i].Contains(k) && dict[j].Contains(k)) {
									var curr = costs[i - 1] + costs[j - 1] + costs[k - 1];
									if (curr > maxCost) {
										maxCost = curr;
									}
								}
							}
						}
					}
				}
			}

			sw.WriteLine(maxCost);
		}
	}
}

internal class InputReader : IDisposable
{
	private bool isDispose;
	private readonly TextReader sr;

	public InputReader(TextReader stream)
	{
		sr = stream;
	}

	public void Dispose()
	{
		Dispose(true);
		GC.SuppressFinalize(this);
	}

	public string NextString()
	{
		var result = sr.ReadLine();
		return result;
	}

	public int NextInt32()
	{
		return Int32.Parse(NextString());
	}

	public long NextInt64()
	{
		return Int64.Parse(NextString());
	}

	public string[] NextSplitStrings()
	{
		return NextString()
			.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
	}

	public T[] ReadArray<T>(Func<string, CultureInfo, T> func)
	{
		return NextSplitStrings()
			.Select(s => func(s, CultureInfo.InvariantCulture))
			.ToArray();
	}

	public T[] ReadArrayFromString<T>(Func<string, CultureInfo, T> func, string str)
	{
		return
			str.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries)
				.Select(s => func(s, CultureInfo.InvariantCulture))
				.ToArray();
	}

	protected void Dispose(bool dispose)
	{
		if (!isDispose) {
			if (dispose)
				sr.Close();
			isDispose = true;
		}
	}

	~InputReader()
	{
		Dispose(false);
	}
}

