namespace D
{
    class Program
    {
        class AR
        {
            public long max, sum, maxl, maxr;
        }

        static void Main(string[] args)
        {
            string[] line = Console.ReadLine().Split(' ');
            int n = int.Parse(line[0]);
            int m = int.Parse(line[1]);

            AR[] ar = new AR[n];

            for (int i = 0; i < n; i++)
            {
                line = Console.ReadLine().Split(' ');
                int size = int.Parse(line[0]);
                int[] a = new int[size];
                for (int j = 0; j < size; j++)
                    a[j] = int.Parse(line[j + 1]);

                ar[i] = new AR();

                //// max
                //long max = int.MinValue;
                //for (int j = 0; j < size; j++)
                //    max = Math.Max(max, a[j]);
                //ar[i].max = max;

                long sum = 0;
                for (int j = 0; j < size; j++)
                    sum += a[j];
                ar[i].sum = sum;


                int p = 0;
                long max = long.MinValue;

                while (p < size && a[p] < 0)
                    p++;

                if (p == size)
                {
                    for (int j = 0; j < size; j++)
                        max = Math.Max(max, a[j]);
                    ar[i].max = max;
                }
                else
                {
                    long cs = max = a[p];
                    for (int q = p + 1; q < size; q++)
                    {
                        if (a[q] + cs > 0)
                        {
                            cs += a[q];
                            max = Math.Max(max, cs);
                        }
                        else
                            cs = 0;
                    }
                    ar[i].max = max;
                }

                long maxl = 0, suml = 0;
                for (int j = 0; j < size; j++)
                {
                    suml += a[j];
                    maxl = Math.Max(maxl, suml);
                }

                long maxr = 0, sumr = 0;
                for (int j = size - 1; j >= 0; j--)
                {
                    sumr += a[j];
                    maxr = Math.Max(maxr, sumr);
                }

                ar[i].maxl = maxl;
                ar[i].maxr = maxr;
            }

            int[] lg = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);

            long[] DPe = new long[m + 1];
            long[] DPc = new long[m + 1];
            long[] DPs = new long[m + 1];

            DPe[0] = long.MinValue;
            DPc[0] = long.MinValue;
            DPs[0] = ar[lg[0] - 1].maxr;

            for (int i = 1; i < m; i++)
            {
                int idx = lg[i] - 1;
                if (i > 1)
                {
                    DPe[i] = Math.Max(DPc[i - 1], DPs[i - 1]) + ar[idx].maxl;
                    DPc[i] = Math.Max(DPc[i - 1], DPs[i - 1]) + ar[idx].sum;
                }
                else
                {
                    DPe[i] = DPs[i - 1] + ar[idx].maxl;
                    DPc[i] = DPs[i - 1] + ar[idx].sum;
                }
                DPs[i] = ar[idx].maxr;
            }

            long best = long.MinValue;
            for (int i = 0; i < m; i++)
                best = Math.Max(best, ar[lg[i] - 1].max);

            //best = Math.Max(best, ar[lg[0] - 1].maxr);

            for (int i = 1; i < m; i++)
            {
                best = Math.Max(best, DPe[i]);
                //best = Math.Max(best, DPc[i]);
                //best = Math.Max(best, DPs[i]);
            }

            Console.WriteLine(best);

        }
    }
}

