        static long[] ReadILongs() { return Array.ConvertAll(Console.ReadLine().Split(' '), sss => long.Parse(sss)); }

        public static void Main()
        {
            var xs = ReadInts();
            int n = xs[0],
                m = xs[1];
            var ys = new long[n][];
            var len = new int[n];
            var sum = new long[n];
            var minsum = new long[n];
            var minsum2 = new long[n];
            var maxsum = new long[n];
            var maxsum2 = new long[n];
            for (int i = 0; i < n; i++)
            {
                ys[i] = ReadILongs();
                len[i] = (int)ys[i][0];
                maxsum2[i] = int.MinValue;
                for (int j = 1; j <= len[i]; j++)
                {
                    sum[i] += ys[i][j];

                    if (maxsum2[i] < sum[i] - minsum[i])
                        maxsum2[i] = sum[i] - minsum[i];

                    if (j == 1 || maxsum[i] < sum[i])
                    {
                        if(j > 1) minsum2[i] = minsum[i];
                        maxsum[i] = sum[i];
                    }

                    if (minsum[i] > sum[i])
                        minsum[i] = sum[i];
                }
            }
            xs = ReadInts();
            long min = 0, now = 0, res = long.MinValue;
