            ret[i] = ReadLong();
        }
        return ret;
    }
    static string DoubleToString(double d) {
        return d.ToString(new CultureInfo("en-US"));
    }

    public static void Main(string[] args) {

        int N = ReadInt();
        int[] ar = ReadIntArray(N);
        for (int i = 0; i < N; i++) ar[i]--;
        int[,] dp = new int[2 * N + 1, N];
        for (int k = 0; k <= 2 * N; k++) {
            for (int i = 0; i < N; i++) {
                if (k == 0) dp[k, i] = 1;
                else if (k == 1) dp[k, i] = ar[i];
                else dp[k, i] = ar[dp[k - 1, i]];
            }
        }
        int[] cycle = new int[N];

        for (int i = 0; i < N; i++) {
            cycle[i] = -1;
        }
        for (int i = 0; i < N; i++) {
            for (int k = 1; k <= N; k++) {
                if (dp[k, i] == i) { cycle[i] = k; break; }
            }
        }
        long lc = 1;
        for (int i = 0; i < N; i++) {
            //Console.WriteLine(i + " " + cycle[i]);
            if (cycle[i] != -1) lc = lcm(lc, cycle[i]);
        }
