                bool flag = true;
                for (int i = 0; i < N; i++) {
                    if (dp[2 * k, i] != dp[k, i]) flag = false;
                }
                if (flag) { ans = k; break; }
            }
        }
        if (ans == -1) {
            ans = 0;
            while (ans < N) ans += lc;
        }

        Console.WriteLine(ans);

    }

    static long gcf(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    static long lcm(long a, long b) {
        return (a / gcf(a, b)) * b;
    }
}

