                for (int j = 4; j < phr.Length; ++j)
                    abbr += phr[j];


                answer = 1988;
                add = 1;
                pos_1 = 1;
                pos_2 = abbr.Length - 1;

                while (pos_2 >= 0)
                {
                    while (true)
                    {
                        answer += add;

                        if (take_dig(answer, pos_1) == abbr[pos_2] - '0')
                            break;
