﻿using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;
using System.IO;
using System.Linq;
using System.Threading;




class Program
{
    long[,] dp;
    long[] allLucky;
    long[] p10;
    int K;
    const long mod = 1000000007;
    void solve()
    {
        int Q = nextInt();
        K = nextInt();
        Do();
        for (int step = 1; step <= Q; step++)
        {
            string s = nextString();
            string t = nextString();
            long res = getStricklySmaller(t);
            res -= getStricklySmaller(s);
            if (isLucky(t))
                res++;
            res += mod;
            res %= mod;
            println(res);
        }

    }

    private long getStricklySmaller(string s)
    {
        int prev = -1;
        int d = 1001;
        long res = 0;
        for (int i = 0; i < s.Length; i++)
        {
            for (int cur = 0; cur < s[i] - '0'; cur++)
            {
                if (cur == 0 && i == 0)
                    continue;
                int nd = d;
                if ((cur == 4 || cur == 7) && prev != -1)
                    nd = Math.Min(nd, i - prev);
                if (nd <= K)
                    res += p10[s.Length - 1 - i];
                else
                {
                    int nprev = i-prev;
                    if (prev == -1)
                        nprev = 1001;
                    if (cur == 4 || cur == 7)
                        nprev = 0;
                    res += dp[nprev, s.Length - 1 - i];
                }
                res %= mod;
            }
            if (s[i] == '4' || s[i] == '7')
            {
                if (prev != -1)
                {
                    d = Math.Min(d, i - prev);
                }
                prev = i;
            }
        }
        for (int i = 1; i < s.Length; i++)
            res = (res + allLucky[i]) % mod;
        return res;
    }
    void Do()
    {
        dp = new long[1002, 1002];
        allLucky = new long[1002];
        p10 = new long[1002];
        for (int i = 0; i < p10.Length; i++)
        {
            p10[i] = (i == 0) ? 1 : 10 * p10[i - 1] % mod;
        }
        for (int digits = 0; digits < p10.Length; digits++)
            for (int prev = 0; prev < p10.Length; prev++)
            {
                if (digits > 0)
                {
                    long cur = 0;
                    //if lucky
                    if (prev <= K - 1)
                    {
                        cur += 2*p10[digits - 1];
                    }
                    else
                    {

                        cur += dp[0, digits - 1];
                    }
                    //end od luck
                    //not lucky
                    cur += 8*dp[Math.Min(1001, prev + 1), digits - 1];
                    //end of not lucky
                    dp[prev, digits] = cur % mod;
                }
            }
        for (int digits = 2; digits < p10.Length; digits++)
        {
            for (int first = 1; first <= 9; first++)
            {
                int prev = 1001;
                if (first == 4 || first == 7)
                {
                    prev = 0;
                }
                allLucky[digits] = (allLucky[digits] + dp[prev, digits - 1]) % mod;
            }
        }

    }
    bool isLucky(string s)
    {
        int prev = -1;
        int d = 1001;
        for (int i = 0; i < s.Length; i++)
        {
            if (s[i] == '4' || s[i] == '7')
            {
                if (prev != -1)
                {
                    d = Math.Min(d, i - prev);
                }
                prev = i;
            }
        }
        return d <= K;
    }

    ////////////
    private void println(int[] ar)
    {
        for (int i = 0; i < ar.Length; i++)
        {
            if (i == ar.Length - 1)
                println(ar[i]);
            else
                print(ar[i] + " ");
        }
    }
    private void println(int[] ar, bool add)
    {
        int A = 0;
        if (add)
            A++;
        for (int i = 0; i < ar.Length; i++)
        {
            if (i == ar.Length - 1)
                println(ar[i] + A);
            else
                print((ar[i] + A) + " ");
        }
    }

