﻿using System;
using System.Collections.Generic;
using System.IO;

namespace _37E
{
	class Vertex
	{
		public int V;
		public char Color;
		public HashSet<Vertex> Adjast = new HashSet<Vertex>();

		public override string ToString()
		{
			return V.ToString() + "(" + Color + ")";
		}
	}

	class Solver
	{
		public int N { get; set; }
		public int M { get; set; }
		public string[] Board { get; set; }
		int[,] Mask;
		Dictionary<int, Vertex> Graph = new Dictionary<int, Vertex>();

		public Solver(int N, int M, string[] board)
		{
			this.N = N;
			this.M = M;
			Board = board;
		}

		public void Solve()
		{
			Mask = new int[N, M];

			int Areas = Fill();

			bool[] prepared = new bool[Areas+1];

			for (int i = 1; i <= Areas; i++)
			{
				Graph.Add(i, new Vertex() { V = i });
			}

			for (int i = 0; i < Mask.GetLength(0); i++)
				for (int j = 0; j < Mask.GetLength(1); j++)
				{
					if (!prepared[Mask[i, j]])
					{
						bool[,] walked = new bool[Mask.GetLength(0), Mask.GetLength(1)];
						prepared[Mask[i, j]] = true;
						FillAdjast(walked, i, j);
					}
				}

			int max = -1;

			foreach (var v in Graph)
			{
				//genereate Wave
				bool[] walked2 = new bool[Areas + 1];
				walked2[v.Value.V] = true;
				List<Vertex> wave = new List<Vertex>();
				wave.Add(v.Value);
				bool startBlack = v.Value.Color == 'B';

				if (startBlack && max < 0)
					max = 0;

				bool needBreak;
				for (int i = 1; i < Areas; i++)
				{
					List<Vertex> newWave = new List<Vertex>();
					needBreak = true;
					foreach (var vinwave in wave)
						foreach (var adj in vinwave.Adjast)
							if (!walked2[adj.V])
							{
								walked2[adj.V] = true;
								newWave.Add(adj);
								needBreak = false;
								if (startBlack && adj.Color == 'B' && i > max)
									max = i;
							}
					wave = newWave;
					if (needBreak)
						break;
				}
			}

			Console.WriteLine((max + 2)/2);
		}

		private void FillAdjast(bool[,] walked, int i, int j)
		{
			if (walked[i, j])
				return;

			walked[i, j] = true;
			int c = Mask[i, j];
			Graph[c].Color = Board[i][j];

			if (i > 0)
			{
				if (Mask[i - 1, j] == c)
					FillAdjast(walked, i - 1, j);
				else
					Graph[c].Adjast.Add(Graph[Mask[i - 1, j]]);
			}
			if (j > 0)
			{
				if (Mask[i, j-1] == c)
					FillAdjast(walked, i , j-1);
				else
					Graph[c].Adjast.Add(Graph[Mask[i, j-1]]);
			}
			if (i < N-1)
			{
				if (Mask[i + 1, j] == c)
					FillAdjast(walked, i + 1, j);
				else
					Graph[c].Adjast.Add(Graph[Mask[i + 1, j]]);
			}
			if (j < M-1)
			{
				if (Mask[i , j + 1] == c)
					FillAdjast(walked, i , j + 1);
				else
					Graph[c].Adjast.Add(Graph[Mask[i, j + 1]]);
			}
		}

		private int Fill()
		{
			int k = 1;
			for (int i = 0; i < Mask.GetLength(0); i++)
				for (int j = 0; j < Mask.GetLength(1); j++)
					if (Mask[i, j] == 0)
					{
						FillPart(i, j, k);
						k++;
					}
			return k - 1;
		}

		private void FillPart(int i, int j, int k)
		{
			char c = Board[i][j];
			Mask[i, j] = k;

			if (i > 0 && Mask[i - 1, j] == 0 && Board[i - 1][j] == c)
				FillPart(i - 1, j, k);

			if (j > 0 && Mask[i, j - 1] == 0 && Board[i][j - 1] == c)
				FillPart(i, j - 1, k);

			if (i < Mask.GetLength(0)-1 && Mask[i + 1, j] == 0 && Board[i + 1][j] == c)
				FillPart(i + 1, j, k);

			if (j < Mask.GetLength(1)-1 && Mask[i, j + 1] == 0 && Board[i][j + 1] == c)
				FillPart(i, j + 1, k);
		}
	}

	class Program
	{
		//static StreamReader inStream = new StreamReader("input.txt");
		//static string ReadLine()
		//{
		//    return inStream.ReadLine();
		//}

		static string ReadLine()
		{
			return Console.ReadLine();
		}

		static void Main(string[] args)
		{
			string[] arg1 = ReadLine().Split();
			int N = int.Parse(arg1[0]);
			int M = int.Parse(arg1[1]);

			string[] board = new string[N];

			for (int i = 0; i < N; i++)
			{
				board[i] = ReadLine();
			}

			new Solver(N, M, board).Solve();
		}

	}
}

