				{
					List<Vertex> newWave = new List<Vertex>();
					needBreak = true;
					foreach (var vinwave in wave)
						foreach (var adj in vinwave.Adjast)
							if (!walked2[adj.V])
							{
								walked2[adj.V] = true;
								newWave.Add(adj);
								needBreak = false;
								if (adj.Color == 'B' && i > max)
									max = i;
							}
					wave = newWave;
					if (needBreak)
						break;
				}

				if (min > max)
					min = max;
			}

			Console.WriteLine(min + 1);
		}

		private void FillAdjast(bool[,] walked, int i, int j)
		{
			if (walked[i, j])
				return;

			walked[i, j] = true;
			int c = Mask[i, j];
			Graph[c].Color = Board[i][j];

			if (i > 0)
			{
				if (Mask[i - 1, j] == c)
					FillAdjast(walked, i - 1, j);
				else
					Graph[c].Adjast.Add(Graph[Mask[i - 1, j]]);
			}
			if (j > 0)
			{
				if (Mask[i, j-1] == c)
					FillAdjast(walked, i , j-1);
				else
					Graph[c].Adjast.Add(Graph[Mask[i, j-1]]);
			}
			if (i < N-1)
			{
				if (Mask[i + 1, j] == c)
					FillAdjast(walked, i + 1, j);
				else
					Graph[c].Adjast.Add(Graph[Mask[i + 1, j]]);
			}
			if (j < M-1)
			{
				if (Mask[i , j + 1] == c)
					FillAdjast(walked, i , j + 1);
				else
					Graph[c].Adjast.Add(Graph[Mask[i, j + 1]]);
			}
		}

		private int Fill()
		{
			int k = 1;
			for (int i = 0; i < Mask.GetLength(0); i++)
				for (int j = 0; j < Mask.GetLength(1); j++)
					if (Mask[i, j] == 0)
					{
						FillPart(i, j, k);
						k++;
					}
			return k - 1;
		}

		private void FillPart(int i, int j, int k)
		{
			char c = Board[i][j];
			Mask[i, j] = k;

			if (i > 0 && Mask[i - 1, j] == 0 && Board[i - 1][j] == c)
				FillPart(i - 1, j, k);

			if (j > 0 && Mask[i, j - 1] == 0 && Board[i][j - 1] == c)
				FillPart(i, j - 1, k);

			if (i < Mask.GetLength(0)-1 && Mask[i + 1, j] == 0 && Board[i + 1][j] == c)
				FillPart(i + 1, j, k);

			if (j < Mask.GetLength(1)-1 && Mask[i, j + 1] == 0 && Board[i][j + 1] == c)
				FillPart(i, j + 1, k);
		}
	}

