using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

public class Program
{
    public static void Main(string[] args)
    {
        var input = Console.ReadLine();

        System.Console.WriteLine(Solve(input));
    }

    private static string Solve(string input)
    {
        var n = input.Length;
        if (n % 2 != 0)
        {
            return Generate(0, String.Empty, n + 1);
        }

        var result = new char[n];
        var foors = 0;
        var sevens = 0;
        for (int i = 0; i < n; ++i)
        {
            if (input[i] < '4')
            {
                var prefix = new string(result, 0, i);
                if (foors < n / 2)
                {
                    prefix = prefix + '4';
                    ++foors;
                }
                else
                {
                    prefix = prefix + '7';
                }
                return Generate(foors, prefix, n);
            }

            if (input[i] == '4')
            {
                if (foors < n / 2)
                {
                    result[i] = '4';
                    ++foors;
                    continue;
                }
                else
                {
                    result[i] = '7';
                    return Generate(foors, new string(result, 0, i + 1), n);
                }
            }

            if (input[i] < '7')
            {
                if (sevens < n / 2)
                {
                    var prefix = new string(result, 0, i) + '7';
                    return Generate(foors, prefix, n);
                }
                return FindLeft(input, result, i - 1, sevens, foors);
            }

            if (input[i] == '7')
            {
                if (sevens < n / 2)
                {
                    result[i] = '7';
                    ++sevens;
                    continue;
                }
                return FindLeft(input, result, i - 1, sevens, foors);
            }

            if (input[i] > '7')
            {
                return FindLeft(input, result, i - 1, sevens, foors);
            }
        }
        return new string(result);
    }

    private static string FindLeft(string input, char[] result, int start, int sevens, int foors)
    {
        int n = input.Length;
        for (int i= start; i >= 0; --i)
        {
            if (result[i] == '7')
            {
                --sevens;
            }
            else
            {
                --foors;
                if (sevens < n / 2)
                {
                    result[i] = '7';
                    return Generate(foors, new string(result, 0, i), n);
                }
            }
        }
        return Generate(0, "", n + 2);
    }

    private static string Generate(int foors, string prefix, int size)
    {
        var realSize = size - prefix.Length;

        return prefix + new String('4', size/2 - foors) +
               new String('7', realSize - size / 2 + foors);
    }
}

