                        break;
                    }
            }
        }
    }

    static void defragment() {
        int cnt = _memory.Count, i = 0;
        for (; i < cnt; i++) {
            block block = _memory[i];
            if (i == 0) {
                block.offset = 0;
            } else { var prev_block = _memory[i - 1]; block.offset = prev_block.offset + prev_block.size; }
            _memory[i] = block;
        }
    }

