        var block = find_block(index);
        if (block.HasValue) {
            _memory.Remove(block.Value);
        } else { Console.WriteLine("ILLEGAL_ERASE_ARGUMENT"); }
    }

    static block? find_block(int index) {
        var blocks = _memory.Where(x => x.index == index);
        if (blocks.Count() == 0) {
            return null;
        } else { return blocks.First(); }
    }

