            _memory.Add(block.Value);
            _memory = _memory.OrderBy(x => x.offset).ToList();
        } else { Console.WriteLine("NULL"); }
    }

    static block? insert_block(int size) {
        int found_offset = -1;
        if (get_first_empty_size(0) >= size) { found_offset = 0; }
        if (found_offset < 0) {
            for (int i = 0; i < _memory.Count; i++) {
                var block_seek = _memory[i].offset + _memory[i].size;
                var block_size = get_first_empty_size(block_seek);
                if (block_size >= size) { found_offset = block_seek; break; }
            }
        }
        if (found_offset >= 0) {
            _global_index++;
            return new block() {
                index = _global_index,
                offset = found_offset,
                size = size
            };
        }
        return null;
    }

    static int get_first_empty_size(int seek) {
        var blocks = _memory.Where(x => x.offset >= seek);
        return (blocks.Count() == 0 ? _memory_size : blocks.First().offset) - seek;
    }
