using System.Collections.Generic;
using System.Text;
using System.Linq;
using System.Diagnostics;
using System.IO;

namespace Solution
{
    class Solution
    {
        public void Solve()
        {
            var n = int.Parse(Console.ReadLine());

            var list = new List<int>();
            {
                var ds = Console.ReadLine().Split(' ');
                foreach (var v in ds)
                {
                    var d = int.Parse(v);
                    list.Add(d);
                }
            }

            if (!list.Contains(0))
            {
                Console.WriteLine("-1");
                return;
            }
            list.Remove(0);

            if (list.Sum() % 3 == 0)
            {
                _o(list);
                return;
            }

            for (int i = 1; i <= 9; i++)
            {
                if (!list.Contains(i))
                    continue;

                if ((list.Sum() - i) % 3 == 0)
                {
                    list.Remove(i);
                    _o(list);
                    return;
                }
            }

            for (int i = 1; i <= 9; i++)
            {
                if (!list.Contains(i))
                    continue;

                list.Remove(i);

                for (int j = 1; j <= i; j++)
                {
                    if (!list.Contains(j))
                        continue;

                    if ((list.Sum() -j) % 3 == 0)
                    {
                        list.Remove(j);
                        _o(list);
                        return;
                    }
                }

                list.Add(i);
            }

            Console.WriteLine("-1");
        }

        void _o(List<int> ds)
        {
            if (ds.Sum() != 0)
            {
                ds.Sort();
                ds.Reverse();
                foreach (var v in ds)
                {
                    Console.Write(v);
                }
            }
            Console.WriteLine("0");
        }


#if !DEBUG
    static void Main(string[] args)
    {
        new Solution().Solve();
    }
#endif
    }
}

