namespace cf_BooksExposition
{
    class Program
    {
        static void Main(string[] args)
        {
            string[] line = Console.ReadLine().Split(' ');
            int n = Convert.ToInt32(line[0]);
            int k = Convert.ToInt32(line[1]);
            line = Console.ReadLine().Split(' ');
            int[] nums = line.Select(s => Convert.ToInt32(s)).ToArray();

            //int k = 5;
            //int[] nums = new int[] { 8, 19,14, 10, 13,8};
            int l;
            var list = BooksExposition(k, nums, out l);
            Console.WriteLine(l + " " + list.Count);
            foreach (int i in list)
            {
                Console.WriteLine((i + 1) + " " + (i + l));


            }



        }

        private static List<int> BooksExposition(int k, int[] nums, out int l)
        {
            LinkedList<int> maxlist = new LinkedList<int>();
            LinkedList<int> minlist = new LinkedList<int>();

            l = 1;

            maxlist.AddLast(0);
            minlist.AddLast(0);
            int i = 0;
            List<int> results = new List<int>();
            results.Add(0);
            for (int j = 1; j < nums.Length; j++)
            {
                while (maxlist.Count > 0 && nums[j] > nums[maxlist.Last.Value])
                {
                    maxlist.RemoveLast();
                }
                if (maxlist.Count == 0 || nums[j] != nums[maxlist.Last.Value])
                    maxlist.AddLast(j);

                while (minlist.Count > 0 && nums[j] < nums[minlist.Last.Value])
                {
                    minlist.RemoveLast();
                }
                if (minlist.Count == 0 || nums[j] != nums[minlist.Last.Value])
                    minlist.AddLast(j);

                while (nums[maxlist.First.Value] - nums[minlist.First.Value] > k)
                {
                    if (minlist.First.Value < maxlist.First.Value)
                    {
                        i = minlist.First.Value + 1;
                        minlist.RemoveFirst();
                    }
                    else
                    {
                        i = maxlist.First.Value + 1;
                        maxlist.RemoveFirst();
                        if (minlist.First.Value == maxlist.First.Value)
                            minlist.RemoveFirst();
                    }

                }

                if (j - i + 1 > l)
                {
                    l = j - i + 1;
                    results.Clear();
                    results.Add(i);
                }
                else if (j - i + 1 == l)
                {
                    results.Add(i);
                }
            }
            return results;
        }
    }
}

