                    if (minlist.First.Value < maxlist.First.Value)
                    {
                        i = minlist.First.Value + 1;
                        minlist.RemoveFirst();
                        while (maxlist.First.Value < i)
                            maxlist.RemoveFirst();
                    }
                    else
                    {
                        i = maxlist.First.Value + 1;
                        maxlist.RemoveFirst();
                        while (minlist.First.Value < i)
                            minlist.RemoveFirst();
                    }
                }

                if (j - i + 1 > l)
                {
                    l = j - i + 1;
                    results.Clear();
                    results.Add(i);
                }
                else if (j - i + 1 == l)
                {
                    results.Add(i);
                }
            }
            return results;
        }
    }
}

