				foreach (var opinion in opinions) {
					if (opinion > 0) {
						if (opinion == i + 1)
							countTruth++;
					} else {
						if (-opinion != i + 1) 
							countTruth++;
					}
					if (countTruth > rightPeoplesCount)
						break;
				}
				if (countTruth != rightPeoplesCount)
					impossibleMurders.Add(i + 1);
				else
					lastPossibleSolution = i + 1;

			}

			if (impossibleMurders.Count == peoples.Length - 1) {
				for (int i = 0; i < opinions.Length; i++) {
					if (opinions[i] == lastPossibleSolution)
