﻿using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace B
{
    class bus
    {
        public int s, t;
    }

    class Program
    {
        const int mod = 1000000007;
        static int n, m;
        static bus[] buses;
        static Dictionary<int, int> mem = new Dictionary<int,int>();
        static int [] dp;
        static int t;

        static int countfrom(int p, int b)
        {
            if (p == t)
                return 1;

            if (dp[p] != -1)
                return dp[p];

            int ways = 0;
            for (int i = b + 1; i < m; i++)
            {
                if (p >= buses[i].s && p < buses[i].t)
                {
                    ways += countfrom(buses[i].t, i);
                    ways %= mod;
                }
            }

            dp[p] = ways;
            return ways;
        }

        static void Main(string[] args)
        {
            string[] line = Console.ReadLine().Split();
            n = int.Parse(line[0]);
            m = int.Parse(line[1]);

            buses = new bus[m];
            for (int i = 0; i < m; i++)
            {
                buses[i] = new bus();
                line = Console.ReadLine().Split();
                buses[i].s = int.Parse(line[0]);
                buses[i].t = int.Parse(line[1]);
            }


            SortedDictionary<int, int> distinct = new SortedDictionary<int, int>();
            distinct[0] = 0;
            distinct[n] = 0;

            for (int i = 0; i < buses.Length; i++)
            {
                distinct[buses[i].s] = 0;
                distinct[buses[i].t] = 0;
            }

            List<int> keys = distinct.Keys.ToList();
            keys.Sort();

            int curr = 0;
            for (int i = 0; i < keys.Count; i++)
                distinct[keys[i]] = curr++;

            for (int i = 0; i < buses.Length; i++)
            {
                buses[i].s = distinct[buses[i].s];
                buses[i].t = distinct[buses[i].t];
            }

            t = distinct[n];

            dp = new int[t + 1];
            for (int i = 0; i < dp.Length; i++)
                dp[i] = -1;

            Array.Sort(buses, (x, y) => x.t.CompareTo(y.t));
            Console.WriteLine(countfrom(0, -1));
        }
    }
}

