﻿using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.IO;

namespace Codeforces
{
#if _ONLINE_JUDGE_
	[OnlineJudge.Task("Codeforces 101B")]
#endif
	class Task101B
	{
		private InputTokenizer input = new InputTokenizer();
		private TextWriter output = Console.Out;

		class FenwickTree
		{
			private long[] _data;
			private int _size;

			public FenwickTree(int size)
			{
				_size = size;
				_data = new long[_size];
			}

			public FenwickTree(IEnumerable<long> values)
			{
				_size = values.Count();
				_data = new long[_size];

				int i = 0;
				foreach (long x in values) Increment(i++, x);
			}

			public long Sum(int high)
			{
				if (high < 0) return 0;
				long answer = 0;
				for (; high >= 0; high = (high & (high + 1)) - 1)
					answer += _data[high];
				return answer;
			}

			public long Sum(int low, int high)
			{
				return Sum(high) - Sum(low - 1);
			}

			public void Increment(int index, long increment)
			{
				for (; index < _size; index |= index + 1)
					_data[index] += increment;
			}
		}

		struct T
		{
			public int a, b;
		}

		private void Solve()
		{
			int n, m;

			input.Line().Read(out n).Read(out m);

			var f = new SortedDictionary<int, int>();

			var tmp = new T[m];
			for (int i = 0; i < m; ++i)
			{
				input.Line().Read(out tmp[i].a).Read(out tmp[i].b);
				f[tmp[i].a] = 0;
				f[tmp[i].b] = 0;
			}

			f[0] = 0;
			f[n] = 0;

			var keys = f.Keys.ToArray();
			int g = 0;
			for (int i = 0; i < keys.Length; ++g) {
				f[keys[i]] = g;
				++i;
				while (i < keys.Length && keys[i - 1] == keys[i]) ++i;
			}

			Array.Sort(tmp, (l, r) => l.b - r.b);

			var ft = new FenwickTree(g);

			ft.Increment(0, 1);
			for (int i = 0; i < m; ++i)
			{
				ft.Increment(f[tmp[i].b], ft.Sum(f[tmp[i].a], f[tmp[i].b] - 1) % 1000000007);
			}

			output.WriteLine(ft.Sum(f[n], f[n]) % 1000000007);
		}

		public static void Main()
		{
			var obj = new Task101B();
			obj.Solve();
		}

		#region
		private class InputTokenizer
		{
			private List<string> _tokens = new List<string>();
			private int _offset = 0;

			public InputTokenizer()
			{
			}

			public InputTokenizer String(String s)
			{
				_tokens.AddRange(s.Split(new char[] { ' ', '\n', '\t', '\r' }, StringSplitOptions.RemoveEmptyEntries));
				return this;
			}

			public InputTokenizer Line()
			{
				return String(Console.In.ReadLine());
			}

			public InputTokenizer Read(out int v)
			{
				v = int.Parse(_tokens[_offset++]);
				return this;
			}

			public InputTokenizer Read(int n, out int[] v)
			{
				v = new int[n];
				for (int i = 0; i < n; ++i) Read(out v[i]);
				return this;
			}

			public InputTokenizer Read(out long v)
			{
				v = long.Parse(_tokens[_offset++]);
				return this;
			}

			public InputTokenizer Read(int n, out long[] v)
			{
				v = new long[n];
				for (int i = 0; i < n; ++i) Read(out v[i]);
				return this;
			}

			public InputTokenizer Read(out ulong v)
			{
				v = ulong.Parse(_tokens[_offset++]);
				return this;
			}

			public InputTokenizer Read(int n, out ulong[] v)
			{
				v = new ulong[n];
				for (int i = 0; i < n; ++i) Read(out v[i]);
				return this;
			}

			public InputTokenizer Read(out double v)
			{
				v = double.Parse(_tokens[_offset++]);
				return this;
			}

			public InputTokenizer Read(int n, out double[] v)
			{
				v = new double[n];
				for (int i = 0; i < n; ++i) Read(out v[i]);
				return this;
			}

			public InputTokenizer Read(out string v)
			{
				v = _tokens[_offset++];
				return this;
			}

			public InputTokenizer Read(int n, out string[] v)
