        for (int i = 0; i < a.Length; i++)
            a[i] = nextLong();
        long res = n - doIt(n);
        println(res);


    }
    long doIt(long n)
    {
        Array.Sort(a);
        Array.Reverse(a);
        bool ok = true;
        for (int i = 0; i < a.Length; i++)
        {
            if (a[i] == 1)
                ok = false;
        }
        if (!ok)
        {
            return 0;
        }
        dp = new long[100, maxn];
        for (int i = 0; i < 100; i++)
            for (int j = 0; j < maxn; j++)
                dp[i, j] = -1;
        return go(n, 0);
    }
