                    else if (cos < -eps) return PI + Math.Atan(sin / cos);
                    else return -PI / 2;
                }
                else
                {
                    if (cos > eps) return 0;
                    else if (cos < -eps) return PI;
                    else throw new Exception("zero vector");
                }
            }
