        public static class ConvexHull
        {
            // Notes:
            // pts is not affected.
            // PointD[] can be any indexable type.
            // работает даже для вырожденных случаев.

            static int[] p;
            static PointD[] pts;
            static double[] a;

            class PointComparer : IComparer<int>
            {
                public int Compare(int p1, int p2)
                {
                    double da = a[p1] - a[p2];
                    if (Math.Abs(da) > 1e-9) return Math.Sign(da);
                    return Math.Sign(pts[p1].Dist2() - pts[p2].Dist2());
                }
            }

            public static List<int> Do(PointD[] pts)
            {
                List<int> ch = new List<int>();
                if (pts.Length == 0) return ch;

                ConvexHull.pts = pts;
                p = new int[pts.Length];
                for (int i = 0; i < pts.Length; i++) p[i] = i;

                int m = 0;
                for (int i = 1; i < pts.Length; i++)
                    if (pts[i].Y < pts[m].Y || pts[i].Y == pts[m].Y && pts[i].X < pts[m].X)
                        m = i;
                p[0] = m; p[m] = 0;

                a = new double[pts.Length];
                for (int i = 1; i < pts.Length; i++) a[p[i]] = (pts[p[i]] - pts[m]).Atan2;

                Array.Sort<int>(p, 1, pts.Length - 1, new PointComparer());

                // избавляемся от дубликатов точки m.
                int j;
                for (j = 1; j < pts.Length - 1; j++)
                    if (pts[p[j]].Dist2() == 0) p[j] = -1;
                    else break;

                // "если есть несколько точек с одинаковым углом, то оставляем только самую удалённую."
                // заодно и избавимся от дубликатов.
                for (; j < pts.Length - 1; j++)
                    if (Math.Abs(a[p[j + 1]] - a[p[j]]) < 1e-9)
                        p[j] = -1;

                ch.Add(p[0]);
                j = 1;
                while (ch.Count < 3)
                {
                    if (j == p.Length) return ch;
                    if (p[j++] >= 0) ch.Add(p[j - 1]);
                }

                for (; j < p.Length; j++)
                {
                    while (j < p.Length && p[j] < 0) j++;
                    if (j == pts.Length) return ch;         // вроде никогда не должно сработать

                    while (true)
                    {
                        PointD p1 = pts[ch[ch.Count - 2]];
                        PointD p2 = pts[ch[ch.Count - 1]];
                        PointD p3 = pts[p[j]];
                        var v12 = new VectorD(p2, p1);
                        var v23 = new VectorD(p3, p2);
                        if (v12 * v23 < 0) break;

                        ch.RemoveAt(ch.Count - 1);
                    }
                    ch.Add(p[j]);
                }

                return ch;
            }

            public static void test()
            {
                List<PointD> pts = new List<PointD>();
                pts.Add(new PointD(1, 1));
                pts.Add(new PointD(0, 0));
                pts.Add(new PointD(2, 2));
                pts.Add(new PointD(10, 0));
                var ch = Do(pts.ToArray());
                var chpts = new List<PointD>();
                foreach (var p in ch)
                    chpts.Add(pts[p]);
            }
        }

        static int Main(string[] args)
        {
           Geometry.ConvexHull.test();

            //Console.SetIn(File.OpenText("_input"));
            Parser parser = new Parser();

