using System;
using System.Collections.Generic;

namespace Task2
{
    class Program
    {
        private struct Spell
        {
            public int N;
            public int pow;
            public int dmg;

            public static Spell NullSpell
            {
                get { return new Spell() {N = -1, dmg = -1, pow = -1}; }
            }
        }

        private struct Cast
        {

            public int time;
            public int spell;
        }

        static void Main(string[] args)
        {
            string line;

            line = Console.ReadLine();
            string[] arg1 = line.Split();

            int N = int.Parse(arg1[0]);
            int max = int.Parse(arg1[1]);
            int reg = int.Parse(arg1[2]);

            List<Spell> spells = new List<Spell>();

            for (int i = 0; i < N; i++)
            {
                line = Console.ReadLine();
                string[] arg2 = line.Split();

                int pow = int.Parse(arg2[0]);
                int dmg = int.Parse(arg2[1]);

                spells.Add(new Spell() {N = i + 1, pow = pow, dmg = dmg});
            }

            spells.Sort( (x, y) => y.dmg.CompareTo(x.dmg)); //sort desc

            List<Cast> usedSpells = new List<Cast>();

            int currentDmg = 0;
            int currentHp = max;
            int currentTime = 0;

            do
            {
                currentHp -= currentDmg;

                currentHp += reg;
                if (currentHp > max)
                    currentHp = max;

                Spell spell = GetBestSpell(currentHp, max, spells);
                if (spell.Equals(Spell.NullSpell))
                {
                    if (reg >= currentDmg && currentHp > 0)
                    {
                        OutNoSolution();
                        return;
                    }
                }
                else
                {
                    currentDmg += spell.dmg;
                    spells.Remove(spell);

                    usedSpells.Add(new Cast() {spell = spell.N, time = currentTime});
                }

                if (currentHp <= 0)
                {
                    OutSolution(usedSpells, currentTime);
                    return;
                }

                currentTime++;
            } while (true);
        }

        private static void OutNoSolution()
        {
            Console.WriteLine("NO");

        }

        private static void OutSolution(List<Cast> usedSpells, int time)
        {
            Console.WriteLine("YES");
            Console.WriteLine("{0} {1}", time, usedSpells.Count);

            foreach (var cast in usedSpells)
            {
                Console.WriteLine("{0} {1}", cast.time, cast.spell);
            }
        }

        private static Spell GetBestSpell(int currentHp, int max, List<Spell> spells)
        {
            for (int i = 0; i < spells.Count; i++)
                if ((long)currentHp * 100 <= (long)spells[i].pow * max)
                {
                    return spells[i];
                }

            return Spell.NullSpell;
        }
    }
}

