    void calc()
    {
        cin = new Scanner();
        int N = cin.nextInt();
        long[] A = new long[N];
        int count1 = 0;
        for (int i = 0; i < N; i++)
        {
            A[i] = cin.nextLong();
            if (A[i] == 1) count1++;
        }
        Array.Sort(A);

        int MAX = 200000;

        int ok = MAX;
        int ng = 0;

        long[] NGar = new long[N];
        long[] OKar = new long[N];
        int NGcnt, OKcnt;

        while(ok - ng > 1)
        {
            int mid = (ok + ng) / 2;
            long p2Num = 0;
            int p2 = mid;

            long preNum = 1;
            int pre = 0;
            bool flag = true;
            NGcnt = OKcnt = 0;

            foreach (var now in A)
            {
                while(now > preNum)
                {
                    if (p2Num != 0)
                    {
                        for (int i = 0; i < p2; i++)
                        {
                            OKar[OKcnt++] = p2Num;
                        }
                    }
                    p2 = pre;
                    p2Num = preNum;
                    pre = 0;
                    preNum *= 2;
                }
                if(p2 >= 1 && now == preNum)
                {
                    pre++;
                    p2--;
                }
                else
                {
                    NGar[NGcnt++] = now;
                }

            }

            for (int i = 0; i < p2; i++)
            {
                OKar[OKcnt++] = p2Num;
            }
            for (int i = 0; i < pre; i++)
            {
                OKar[OKcnt++] = preNum;
            }

            int o = 0;
            int nn = 0;
            while(o < OKcnt && nn < NGcnt)
            {
                if (OKar[o] * 2 >= NGar[nn]) nn++;
                o++;
            }

            if (nn < NGcnt) flag = false;

            if (flag) ok = mid;
            else  ng = mid;
        }

        if (ok == MAX) Console.WriteLine(-1);
        else
        {
            for (int i = ok; i <= count1; i++)
            {
                Console.Write(i + " ");
            }
            Console.WriteLine();
        }
    }
}

