﻿namespace ZT.Contests.Codeforces
{
    using System;
    using System.Collections.Generic;
    using System.IO;
    using System.Linq;

    internal static class Program
    {
        public static void Main(string[] args)
        {
            var solver = new PrairiePartition();
            var input = new TextInputHelper(Console.In);
            solver.DoWork(input);
        }
    }

    internal class PrairiePartition : CFSolver
    {
        // 2^(ValueU2-1) should be larger than the largest value
        private const int ValueU2 = 42;

        public PrairiePartition(RunType runType = RunType.ReadUntilNoInput) : base(runType) { }

        public override void Solve(InputHelper input)
        {
            var n = input.Read<int>();
            var a = new long[n];
            for (var i = 0; i < n; ++i) a[i] = input.Read<long>();

            var sum = new int[ValueU2]; // count of number no less than 2^j
            var b = new int[ValueU2]; // count of number equal to 2^j
            for (int j = ValueU2 - 1, i = n - 1; j >= 0; --j)
            {
                var c = 1L << j;
                for (; i >= 0 && a[i] > c; --i) ;
                sum[j] = n - i - 1;
                var qi = i;
                for (; i >= 0 && a[i] >= c; --i) ;
                b[j] = qi - i;
            }
            //Console.WriteLine($"sum: {string.Join(" ", sum)}\nb: {string.Join(" ", b)}");
            var res = new List<int>();
            for (var r = (b[0] + 1) / 2; r <= b[0]; ++r)
            {
                var u = new int[ValueU2];
                var v = new int[ValueU2];
                //Console.WriteLine($"check {r}");
                Func<int, int, bool> cal = null;
                cal = (j, c) =>
                {
                    if (j == ValueU2 - 1) return true; // 2^(ValueU2-1) is larger than the largest element
                    u[j] = Math.Min(c, b[j]);
                    if (!cal(j + 1, u[j])) return false;
                    var d = sum[j] - sum[j + 1] - u[j + 1];
                    v[j] = v[j + 1] + d;
                    //Console.WriteLine($"\t{j}: {u[j]} {v[j]} ({d})");
                    return u[j] >= v[j];
                };
                if (cal(0, r) && u[0] - v[0] >= b[0] - u[0]) res.Add(r);
            }
            Console.WriteLine(res.Any() ? string.Join(" ", res) : "-1");
        }
    }

    internal abstract class CFSolver
    {
        public const long Mod = 1000000007;

        public CFSolver(RunType runType)
        {
            RunType = runType;
        }

        public RunType RunType { get; private set; }

        public void DoWork(InputHelper input)
        {
            Func<bool> shouldRun;

            switch (RunType)
            {
                case RunType.ReadRunTimeFromInput:
                    shouldRun = GetShouldRun(input.Read<int>());
                    break;
                case RunType.ReadUntilNoInput:
                    shouldRun = () => input.HasNext();
                    break;
                default:
                    shouldRun = GetShouldRun(1);
                    break;
            }

            while (shouldRun())
            {
                Solve(input);
            }
        }

        public abstract void Solve(InputHelper input);

        private static Func<bool> GetShouldRun(int n) { return () => n-- > 0; }
    }

    public enum RunType
    {
        Single,
        ReadRunTimeFromInput,
        ReadUntilNoInput,
    }

    public abstract class InputHelper
    {
        private bool any;
        private IEnumerator<string> cur;

        public T Read<T>()
        {
            if (!HasNext()) { throw new InvalidOperationException("no more data"); }
            var r = (T)Convert.ChangeType(cur.Current, typeof(T));
            any = false;
            return r;
        }

        public bool HasNext()
        {
            while (!any)
            {
                if (cur != null && cur.MoveNext()) break;
                var next = GetNextGroup();
                if (next == null) { return false; }
                cur = next.GetEnumerator();
                any = cur.MoveNext();
            }

            return any = true;
        }

        protected abstract IEnumerable<string> GetNextGroup();
    }

    public class TextInputHelper : InputHelper
    {
        private TextReader reader;

        public TextInputHelper(TextReader reader) { this.reader = reader; }

        protected override IEnumerable<string> GetNextGroup()
        {
            if (reader == null) { return null; }
            var cur = reader;
            reader = null;
            return ReadWordsToEnd(cur);
        }

        public static IEnumerable<string> ReadWordsToEnd(TextReader reader)
        {
            while (true)
            {
                var lines = ReadWords(reader);
                if (lines == null) yield break;
                foreach (string word in lines) yield return word;
            }
        }

        public static IEnumerable<string> ReadWords(TextReader reader)
        {
            string line = reader.ReadLine();
            return line == null ? null : line.Split(new char[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
        }
    }
}

