package main

import (
	"bufio"
	"fmt"
	"os"
)

func _Solve(current int, n int, k int, S string) string {
	if n == 1 && k > 0 {
		return "0"
	}
	if k == 0 || current == n {
		return S
	}
	if current == 0 && string(S[current]) != "1" {
		k -= 1
		S = "1" + S[1:]
	} else if current != 0 && S[current] > 0 {
		k -= 1
		S = S[:current] + "0" + S[current+1:]
	}
	return _Solve(current+1, n, k, S)
}

func Solve(n int, k int, S string) string {
	return _Solve(0, n, k, S)
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, k int
	var s string
	fmt.Fscanf(reader, "%d %d\n%s\n", &n, &k, &s)

	fmt.Fprintf(writer, "%s\n", Solve(n, k, s))
}

