	reader := bytes.NewBuffer(bs)

	var n int
	var vb, vs, xu, yu float64

	fmt.Fscanf(reader, "%d %f %f\n", &n, &vb, &vs)
	stop := make([]float64, n)
	for i := 0; i < n; i++ {
		fmt.Fscanf(reader, "%f", &stop[i])
		if i != n-1 {
			fmt.Fscanf(reader, " ")
		} else {
			fmt.Fscanf(reader, "\n")
		}
	}
	fmt.Fscanf(reader, "%f %f", &xu, &yu)
	min := 99999999999.0
	var minStop int
	for i := 1; i < n; i++ {
		t := stop[i]/vb + math.Sqrt((xu-stop[i])*(xu-stop[i])+yu*yu)/vs
		if t < min {
			minStop = i
			min = t
		} else if t == min {
			if math.Abs(xu-stop[minStop]) > math.Abs(xu-stop[i]) {
				minStop = i
				min = t
			}
		}
	}
	fmt.Printf("%d", minStop+1)
