	var a, b string
	likes := map[string]map[string]int{}
	for i := 0; i < n; i++ {
		fmt.Scanf("%s likes %s\n", &a, &b)
		_, ok := likes[a]
		if !ok {
			likes[a] = map[string]int{}
		}
		likes[a][b] = 1
	}
	var n1, n2, n3 int
	fmt.Scanf("%d %d %d\n", &n1, &n2, &n3)
	heroes := []string{"Anka", "Chapay", "Cleo", "Troll", "Dracul", "Snowy", "Hexadecimal"}
	ans1, ans2 := math.MaxInt32, math.MinInt32
	g1, g2, g3 := 0, 0, 0
	for i := 1; i <= 5; i++ {
		for j := 1; j <= 5; j++ {
			if i+j >= 7 {
				continue
			}
			k := 7 - i - j
			t := calc(n1/i, n2/j, n3/k)
			if t < ans1 {
				ans1 = t
				g1, g2, g3 = i, j, k
			}
		}
	}
	var i, j, k uint
	var t int
	for i = 0; i < 128; i++ {
		if count(i) != g1 {
			continue
		}
		for j = 0; j < 128; j++ {
			if count(j) != g2 {
				continue
			}
			k = 127 - i - j
			if count(k) != g3 {
				continue
			}
			t = calc2(i, heroes, likes) + calc2(j, heroes, likes) + calc2(k, heroes, likes)
			if t > ans2 {
				ans2 = t
			}
		}
	}
	fmt.Println(ans1, ans2)
}

func calc2(n uint, h []string, l map[string]map[string]int) int {
	ans := 0
	q := []int{}
	for i := 0; i < 7; i++ {
		if n&(1<<i) != 0 {
			q = append(q, i)
		}
	}

	for i := 0; i < len(q); i++ {
		for j := i + 1; j < len(q); j++ {
			if l[h[q[i]]][h[q[j]]] == 1 {
				ans++
			}
			if l[h[q[j]]][h[q[i]]] == 1 {
				ans++
			}
		}
	}
	return ans
}

func count(n uint) int {
	ans := 0
	for n != 0 {
		ans++
		n = n & (n - 1)
	}
	return ans
}

func calc(a, b, c int) int {
	if a < b {
		a, b = b, a
	}
	if b > c {
		return a - c
	}
	if c > a {
		return c - b
	}
	return a - b
}

