  Pos, Size int
}
type Houses []*House
func (houses Houses) Len() int {
  return len(houses)
}
func (houses Houses) Swap(i, j int) {
  houses[i], houses[j] = houses[j], houses[i]
}
func (houses Houses) Less(i, j int) bool {
  return houses[i].Pos < houses[j].Pos
}

