)

var scanner *bufio.Scanner

func getI64() int64 {
  scanner.Scan()
  x, _ := strconv.ParseInt(scanner.Text(), 10, 64)
  return x
}
func getI() int {
  return int(getI64())
}
func getF() float64 {
  scanner.Scan()
  x, _ := strconv.ParseFloat(scanner.Text(), 64)
  return x
}
func getS() string {
  scanner.Scan()
  return scanner.Text()
}

func seek(s, a, b string) bool {
  aPos := strings.Index(s, a)
  if aPos != -1 {
    bPos := strings.Index(s[aPos+len(a):], b)
    if bPos != -1 {
      return true
    }
  }
  return false
}

func main() {
  scanner = bufio.NewScanner(os.Stdin)
  scanner.Split(bufio.ScanWords)
  writer := bufio.NewWriter(os.Stdout)
  defer writer.Flush()

  ab := getS()
  n := len(ab)
  baBytes := make([]byte, n)
  for i := 0; i < n; i++ {
    baBytes[i] = ab[n-1-i]
  }
  ba := string(baBytes)
  s1, s2 := getS(), getS()
  forward, backward := seek(ab, s1, s2), seek(ba, s1, s2)
  result := "fantasy"
  if forward && backward {
    result = "both"
  } else if forward {
    result = "forward"
  } else if backward {
    result = "backward"
  }
  writer.WriteString(fmt.Sprintf("%s\n", result))
}

