// github.com/EndlessCheng/codeforces-go
func CF101B(_r io.Reader, out io.Writer) {
	in := bufio.NewReader(_r)
	const mod int = 1e9 + 7

	var n, m, ans int
	Fscan(in, &n, &m)
	a := make([]struct{ l, r int }, m)
	b := make(sort.IntSlice, 0, m*2)
	for i := range a {
		Fscan(in, &a[i].l, &a[i].r)
		b = append(b, a[i].l, a[i].r)
	}
	b.Sort()
	if m == 0 || b[0] != 0 || b[m*2-1] != n {
		Fprint(out, 0)
		return
	}
	k := 0
	for _, w := range b[1:] {
		if b[k] != w {
			k++
			b[k] = w
		}
	}
	b = b[:k+1]
	sum := make([]int, m*2+1)
	sum[0] = -1
	sort.Slice(a, func(i, j int) bool { return a[i].r < a[j].r })
	for _, p := range a {
		r := b.Search(p.r)
		res := (sum[r] - sum[b.Search(p.l)]) % mod
		if p.r < n {
			sum[r+1] = (sum[r] + res) % mod
		} else {
			ans = (ans + res) % mod
		}
	}
	Fprint(out, (ans+mod)%mod)
}

func main() { CF101B(os.Stdin, os.Stdout) }

