import "fmt"

type Matrix struct {
	x [][]uint64
}

func newMatrix(dx int, dy int) Matrix {
	var r Matrix
	r.x = make([][]uint64, dx)
	for i := 0; i < dx; i++ {
		r.x[i] = make([]uint64, dy)
	}
	return r
}

func (r *Matrix) setValue(dx int, dy int, val uint64) {
	r.x[dx][dy] = val
}

func (r Matrix) multi(r1 Matrix, m uint64) Matrix {
	res := newMatrix(2, 2)
	for i := 0; i < 2; i++ {
		for j := 0; j < 2; j++ {
			for k := 0; k < 2; k++ {
				res.x[i][j] = (res.x[i][j] + r.x[i][k]*r1.x[k][j]) % m
			}
		}
	}
	return res
}

func (r Matrix) powerMod(a uint64, b uint64) Matrix {
	matrix := newMatrix(2, 2)
	matrix.setValue(0, 0, 1)
	matrix.setValue(0, 1, 1)
	matrix.setValue(1, 0, 1)
	for a > 0 {
		if a%2 == 1 {
			matrix = matrix.multi(r, b)
		}
		r = r.multi(r, b)
		a /= 2
	}
	return matrix
}

func ok(u uint64, l uint64, r uint64, k uint64) bool {
	if (r/u - (l-1)/u) >= k {
		return true
	}
	return false
}

func main() {
	var m uint64
	var l uint64
	var r uint64
	var k uint64
	fmt.Scanf("%d%d%d%d", &m, &l, &r, &k)
	var found uint64
	for i := uint64(1); i*i <= r; i++ {
		if ok(i, l, r, k) {
			if i > found {
				found = i
			}
		}
		if ok(r/i, l, r, k) {
			if r/i > found {
				found = r / i
			}
		}
	}
	if found <= 2 {
		fmt.Println(1)
		return
	}
	matrix := newMatrix(2, 2)
	matrix.setValue(0, 0, 1)
	matrix.setValue(0, 1, 1)
	matrix.setValue(1, 0, 1)
	matrix = matrix.powerMod(found-2, m)
	fmt.Println(matrix.x[0][0])
}

