package main

import (
	"fmt"
	"sort"
)

const mod = 1e9 + 7

var dp [202][1002][202]int64

func main() {
	var n, k int
	fmt.Scan(&n, &k)
	a := make([]int, n)
	for i := range a {
		fmt.Scan(&a[i])
	}
	sort.Ints(a)
	dp[0][0][1] = 1
	dp[0][0][0] = 1
	for i := 1; i < n; i++ {
		diff := a[i] - a[i-1]
		for imb := 0; imb <= k; imb++ {
			for g := 0; g <= i + 1; g++ {
				imb0 := imb - diff*g
				if imb0 >= 0 {
					dp[i][imb][g] = dp[i-1][imb0][g] * int64(g+1) % mod
				}
				if g+1 <= n && imb0-diff >= 0 {
					dp[i][imb][g] = (dp[i][imb][g] + dp[i-1][imb0-diff][g+1]) % mod
				}
				if g > 0 && imb0 + diff >= 0 {
					dp[i][imb][g] = (dp[i][imb][g] + dp[i-1][imb0+diff][g-1]) % mod
				}
			}
		}
	}
	var res int64
	for i := 0; i <= k; i++ {
		res = (res + dp[n-1][i][0]) % mod
	}
	fmt.Println(res)
}

