package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

func problem7B(_r io.Reader, out io.Writer) {
	in := bufio.NewReader(_r)
	var t, m int
	var cmd string
	var arg int
	fmt.Fscan(in, &t, &m)

	id := 1
	blocks := [][3]int{}
	var ok bool
	for i := 0; i < t; i++ {
		fmt.Fscan(in, &cmd)
		switch cmd {
		case "alloc":
			fmt.Fscan(in, &arg)
			// fmt.Println(i, cmd, arg, blocks)
			ok, blocks = alloc(arg, m, id, blocks)
			if !ok {
				fmt.Fprintln(out, "NULL")
			} else {
				fmt.Fprintln(out, id)
				id++
			}
		case "erase":
			fmt.Fscan(in, &arg)
			ok, blocks = erase(arg, blocks)
			if !ok {
				fmt.Fprintln(out, "ILLEGAL_ERASE_ARGUMENT")
			}
		case "defragment":
			blocks = defrag(blocks)
		}
	}
}

func alloc(x, m, id int, blocks [][3]int) (bool, [][3]int) {
	res := [3]int{id, -1, -1}
	if len(blocks) == 0 && x > m {
		return false, blocks
	}
	if len(blocks) == 0 || blocks[0][1] >= x {
		res[1] = 0
		res[2] = x
		return true, append([][3]int{res}, blocks...)
	}
	for idx := 1; idx < len(blocks); idx++ {
		lo := blocks[idx-1][2]
		hi := blocks[idx][1]
		if lo+x <= hi {
			res[1] = lo
			res[2] = lo + x
			return true, append(blocks[:idx], append([][3]int{res}, blocks[idx:]...)...)
		}
	}
	lo := blocks[len(blocks)-1][2]
	if lo+x <= m {
		res[1] = lo
		res[2] = lo + x
		return true, append(blocks, res)
	}
	return false, blocks
}

func erase(x int, blocks [][3]int) (bool, [][3]int) {
	for i := range blocks {
		if blocks[i][0] == x {
			blocks = append(blocks[:i], blocks[i+1:]...)
			return true, blocks
		}
	}
	return false, blocks
}

func defrag(blocks [][3]int) [][3]int {
	end := 0
	for i := range blocks {
		if blocks[i][1] > end {
			sz := blocks[i][2] - blocks[i][1]
			blocks[i][1] = end
			blocks[i][2] = blocks[i][1] + sz
			end = blocks[i][2]
		}
	}
	return blocks
}

func main() { problem7B(os.Stdin, os.Stdout) }

