package main

import(
	"fmt"
	"sort"
	"os"
	"bufio"
	// "math"
	// "strconv"
	// "strings"
)

func min(a,b int) int{
	if a<b{
		return a
	}
	return b
}

func max(a,b int) int{
	if a>b{
		return a
	}
	return b
}

func toInt(buf []byte) (o int) {
    for _, v := range buf {
        o = o*10 + int(v-'0')
    }
    return
}

type pair struct {
	first int
	second int
}

type pairs []pair

func (a pairs) Len() int {return len(a)}
func (a pairs) Swap(i,j int) {a[i], a[j] = a[j], a[i]}
func (a pairs) Less(i,j int) bool {
	return a[i].first < a[j].first
	if a[i].first > a[j].first {
		return false
	}
	return a[i].second <= a[j].second
}

var points [2][]pair
var g [100005][]int
var used,used_x,used_y [100005]bool
var diff_x,diff_y []int
var cycle_found bool
var MD int64 = 1000000007


func deg(d int) int64 {
	if d == 0 {
		return 1
	}
	t := deg(d / 2)
	t *= t
	t %= MD
	if d % 2 == 1 {
		t = t * 2 % MD
	}
	return t
}

func dfs(v,p int) {
	used[v] = true
	if !used_x[points[0][v-1].first] {
		used_x[points[0][v-1].first] = true
		diff_x = append(diff_x, points[0][v-1].first)
	}
	if !used_y[points[0][v-1].second] {
		used_y[points[0][v-1].second] = true
		diff_y = append(diff_y, points[0][v-1].second)
	}
	for i:= range g[v] {
		to := g[v][i]
		if to == p {
			continue
		}
		if used[to] {
			cycle_found = true
			continue
		}
		dfs(to,v)
	}
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	scanner.Scan()
	n := toInt(scanner.Bytes())
	mp := make(map[pair]int)
	for i:=1;i<=n;i++ {
		scanner.Scan()
		x := toInt(scanner.Bytes())
		scanner.Scan()
		y := toInt(scanner.Bytes())
		mp[pair{x,y}] = i
		points[0] = append(points[0], pair{x,y})
		points[1] = append(points[1], pair{y,x})
	}
	sort.Sort(pairs(points[0]))
	sort.Sort(pairs(points[1]))
	for i:= range points[0] {
		if i > 0 {
			if points[0][i].first == points[0][i - 1].first {
				x := mp[points[0][i]]
				y := mp[points[0][i - 1]]
				g[x] = append(g[x], y)
				g[y] = append(g[y], x)
				//fmt.Println(">>",x,y)
			}
		}
	}

	for i:= range points[1] {
		if i > 0 {
			if points[1][i].first == points[1][i - 1].first {
				x := mp[pair{points[1][i].second, points[1][i].first}]
				y := mp[pair{points[1][i - 1].second, points[1][i - 1].first}]
				g[x] = append(g[x], y)
				g[y] = append(g[y], x)
				//fmt.Println(">>",x,y)
			}
		}
	}

	var ans int64
	ans = 1

	for i:= 1;i<= n;i++ {
		if !used[i] {
			cycle_found = false
			for j:= range diff_x {
				used_x[diff_x[j]] = false
			}
			for j:= range diff_y {
				used_y[diff_y[j]] = false
			}
			diff_x = nil
			diff_y = nil
			dfs(i,i)
			res := deg(len(diff_x) + len(diff_y))
			//fmt.Println(res)
			if !cycle_found {
				res--
			}
			if res < 0 {
				res += MD
			}
			ans = ans * res % MD
		}
	}
	fmt.Println(ans)
}

