var g [100005][]int
var used [100005]bool
var diff_x,diff_y []int
var cycle_found bool
var MD int64 = 1000000007
var used_x,used_y map[int]bool
var n,x,y int

func deg(d int) int64 {
	if d == 0 {
		return 1
	}
	t := deg(d / 2)
	t *= t
	t %= MD
	if d % 2 == 1 {
		t = t * 2 % MD
	}
	return t
}

func dfs(v,p int) {
	used[v] = true
	if !used_x[pts[v].first] {
		used_x[pts[v].first] = true
		diff_x = append(diff_x, pts[v].first)
	}
	if !used_y[pts[v].second] {
		used_y[pts[v].second] = true
		diff_y = append(diff_y, pts[v].second)
	}
	for i:= range g[v] {
		to := g[v][i]
		if to == p {
			continue
		}
		if used[to] {
			cycle_found = true
			continue
		}
		dfs(to,v)
	}
}

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscanf(in, "%d\n", &n)
	mp := make(map[pair]int)
	used_x = make(map[int]bool)
	used_y = make(map[int]bool)
	for i:=1;i<=n;i++ {
		fmt.Fscanf(in, "%d %d\n",&x,&y)
		mp[pair{x,y}] = i
		pts[i] = pair{x,y}
		points[0] = append(points[0], pair{x,y})
		points[1] = append(points[1], pair{y,x})
	}
	sort.Sort(pairs(points[0]))
	sort.Sort(pairs(points[1]))
	for i:= range points[0] {
		if i > 0 {
			if points[0][i].first == points[0][i - 1].first {
				x := mp[points[0][i]]
				y := mp[points[0][i - 1]]
				g[x] = append(g[x], y)
				g[y] = append(g[y], x)
				//fmt.Println(">>",x,y)
			}
		}
	}

	for i:= range points[1] {
		if i > 0 {
			if points[1][i].first == points[1][i - 1].first {
				x := mp[pair{points[1][i].second, points[1][i].first}]
				y := mp[pair{points[1][i - 1].second, points[1][i - 1].first}]
				g[x] = append(g[x], y)
				g[y] = append(g[y], x)
				//fmt.Println(">>",x,y)
			}
		}
	}

	var ans int64
	ans = 1

	for i:= 1;i<= n;i++ {
		if !used[i] {
			cycle_found = false
			for j:= range diff_x {
				used_x[diff_x[j]] = false
			}
			for j:= range diff_y {
				used_y[diff_y[j]] = false
			}
			diff_x = nil
			diff_y = nil
			dfs(i,i)
			//fmt.Println(len(diff_x),len(diff_y))
			res := deg(len(diff_x) + len(diff_y))
			if !cycle_found {
				res--
			}
			if res < 0 {
				res += MD
			}
			ans = ans * res % MD
		}
	}
	fmt.Println(ans)
}

