	fmt.Fscanf(reader, "%d %d\n", &t, &m)
	nextId := 1
	memory := &Block{0, m, nil}

	for i := 0; i < t; i++ {
		var op string
		var x int
		fmt.Fscanf(reader, "%s", &op)
		switch op {
		case "alloc":
			fmt.Fscanf(reader, " %d\n", &x)
			flag := false
			for p := memory; p != nil; p = p.nextBlock {
				if p.id == 0 {
					for q := p.nextBlock; q != nil && q.id == 0; q = p.nextBlock {
						p.nextBlock = q.nextBlock
						p.length += q.length
					}
				} else {
					continue
				}
				if p.length == x {
					p.id = nextId
					nextId++
					fmt.Printf("%d\n", p.id)
					flag = true
					break
				} else if p.length > x {
					q := &Block{0, p.length - x, p.nextBlock}
					p.length = x
					p.nextBlock = q
					p.id = nextId
					nextId++
					fmt.Printf("%d\n", p.id)
					flag = true
					break
				}
			}
			if !flag {
				fmt.Printf("NULL\n")
			}
		case "erase":
			fmt.Fscanf(reader, " %d\n", &x)
			flag := false
			for p := memory; p != nil; p = p.nextBlock {
				if p.id == x && p.id != 0 {
					p.id = 0
					flag = true
				}
			}
			if !flag {
				fmt.Printf("ILLEGAL_ERASE_ARGUMENT\n")
			}
		case "defragment":
			fmt.Fscanf(reader, "\n")
			for p := memory; p != nil && p.nextBlock != nil; p = p.nextBlock {
				if p.id != 0 {
					continue
				}
				for q := p.nextBlock; q != nil; q = p.nextBlock {
					if p.id == 0 && q.id == 0 {
						p.length += q.length
						p.nextBlock = q.nextBlock
					} else if p.id == 0 && q.id != 0 {
						p.id, q.id = q.id, p.id
						p.length, q.length = q.length, p.length
						break
					} else {
						break
					}
				}
			}
		}
	}
}

