}

func readInt(bytes []byte, from int, val *int) int {
	i := from
	sign := 1
	if bytes[i] == '-' {
		sign = -1
		i++
	}
	tmp := 0
	for i < len(bytes) && bytes[i] >= '0' && bytes[i] <= '9' {
		tmp = tmp*10 + int(bytes[i]-'0')
		i++
	}
	*val = tmp * sign
	return i
}

func readNum(reader *bufio.Reader) (a int) {
	bs, _ := reader.ReadBytes('\n')
	readInt(bs, 0, &a)
	return
}

func readTwoNums(reader *bufio.Reader) (a int, b int) {
	res := readNNums(reader, 2)
	a, b = res[0], res[1]
	return
}

func readThreeNums(reader *bufio.Reader) (a int, b int, c int) {
	res := readNNums(reader, 3)
	a, b, c = res[0], res[1], res[2]
	return
}

func readNNums(reader *bufio.Reader, n int) []int {
	res := make([]int, n)
	x := 0
	bs, _ := reader.ReadBytes('\n')
	for i := 0; i < n; i++ {
		for x < len(bs) && (bs[x] < '0' || bs[x] > '9') {
			x++
		}
		x = readInt(bs, x, &res[i])
	}
	return res
}

func readUint64(bytes []byte, from int, val *uint64) int {
	i := from

	var tmp uint64
	for i < len(bytes) && bytes[i] >= '0' && bytes[i] <= '9' {
		tmp = tmp*10 + uint64(bytes[i]-'0')
		i++
	}
	*val = tmp

	return i
}

const H = 17
const INF = 10000

func solve(n int, a int, b int, h []int) []int {
	for i := 0; i < n; i++ {
		h[i]++
	}
	if n == 3 {
		var res []int
		for h[0] > 0 || h[1] > 0 || h[2] > 0 {
			h[0] = max(0, h[0]-b)
			h[1] = max(0, h[1]-a)
			h[2] = max(0, h[2]-b)
			res = append(res, 2)
		}
		return res
	}
	dp := make([][][]int, n)
	for i := 0; i < n; i++ {
		dp[i] = make([][]int, h[i]+1)
		for j := 0; j <= h[i]; j++ {
			dp[i][j] = make([]int, 1+(H+a-1)/a)
			for k := 0; k < len(dp[i][j]); k++ {
				dp[i][j][k] = INF
			}
		}
	}
	dp[0][h[0]][0] = 0

	for i := 1; i < n-1; i++ {
		for j := 0; j <= h[i-1]; j++ {
			for k := 0; k < len(dp[i-1][j]); k++ {
				if dp[i-1][j][k] >= INF {
					continue
				}
				//first: need to make sure attacks at this archer can make h[i-1] to be zero
				for kk := 0; kk < len(dp[i][j]); kk++ {
					jj := max(0, h[i]-b*k-a*kk)
					if kk*b >= j {
						dp[i][jj][kk] = min(dp[i][jj][kk], dp[i-1][j][k]+kk)
					}
				}
			}
		}
	}

	for j := 0; j <= h[n-2]; j++ {
		for k := 0; k < len(dp[n-2][j]); k++ {
			if dp[n-2][j][k] >= INF {
				continue
			}
			if k*b >= h[n-1] {
				dp[n-1][0][0] = min(dp[n-1][0][0], dp[n-2][j][k])
			}
		}
	}
	best := dp[n-1][0][0]
	res := make([]int, 0, best)

	for i := n - 2; i > 0; i-- {
		var found = false
		for j := 0; j <= h[i] && !found; j++ {
			for k := 0; k < len(dp[i][j]) && !found; k++ {
				if dp[i][j][k] == best {
					for x := 0; x < k; x++ {
						res = append(res, i+1)
					}
					best -= k
					found = true
				}
			}
		}
	}

	return res
}

func max(a, b int) int {
	if a >= b {
		return a
	}
	return b
}

func min(a, b int) int {
	if a <= b {
		return a
	}
	return b
}

