package main

import (
	"bytes"
	"fmt"
	"io/ioutil"
	"os"
)

type Node struct {
	max int
	min int
}

var n int
var h [100000]int

func create(tree []*Node, l int, r int, index int) {
	if l == r {
		tree[index] = &Node{h[l], h[r]}
		return
	}
	mid := (l + r) / 2
	create(tree, l, mid, index*2+1)
	create(tree, mid+1, r, index*2+2)
	max, min := tree[index*2+1].max, tree[index*2+1].min
	if max < tree[index*2+2].max {
		max = tree[index*2+2].max
	}
	if min > tree[index*2+2].min {
		min = tree[index*2+2].min
	}
	tree[index] = &Node{max, min}
}

func query(tree []*Node, l int, r int, index int, lIndex int, rIndex int) (int, int) {
	if l == lIndex && r == rIndex {
		return tree[index].max, tree[index].min
	}
	mid := (l + r) / 2
	if rIndex <= mid {
		return query(tree, l, mid, index*2+1, lIndex, rIndex)
	}
	if lIndex >= mid+1 {
		return query(tree, mid+1, r, index*2+2, lIndex, rIndex)
	}
	max, min := query(tree, l, mid, index*2+1, lIndex, mid)
	max1, min1 := query(tree, mid+1, r, index*2+2, mid+1, rIndex)
	if max < max1 {
		max = max1
	}
	if min > min1 {
		min = min1
	}
	return max, min
}

func main() {
	bs, _ := ioutil.ReadAll(os.Stdin)
	reader := bytes.NewBuffer(bs)
	var n, k int

	fmt.Fscanf(reader, "%d %d\n", &n, &k)
	for i := 0; i < n; i++ {
		fmt.Fscanf(reader, "%d ", &h[i])
	}
	tree := make([]*Node, 1000000)
	create(tree, 0, n-1, 0)

	lp, rp := 0, 0
	best := 0
	var solu []*Node
	for rp != n {
		max, min := query(tree, 0, n-1, 0, lp, rp)
		if max-min > k {
			lp++
		} else if best == rp-lp+1 {
			solu = append(solu, &Node{rp, lp})
			rp++
		} else if best < rp-lp+1 {
			best = rp - lp + 1
			solu = make([]*Node, 0, 100000)
			solu = append(solu, &Node{rp, lp})
			rp++
		} else {
			rp++
		}
	}

	writer := bytes.NewBuffer(make([]byte, 0, 12000000))
	fmt.Fprintf(writer, "%d %d\n", best, len(solu))
	for i := 0; i < len(solu); i++ {
		fmt.Fprintf(writer, "%d %d\n", solu[i].min+1, solu[i].max+1)
	}
	writer.WriteTo(os.Stdout)

}

