	"strings"
)

var (
	in  = bufio.NewReader(os.Stdin)
	out = bufio.NewWriter(os.Stdout)
)

var n, m int
var vType []Type
var edges [][]int

func main() {
	defer out.Flush()
	fmt.Fscan(in, &n, &m)
	vType = make([]Type, n)
	edges = make([][]int, n)
	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(in, &a, &b)
		a--
		b--
		edges[a] = append(edges[a], b)
		edges[b] = append(edges[b], a)
	}
	if ok, a, b, c := solve(); ok {
		fmt.Fprintln(out, "Yes")
		fmt.Fprintln(out, strings.Repeat("a", a)+strings.Repeat("b", b)+strings.Repeat("c", c))
	} else {
		fmt.Fprintln(out, "No")
	}
}

func solve() (ok bool, a, b, c int) {
	for v := range edges {
		if len(edges[v]) == n-1 {
			vType[v] = B
		}
	}
	for v := range vType {
		if vType[v] == UNSEEN {
			mark(v, A)
			break
		}
	}
	for v := range vType {
		if vType[v] == UNSEEN {
			mark(v, C)
			break
		}
	}
	for v := range vType {
		switch vType[v] {
		case UNSEEN:
			ok = false
			return
		case A:
