package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

const MaxNum = 200001

func Solve(n int, k int, a []int) int {
	divs := make([][]int, MaxNum)
	for _, elem := range a {
		count := 0
		for elem > 0 {
			divs[elem] = append(divs[elem], count)
			elem /= 2
			count += 1
		}
	}
	ans := MaxNum
	for _, d := range divs {
		sort.Ints(d)
		sum := 0
		for i := 0; i < len(d) && i < k; i++ {
			sum += d[i]
		}
		if len(d) >= k && sum < ans {
			ans = sum
		}
	}
	return ans
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, k int
	fmt.Fscanf(reader, "%d %d\n", &n, &k)
	a := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscanf(reader, "%d", &a[i])
	}

	fmt.Fprintf(writer, "%d\n", Solve(n, k, a))
}

