package main

import (
	"bufio"
	"fmt"
	"os"
)

type Edge struct {
	from int
	to   int
}

type QueueItem struct {
	town int
	d    int
}

func bfs(n int, matrix [][]int, flag int) int {
	queue := []QueueItem{{1, 0}}
	visited := make(map[int]bool)
	visited[1] = true
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		if current.town == n {
			return current.d
		}
		for v := 1; v <= n; v++ {
			if !visited[v] && matrix[current.town-1][v-1] == flag {
				visited[v] = true
				queue = append(queue, QueueItem{v, current.d + 1})
			}
		}
	}
	return -1
}

func createMatrix(n int, edges []Edge) [][]int {
	adjMatrix := make([][]int, n)
	for i := 0; i < n; i++ {
		adjMatrix[i] = make([]int, n)
	}
	for _, edge := range edges {
		adjMatrix[edge.to-1][edge.from-1] = 1
		adjMatrix[edge.from-1][edge.to-1] = 1
	}
	return adjMatrix
}

func Solve(n int, edges []Edge) int {
	matrix := createMatrix(n, edges)
	if matrix[0][n-1] == 1 {
		return bfs(n, matrix, 0)
	}
	return bfs(n, matrix, 1)
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, m int
	fmt.Fscanf(reader, "%d %d\n", &n, &m)
	edges := make([]Edge, m)
	for i := 0; i < m; i++ {
		fmt.Fscanf(reader, "%d %d\n", &edges[i].from, &edges[i].to)
	}

	fmt.Fprintf(writer, "%d\n", Solve(n, edges))
}

