process.stdin.on('data', inputStdin => {
    inputString += inputStdin;
});

process.stdin.on('end', _ => {
    inputString = inputString.trim().split('\n').map(string => {
        return string.trim();
    });

    main();
});

function readline() {
    return inputString[currentLine++];
}

function pi(a) {
    return parseInt(a);
}

function ti(a){
    for(let i = 0; i < a.length; i++)
        a[i] = pi(a[i]);

    return a;
}

function dsu(n){
    this.parent = new Array(n);
    for(let i = 0; i < n; i++)
        this.parent[i] = i;

    this.find = (x) => {
        if(this.parent[x] === x)
            return this.parent[x];

        return this.find(this.parent[x]);
    }

    this.union = (x,y) => {
        this.parent[this.find(x)] = this.find(y);
    }
}

function main(){
    let n = pi(readline());
    let mapX = new Array(1005);
    let mapY = new Array(1005);
    mapX.fill(-1);
    mapY.fill(-1);
    let uf = new dsu(n);

    for(let i = 0; i < n; i++){
        let [x,y] = ti(readline().split(' '));
        if(mapX[x] !== -1){
            uf.union(mapX[x], i);
        }else{
            mapX[x] = i;
        }

        if(mapY[y] !== -1){
            uf.union(mapY[y], i);
        }else{
            mapY[y] = i;
        }
    }

    let res = 0;
    for(let i = 0; i < n; i++)
        if(uf.parent[i] === i)
            res += 1;

    console.log(Math.floor(res / 2));
}

