function calculateCutArea(input) {
  const [h, w] = input.split(' ').map(Number);

  // Initialize variables to store the best cut area
  let bestHeight = 0;
  let bestWidth = 0;
  let bestArea = 0;

  // Iterate over possible height values
  for (let height = h; height >= Math.ceil(h * 0.8); height--) {
    // Calculate the corresponding width based on the height and the allowed ratio
    const width = Math.floor(height / 0.8);

    // Check if the width is a power of 2
    if ((width & (width - 1)) === 0) {
      // Calculate the area of the current cut area
      const area = height * width;

      // Update the best cut area if the current area is larger
      if (area > bestArea) {
        bestHeight = height;
        bestWidth = width;
        bestArea = area;
      }
    }
  }

  return `${bestHeight} ${bestWidth}`;
}

const inputs = ['2 1\n', '2 2\n', '5 5\n'];
const outputs = inputs.map(calculateCutArea);

JSON.stringify(outputs);

