fun main() {
    val r = System.`in`.bufferedReader()
    val s = StringBuilder()
    val l = r.readLine()!!.toInt()
    val day = r.readLine()!!.split(" ").map { it.toInt() }
    fun f(i: Int, type: Int): Int =
        when{
            i == l-1 -> if (type==day[i]||day[i]==3) 0 else 1
            type==day[i]||day[i]==3 -> f(i+1, 3-type)
            else -> 1+ minOf(f(i+1, type), f(i+1, 3-type))
        }
    println(minOf(f(0, 1), f(0, 2)))
}

