fun readDoubles() = readWords().map { it.toDouble() }
fun readLines(n: Int) = List(n) { readLn() }

fun Boolean.yesNo() = if (this) "YES" else "NO"
fun writeLn(s: String) = writer.write("$s\n")

@JvmName("writeLn1")
fun String.writeLn() = writer.write("\n")

// Functional
fun List<Int>.cumulativeSum1() = runningFold(0) { x, y -> x + y }
fun List<Int>.cumulativeSum() = cumulativeSum1().drop(1)

@JvmName("cumulativeSum1Long")
fun List<Long>.cumulativeSum1() = runningFold(0L) { x, y -> x + y }

@JvmName("cumulativeSumLong")
fun List<Long>.cumulativeSum() = cumulativeSum1().drop(1)

fun <E> List<E>.isDistinct() = size == toSet().size

fun <T> List<T>.histogram() = groupingBy { it }.eachCount().withDefault { 0 }
fun String.histogram() = groupingBy { it }.eachCount().withDefault { 0 }

fun <T> List<T>.groupContiguous(): List<List<T>> {
  val groups = mutableListOf<MutableList<T>>()
  forEach { e ->
    if (e == groups.lastOrNull()?.lastOrNull()) {
      groups.last().add(e)
    } else {
      groups.add(mutableListOf(e))
    }
  }
  return groups
}

fun <T> permutationsWithReplacement(input: Set<T>, n: Int): List<List<T>> =
  if (n <= 0) listOf(emptyList())
  else input.flatMap { first ->
    permutationsWithReplacement(input, n - 1).map { rest ->
      listOf(first) + rest
    }
  }

fun <T> permutations(input: Set<T>): List<List<T>> {
  if (input.isEmpty()) return listOf(emptyList())

  val first = input.first()
  val tail = input.drop(1).toSet()

  return permutations(tail).flatMap { rest ->
    (0..rest.size).map {
      buildList {
        addAll(rest.take(it))
        add(first)
        addAll(rest.drop(it))
      }
    }
  }
}

fun <T> combinations(input: Set<T>, n: Int): Set<Set<T>> {
  if (n <= 0) return setOf(emptySet())
  if (input.isEmpty()) return emptySet()

  val first = input.take(1).toSet()
  val tail = input.drop(1).toSet()

  return combinations(tail, n - 1).map { rest -> first + rest }.toSet() + combinations(tail, n)
}

// Math
fun Int.isOdd() = this % 2 == 1
fun Long.isOdd() = this % 2 == 1L
fun Int.isEven() = !isOdd()
fun Long.isEven() = !isOdd()
fun Int.isZero() = this == 0
fun Long.isZero() = this == 0L
fun Int.isPositive() = this > 0
fun Long.isPositive() = this > 0L
fun Int.isNegative() = this < 0
fun Long.isNegative() = this < 0L
fun Int.isPositiveOrZero() = this >= 0
fun Long.isPositiveOrZero() = this >= 0L
fun Int.isNegativeOrZero() = this <= 0
fun Long.isNegativeOrZero() = this <= 0L

infix fun Int.divides(o: Int) = o % this == 0
infix fun Long.divides(o: Long) = o % this == 0L
infix fun Int.divisibleBy(o: Int) = o divides this
infix fun Long.divisibleBy(o: Long) = o divides this

infix fun Int.floorDiv(o: Int) = floor(toDouble() / o).toInt()
infix fun Long.floorDiv(o: Long) = floor(toDouble() / o).toInt()
infix fun Int.ceilDiv(o: Int) = ceil(toDouble() / o).toInt()
infix fun Long.ceilDiv(o: Long) = ceil(toDouble() / o).toInt()

infix fun Int.mod(m: Int) = ((this % m) + m) % m
infix fun Long.mod(m: Long) = ((this % m) + m) % m

// Number Theory
fun primeSieve(n: Int): List<Boolean> {
  val s = BooleanArray(n + 1) { true }
  val limit = sqrt(n.toDouble()).toInt()
  (2..limit).forEach { i ->
    if (s[i]) (i * i..n).forEach { j -> s[j] = false }
  }
  return s.toList()
}

fun primes(n: Int) = primeSieve(n).mapIndexedNotNull { i, p -> i.takeIf { p } }

// DP
inline fun <I, O> memoize(crossinline fn: (I) -> O): ((I) -> O) = with(ConcurrentHashMap<I, O>()) {
  { input -> get(input) ?: fn(input).also { output -> set(input, output) } }
}
// endregion

fun solve(p: String, q: String): Boolean {
  if (p.length != q.length)
    return false
  val m = p.zip(q).withIndex().filter { (_, v) -> v.first != v.second }.map { it.index }
  if (m.size != 2)
    return false
  val (i, j) = m
  if (j - 1 != i)
    return false
  return p[i] == q[j] && p[j] == q[i]
}

