    var count = 0

    for (i in 0 until n) {
        if (s[i] == 'R') {
            for (j in (i + 1) until n) {
                if (s[j] == 'L') {
                    for (k in i..j) s[k] = 'x'
                    if ((j - i) % 2 == 0) count++
                    break
                }
            }
        } else continue
    }

    for (i in 0 until n) {
        if (s[i] == 'L') {
            for (j in 0..i) s[j] = 'x'
            break
        } else if (s[i] == '.') continue
        else break
    }

    for (i in (n - 1) downTo 0) {
        if (s[i] == 'R') {
            for (j in (n - 1) downTo i) s[j] = 'x'
            break
        } else if (s[i] == '.') continue
        else break
    }

    for (i in 0 until n)
        if (s[i] == '.')
            count++

    print(count)

