    val r = System.`in`.bufferedReader()
    val s = StringBuilder()
    val n = r.readLine()!!.toInt()
    var drift = MutableList(n) {
        val (a, b) = r.readLine()!!.split(" ").map { it.toInt() }
        Pair(a, b)
    }
    var ans = 0
    while (drift.isNotEmpty()) {
        ans++
        val (x, y) = drift.removeAt(0)
        val i = drift.indexOfFirst { it.first == x || it.second == y }
        val cadidate = mutableListOf<Pair<Int, Int>>()
        var nodDone = false
        if (i != -1) {
            cadidate += drift.removeAt(i)
            nodDone = true
        }
        while (nodDone) {
            nodDone = false
            for ((x1, y1) in cadidate) {
                val ind = drift.indexOfFirst { it.first == x1 || it.second == y1 }
                if (ind != -1) {
                    nodDone = true
                    cadidate += drift.removeAt(ind)
                    break
                }
            }
        }
    }
    println(ans - 1)
}

