val scanner = Scanner(System.`in`)
var n = scanner.nextInt()
val arr = Array<Array<Pair<Int, Int>>>(1000) { y -> Array<Pair<Int, Int>>(1000) { Pair(it, y) } }
var x = IntArray(1000) { -1 }
var y = IntArray(1000) { -1 }
fun get(x: Int, y: Int): Pair<Int, Int> {
    if (arr[y][x].first != x || arr[y][x].second != y)
        arr[y][x] = get(arr[y][x].first, arr[y][x].second)
    return arr[y][x]
}
fun join(x1: Int, y1: Int, x2: Int, y2: Int) {
    val root = get(x1, y1)
    arr[root.second][root.first] = get(x2, y2)
}

fun run() {

    var res = 0
    for (i in 0 until n) {
        val a = scanner.nextInt() - 1
        val b = scanner.nextInt() - 1
        if (x[b] != -1 && y[a] != -1 && get(b, x[b]) != get(y[a], a))
            res--
        if (x[b] != -1)
            join(b, a, b, x[b])
        if (y[a] != -1)
            join(b, a, y[a], a)
        if (x[b] == -1 && y[a] == -1)
            res++
        if (x[b] == -1)
            x[b] = a
        if (y[a] == -1)
            y[a] = b
    }
    println(res - 1)

}

class Scanner(s: InputStream) {
    var st: StringTokenizer? = null
    var br: BufferedReader = BufferedReader(InputStreamReader(s))
    @Throws(IOException::class)
    operator fun next(): String {
        while (st == null || !st!!.hasMoreTokens())
            st = StringTokenizer(br.readLine())
        return st!!.nextToken()
    }
    @Throws(IOException::class)
    fun nextInt(): Int {
        return Integer.parseInt(next())
    }
    @Throws(IOException::class)
    fun nextLong(): Long {
        return java.lang.Long.parseLong(next())
    }
    @Throws(IOException::class)
    fun nextLine(): String {
        return br.readLine()
    }
    @Throws(IOException::class)
    fun nextDouble(): Double {
        return java.lang.Double.parseDouble(next())
    }
    @Throws(IOException::class)
    fun ready(): Boolean {
