        "black" to c
    )

    provideAndrew(grapesMap, x)
    provideDmitri(grapesMap, y)
    provideMichal(grapesMap, z)
    if (isValidDistribution(grapesMap)) println("YES")
    else println("NO")
}

private fun getInputString() = readLine()!!
private fun getInputInt() = getInputString().toInt()

private fun provideAndrew(grapesMap: MutableMap<String, Int>, wanted: Int) {
    grapesMap["green"] = grapesMap["green"]!!.minus(wanted)
}

private fun provideDmitri(grapesMap: MutableMap<String, Int>, wanted: Int) {
    val purple = grapesMap["purple"]!!
    if(wanted <= purple) {
        grapesMap["purple"] = purple.minus(wanted)
        return
    }
    grapesMap["purple"] = 0
    grapesMap["green"] = grapesMap["green"]!!.minus(wanted - purple)
}

private fun provideMichal(grapesMap: MutableMap<String, Int>, wanted: Int) {
    grapesMap["black"] = grapesMap["black"]!!.minus(wanted)
}

private fun isValidDistribution(grapesMap: MutableMap<String, Int>) =
    grapesMap.filter { it.value >= 0 }.size == grapesMap.size

