        if (st.get(i) == 'W') {
            w.add(arr.get(i))
        }
        if (st.get(i) == 'O') {
            o.add(arr.get(i))
        }
        if (st.get(i) == 'R') {
            r.add(arr.get(i))
        }
    }

    Collections.sort(w, Collections.reverseOrder())
    Collections.sort(o, Collections.reverseOrder())
    Collections.sort(r, Collections.reverseOrder())

    var fl1 = false
    var fl2 = false

    var sum1: Long = 0L
    var sum2: Long = 0L

    var pos1 = 0
    var pos2 = 0

    if (o.size + w.size < k && o.size + r.size < k) {
        println(-1)
        return
    }

    if (o.size + w.size >= k) {
        while (pos1 + pos2 != k - 1) {
            if (pos1 == w.size || pos2 < o.size && w.get(pos1) < o.get(pos2)) {
                sum1 += o.get(pos2)
                pos2 += 1
                fl2 = true
            } else {
                sum1 += w.get(pos1)
                pos1 += 1
                fl1 = true
            }
        }

        if (fl1 && fl2) {
            if (pos2 == o.size || pos1 < w.size && w.get(pos1) >= o.get(pos2)) {
                sum1 += w.get(pos1)
            } else {
                sum1 += o.get(pos2)
            }
        } else if (pos2 != o.size && fl1) {
            sum1 += o.get(pos2)
            fl2 = true
        } else {
            sum1 += w.get(pos1)
            fl1 = true
        }
    }
    if (!fl1 || !fl2) {
            sum1 = -1
            }

    pos1 = 0
    pos2 = 0
    fl1 = false
    fl2 = false
    if (o.size + r.size >= k) {
        while (pos1 + pos2 != k - 1) {
            if (pos1 == r.size || pos2 < o.size && r.get(pos1) < o.get(pos2)) {
                sum2 += o.get(pos2)
                pos2 += 1
                fl2 = true
            } else {
                sum2 += r.get(pos1)
                pos1 += 1
                fl1 = true
