fun oneBasedArithmetic(string: String, count: Int): Int {
    val length = if (string[0] == '-') string.length - 1 else string.length
    val count1 = withNOnes(string, count, length)
    val count2 = withNPlus1Ones(string, count)
    return if (count1 < count2) count1 else count2
}

fun withNOnes(string: String, count: Int, length: Int): Int {
    val n = if (string[0] == '-') string.length - 1 else string.length
    val num = string.toLong()
    val nOnes = "1".repeat(n).toLong()
    return when {
//        n < length -> oneBasedArithmetic(string, count)
        n > length -> Int.MAX_VALUE
        num == 0L -> count
        num == -1L -> count + 1
        num == 1L -> count + 1
        num < 0L -> {
            val rem = (num % nOnes).toString()
            val quotient = num / nOnes
            if (quotient == 0L && rem.length == n+1){
                withNOnes((num + nOnes).toString(), count + n, n)
            }else
            oneBasedArithmetic(rem, count + (n * quotient.unaryMinus()).toInt())
        }
        else -> {
            val rem = (num % nOnes).toString()
            val quotient = num / nOnes
            if (quotient == 0L && rem.length == n){
                withNOnes((num - nOnes).toString(), count + n, n)
            }else
            oneBasedArithmetic(rem, count + (n * quotient).toInt())
        }
    }
}


fun withNPlus1Ones(string: String, count: Int): Int {
    val n = if (string[0] == '-') string.length - 1 else string.length
    val num = string.toLong()
    val nOnes = "1".repeat(n + 1).toLong()
    return when {
        num < 0L -> withNOnes((num + nOnes).toString(), count + n + 1, n)
        else -> withNOnes((nOnes - num).toString(), count + n + 1, n)
    }
}

