fun main(args: Array<String>) {
    try {
        val out = PrintWriter(System.out)
        val br = BufferedReader(InputStreamReader(System.`in`))
        val n = Integer.parseInt(br.readLine())
        val set = TreeSet<Pair>()

        for (i in 0..(n - 1)) {
            val st = StringTokenizer(br.readLine())
            val l = Integer.parseInt(st.nextToken())
            val r = Integer.parseInt(st.nextToken())
            val pair = Pair(l, r)
            var L = l
            var R = r
            while (true) {
                val toRight = set.ceiling(pair)
                if (toRight != null && toRight.l <= r) {
                    R = Math.max(R, toRight.r)
                    set.remove(toRight)
                } else {
                    break
                }
            }
            while (true) {
                val toLeft = set.floor(pair)
                if (toLeft != null && toLeft.r >= l) {
                    L = Math.min(L, toLeft.l)
                    set.remove(toLeft)
                } else {
                    break
                }
            }
            set.add(Pair(L, R))
            out.print(set.size.toString() + " ")
        }
        out.println()
        out.close()
    } catch (ex : IOException) {
    }
}

class Pair(internal var l: Int, internal var r: Int) : Comparable<Pair> {


    override fun compareTo(o: Pair): Int {
        return if (l != o.l) {
            Integer.compare(l, o.l)
        } else Integer.compare(r, o.r)
    }
}

