fun main() {
	readLn()
	val a = readInts().sorted()
	val m = a.last()
//	val isPrime = (0..m).map { i -> (i >= 2) && (2 until i).all { j -> i % j != 0 } }
	val myPrimes = MutableList(m + 1) { listOf<Int>() }
	val factPrimes = MutableList(m + 1) { listOf<Int>() }
	for (i in 2..m) {
		val j = (2..i).first { j -> i % j == 0 }
		myPrimes[i] = myPrimes[i / j].plus(j)
		factPrimes[i] = factPrimes[i - 1].plus(myPrimes[i]).sortedDescending()
	}
	var ans = 0
	for (x in a) {
		ans += factPrimes[x].size
	}
	var x = 0
	var b = a;
	while (true) {
		val count = mutableMapOf<Int, Int>()
		for (v in b) {
			val f = factPrimes[v]
			if (x >= f.size) continue
			val p = f[x]
			count[p] = count.getOrDefault(p, 0) + 1
		}
		val p = count.keys.firstOrNull { p -> count[p]!! * 2 > a.size } ?: break
		val c = count[p]!!
		ans += a.size - 2 * c
		b = b.filter { v ->
			val f = factPrimes[v]
			x < f.size && f[x] == p
		}
		x++
	}
	println(ans)
}

