fun main(args: Array<String>) {
    fun combinations(n: Int, k: Int): Sequence<Long> {
        return when {
            k < 0 || k > n -> emptySequence()
            n == 0 -> sequenceOf(0)
            else -> sequence {
                yieldAll(combinations(n - 1, k).map {it.shl(1)})
                yieldAll(combinations(n - 1, k - 1).map {it.shl(1) + 1})
            }
        }
    }
    val (n, m) = readLine()!!.split(" ").map {it.toInt()}
    val attempts = Array(m) {
        val s = readLine()!!.split(" ")
        Pair(s[0].toLong(2), s[1].toInt())
    }
    val answers = combinations(n, n - attempts[0].second).map {attempts[0].first xor it}
    println(answers.filter {ans -> attempts.filter { (it.first xor ans).toString(2).count {it == '1'} != n - it.second}.isEmpty()}
        .toList().size
    )
}

