import java.io.*
import java.util.*

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author aryssoncf
 */
object programkt {
    @JvmStatic
    fun main(args: Array<String>) {
        val inputStream = System.`in`
        val outputStream: OutputStream = System.out
        val `in` = InputReader(inputStream)
        val out = OutputWriter(outputStream)
        val solver = D1FrequencyProblemEasyVersion()
        solver.solve(1, `in`, out)
        out.close()
    }

    internal class D1FrequencyProblemEasyVersion {
        fun solve(testNumber: Int, `in`: InputReader, out: OutputWriter) {
            val n = `in`.readInt()
            val a = `in`.readIntArray(n)
            MiscUtils.decreaseByOne(a)
            val counter: MutableMap<Int, Int> = HashMap()
            for (x in a) {
                counter[x] = counter.getOrDefault(x, 0) + 1
            }
            var mf = 0
            val m = ArrayUtils.maxElement(a) + 1
            for (i in 1 until m) {
                if (counter[i]!! > counter[mf]!!) {
                    mf = i
                }
            }
            var ans = 0
            for (x in 0 until m) {
                if (x != mf) {
                    ans = Math.max(ans, solve(n, a, mf, x))
                }
            }
            out.printLine(ans)
        }

        fun solve(n: Int, A: IntArray, a: Int, b: Int): Int {
            val ca = ArrayUtils.count(A, a)
            val cb = ArrayUtils.count(A, b)
            val goal = ca - cb
            val pos = IntArray(ca + cb + 1)
            pos[cb] = n
            var delta = 0
            for (i in n - 1 downTo 0) {
                if (A[i] == a) {
                    delta++
                } else if (A[i] == b) {
                    delta--
                }
                if (pos[delta + cb] == 0) {
                    pos[delta + cb] = i
                }
            }
            var ans = 0
            delta = 0
            for (i in 0 until n) {
                ans = Math.max(ans, pos[goal - delta + cb] - i)
                if (A[i] == a) {
                    delta++
                } else if (A[i] == b) {
                    delta--
                }
            }
            return ans
        }
    }

    internal class OutputWriter {
        private val writer: PrintWriter

        constructor(outputStream: OutputStream?) {
            writer = PrintWriter(BufferedWriter(OutputStreamWriter(outputStream)))
        }

        constructor(writer: Writer?) {
            this.writer = PrintWriter(writer)
        }

        fun close() {
            writer.close()
        }

        fun printLine(i: Int) {
            writer.println(i)
        }
    }

    internal object MiscUtils {
        fun decreaseByOne(array: IntArray) {
            for (i in array.indices) {
                array[i]--
            }
        }
    }

    internal class InputReader(private val stream: InputStream) {
        private val buf = ByteArray(1024)
        private var curChar = 0
        private var numChars = 0
        private val filter: SpaceCharFilter? = null
        fun readIntArray(size: Int): IntArray {
            val array = IntArray(size)
            for (i in 0 until size) {
                array[i] = readInt()
            }
            return array
        }

        fun read(): Int {
            if (numChars == -1) {
                throw InputMismatchException()
            }
            if (curChar >= numChars) {
                curChar = 0
                numChars = try {
                    stream.read(buf)
                } catch (e: IOException) {
                    throw InputMismatchException()
                }
                if (numChars <= 0) {
                    return -1
                }
            }
            return buf[curChar++].toInt()
        }

        fun readInt(): Int {
            var c = read()
            while (isSpaceChar(c)) {
                c = read()
            }
            var sgn = 1
            if (c == '-'.toInt()) {
                sgn = -1
                c = read()
            }
            var res = 0
            do {
                if (c < '0'.toInt() || c > '9'.toInt()) {
                    throw InputMismatchException()
                }
                res *= 10
                res += c - '0'.toInt()
                c = read()
            } while (!isSpaceChar(c))
            return res * sgn
        }

        fun isSpaceChar(c: Int): Boolean {
            return filter?.isSpaceChar(c) ?: isWhitespace(c)
        }

        interface SpaceCharFilter {
            fun isSpaceChar(ch: Int): Boolean
        }

        companion object {
            fun isWhitespace(c: Int): Boolean {
                return c == ' '.toInt() || c == '\n'.toInt() || c == '\r'.toInt() || c == '\t'.toInt() || c == -1
            }
        }
    }

    internal object ArrayUtils {
        fun maxElement(array: IntArray?): Int {
            return Arrays.stream(array).max().asInt
        }

        fun count(array: IntArray, value: Int): Int {
            var result = 0
            for (i in array) {
                if (i == value) {
                    result++
                }
            }
            return result
        }
    }
}

