val MOD = 1_000_000_007

class Solver(stream: InputStream, private val out: java.io.PrintWriter) {
  fun solve() {
    val N = ni()
    val P1 = na(N)
    val P = P1.clone()
    zip(P)
    P.reverse()
    val T = ni()
    val Q = na(T, -1)
    val needsOpen = BooleanArray(N)
    for (i in 0 until T) {
      needsOpen[N - 1 - Q[i]] = true
    }
    val negFlg = BooleanArray(N)
    val lstOpen = ArrayDeque<Int>()
    for (i in 0 until N) {
      val canClose = lstOpen.isNotEmpty() && P[lstOpen.last] == P[i]
      val toOpen = needsOpen[i] || !canClose
      if (toOpen) {
        lstOpen.addLast(i)
      } else {
        lstOpen.removeLast()
      }
      negFlg[i] = !toOpen
    }
    if (lstOpen.isNotEmpty()) {
      out.println("NO")
    } else {
      out.println("YES")
      for (i in 0 until N) {
        P1[i] *= if (negFlg[N - 1 - i]) 1 else -1 // 反転するので
      }
      out.println(P1.joinToString(" "))
    }
  }

  fun zip(A: IntArray) {
    val ids = A.distinct().sorted().toIntArray()
    for (i in 0 until A.size) {
      A[i] = lowerBound(ids, 0, A[i])
    }
  }

  fun lowerBound(A: IntArray, s: Int, x: Int): Int {
    var l = s - 1
    var h = A.size
    while(h - l > 1) {
      val m = (h + l) / 2
      if (A[m] >= x) h = m
      else l = m
    }
    return h
  }












































