    val s = readLn()
    val k = readInt()

    val n = s.length
    val C = List(n) { IntArray(n - it + 1) }
    for (l in 2 .. n) {
        for (i in 0 .. n - l) {
            C[i][l] = C[i+1][l-2]
            if(s[i] != s[i+l-1]) C[i][l]++
        }
    }

    val D = List(k+1) { IntArray(n+1) { Int.MAX_VALUE } }
    val P = List(k+1) { IntArray(n+1) }

    D[0][0] = 0

    for(i in 0 until k) {
        for(j in 0 until n) {
