            for(l in 1 .. n-j) {
                if(D[i+1].setMin(j+l, D[i][j] + C[i][l])) P[i+1][j+l] = l
            }
        }
    }

    val kf = (0..k).minBy { D[it][n] }!!
    val cost = D[kf][n]
    val pals = Array(kf) { "" }
