import java.util.*
import java.util.Arrays.binarySearch

private const val MODULO = 1000000007

fun Long.to(): Int = (this shr 32).toInt()
fun Long.from(): Int = (this and 0xFFFF_FFFFL).toInt()

fun bus(from: Int, to: Int): Long =
        (to.toLong() shl 32) + from

class TaskD(numSegments: Int, val buses: LongArray) {
    val lastStopI: Int
    var countSum: IntArray
    var countSumSize = 0

    init {
        var allStops = IntArray(buses.size * 2 + 2)
        for (i in 0 until buses.size) {
            allStops[i * 2] = buses[i].from()
            allStops[i * 2 + 1] = buses[i].to()
        }
        allStops[allStops.size - 2] = 0
        allStops[allStops.size - 1] = numSegments
        allStops.sort()
        var i = 0
        var j = 1
        while (j < allStops.size) {
            if (allStops[i] != allStops[j]) {
                allStops[++i] = allStops[j++]
            } else {
                j++
            }
        }
        allStops = allStops.copyOf(i + 1)
        lastStopI = allStops.size - 1

        for (i in buses.indices) {
            val bus = buses[i]
            val from = binarySearch(allStops, bus.from())
            val to = binarySearch(allStops, bus.to())
            buses[i] = bus(from, to)
        }

        buses.sort()

        countSum = IntArray(allStops.size + 1)
        countSum[0] = 0
        countSum[1] = 1
        countSumSize = 2
    }

    fun result() =
            if (lastStopI + 1 >= countSumSize) 0
            else mod(countSum[lastStopI + 1] - countSum[lastStopI], MODULO)


    fun run() {
        for (b in buses) {
            val currTo = b.to()
            countSumEnsureSize(currTo + 2)
            val countDelta = mod(countSum[currTo] - countSum[b.from()], MODULO)
            addCount(currTo, countDelta)
        }
    }

    fun addCount(i: Int, d: Int) {
        for (j in (i + 1)..(countSumSize - 1))
            countSum[j] = mod(countSum[j] + d, MODULO)
    }

    fun countSumEnsureSize(size: Int) {
        if (countSumSize >= size) return
        for (i in (countSumSize - 1 + 1)..(size - 1))
            countSum[i] = countSum[i - 1]
        countSumSize = size
    }

    fun print() {
        println(result())
    }
}

