import java.util.*

fun main(args: Array<String>) {
    val sc = BufferedReader(InputStreamReader(System.`in`))
    val out = PrintWriter(BufferedOutputStream(System.out))
    val (n, m) = sc.readLine()!!.split(" ").map(String::toInt)
    if (n < 3) {
        out.println("0")
    } else {
        val graph = Graph(n)
        for (i in 0 until m) {
            val (u, v) = sc.readLine()!!.split(" ").map { it.toInt() - 1 }
            graph.addEdge(u, v)
        }
        graph.checkDeep()
        out.println(graph.count)
    }
    out.close()
}

internal class Node(val id: Int) {
    val links = LinkedList<Node>()
}

internal class Graph(var n: Int) {
    var graphArray = Array(n) { Node(it) }
    private val colors = Array(n) { 0 }
    var count: Long = 0

    fun addEdge(from: Int, to: Int) {
        graphArray[from].links.add(graphArray[to])
        graphArray[to].links.add(graphArray[from])
    }

    fun checkDeep() {
        for (i in 0 until n) {
            if (colors[i] == 0) {
                colors[i] = 1
                dfs(graphArray[i])
            }
        }
    }

    private fun dfs(n: Node) {
        for (it in n.links) {
            if (colors[it.id] == 0) {
                colors[it.id] = 1
                dfs(it)
            } else if (colors[it.id] == colors[n.id]) {
                count++
            }
        }
        colors[n.id] = 0
    }
}

