type Pair = (usize, usize);
fn input_pair() -> Pair {
    let mut buf = String::new();
    std::io::stdin().read_line(&mut buf).unwrap();
    let buf: Vec<usize> = buf
        .trim()
        .split_whitespace()
        .map(|elem| elem.parse().unwrap())
        .collect();
    (buf[0], buf[1])
}

fn minimize(num: &str, n: usize, mut k: usize) -> String {
    if n == 1 {
        String::from("0")
    } else if k == 0 {
        String::from(num)
    } else {
        num.chars()
            .zip(0..)
            .map(|(c, i)| {
                if i == 0 {
                    if c != '1' {
                        k -= 1
                    }
                    '1'
                } else if k > 0 {
                    if c != '0' {
                        k -= 1
                    }
                    '0'
                } else {
                    c
                }
            })
            .collect()
    }
}

fn main() {
    let (n, k) = input_pair();

    let mut num = String::with_capacity(n);
    std::io::stdin().read_line(&mut num).unwrap();
    let num = num.trim();

    print!("{}", minimize(&num, n, k));
}

