fn all_same(s: &String) -> bool {
    if s.len() <= 1 {
        return true;
    }
    let fch: char = s.chars().next().unwrap();
    for ch in s.chars().skip(1) {
        if ch != fch {
            return false;
        }
    }
    true
}
