use std::cmp::min;

use Direction::*;

#[derive(Debug, Eq, PartialEq)]
enum Direction { Direct, Reverse }

#[derive(Debug)]
struct Road {
    to: usize,
    direction: Direction,
    price: usize,
}

fn main() {
    let stdin = std::io::stdin();

    let mut buf = String::new();
    stdin.read_line(&mut buf).unwrap();
    let mut iter = buf.trim_end().split_whitespace();
    let cities_count: usize = iter.next().unwrap().parse().unwrap();

    let mut roads: Vec<Road> = Vec::with_capacity(cities_count);
    for _ in 0..cities_count {
        roads.push(Road {
            to: 0,
            direction: Direct,
            price: 0,
        })
    }

    for _ in 0..cities_count {
        let mut buf = String::new();
        stdin.read_line(&mut buf).unwrap();
        let mut iter = buf.trim_end().split_whitespace();
        let from:  usize = iter.next().unwrap().parse().unwrap();
        let to:    usize = iter.next().unwrap().parse().unwrap();
        let price: usize = iter.next().unwrap().parse().unwrap();

        if roads[from - 1].to == 0 {
            roads[from - 1] = Road { to, direction: Direct, price };
        } else {
            roads[to - 1] = Road { to: from, direction: Reverse, price };
        }
    }

    let direct_total_price: usize = roads
        .iter()
        .filter(|road| road.direction == Reverse)
        .map(|road| road.price)
        .sum();
    let reverse_total_price: usize = roads
        .iter()
        .filter(|road| road.direction == Direct)
        .map(|road| road.price)
        .sum();

    println!("{}", min(direct_total_price, reverse_total_price));
}

