use std::fmt::Write as OtherWrite;
use std::io::{self, Write};
use std::io::{stdin, stdout};
use std::string;

fn main() -> Result<(), io::Error> {
    let reader = stdin();
    let mut writer = stdout().lock();
    let mut lines = reader.lines();
    let s1 = lines.next().unwrap().unwrap();
    let s2 = lines.next().unwrap().unwrap();
    if let Some((index, repeat)) = solve(s1, s2) {
        writeln!(writer, "{repeat}")?;
        writeln!(
            writer,
            "{}",
            (index + 1..index + 1 + repeat)
                .map(|i| i.to_string())
                .collect::<Vec<_>>()
                .join(" ")
        )?;
    } else {
        writeln!(writer, "{}", 0)?;
    }
    Ok(())
}

fn solve(s1: String, s2: String) -> Option<(usize, usize)> {
    let mut iter2 = s2.chars().peekable();
    let mut result_index = None;
    for (i, c1) in s1.chars().enumerate() {
        if let Some(&c2) = iter2.peek() {
            if c1 != c2 {
                if result_index.is_some() {
                    return None;
                } else {
                    result_index = Some(i);
                }
            } else {
                iter2.next();
            }
        } else {
            if (s1.chars().skip(i + 1).next()) == None {
                return Some((i, 1));
            } else {
                return None;
            }
        }
    }
    let result_index = result_index?;
    let mut iter1 = s1.chars().skip(result_index);
    let c_result = iter1.next().unwrap();
    return Some((
        result_index,
        iter1.take_while(|&c| c_result == c).count() + 1,
    ));
}

