    let s1_len = s1.len();

    let prefix = prefix_length(&s1, &s2);
    let suffix = suffix_length(&s1, &s2);

    let mut total: i32 = (prefix as i32 + 1) - (s1_len as i32 - suffix as i32) + 1;

    if total < 0 {
        total = 0;
    }

    println!("{}",total);

    for i in 0..total{
        print!("{}",s1_len - suffix + i as usize + 1);
        if i < total-1{
            print!(" ");
        }else{
            println!();
        }
    }


