fn prefix_length(s1: &String, s2: &String) -> usize {

    let s1_bytes = s1.as_bytes();
    let s2_bytes = s2.as_bytes();

    let s2_len = s2.len();

    let mut i: usize = 0;
    while i < s2_len && s1_bytes[i] == s2_bytes[i] {
        i+=1;
    }

    return i-1;
}


fn suffix_length(s1: &String, s2: &String) -> usize {

    let s1_bytes = s1.as_bytes();
    let s2_bytes = s2.as_bytes();

    let s1_len = s1.len();

    let mut i: usize = s1_len - 1;

    while i > 0 && s1_bytes[i] == s2_bytes[i-1] {
        i-=1;
    }

    return s1_len - i;
}

