fn solve(s: &[bool]) -> Vec<Val> {
    fn solve_with_assumed_size(
        s: &[bool], vals: Vec<Val>,
        // f: &mut BufReader<File>,
    ) -> Result<Vec<Val>, FailReason> {
        fn rec_resolve(
            mut rg: Vec<Val>,
            s: &[bool], offset: usize,
            // f: &mut BufReader<File>,
        ) -> Result<(Vec<Val>, usize), FailReason> {
            if rg.len() <= 1 {
                return Ok((rg, offset));
            }
            let lhs_upper = rg.len() >> 1;
            let rhs = rg.drain(lhs_upper..).collect();
            let lhs = rg;
            let res = rec_resolve(lhs, s, offset).unwrap();
            let (left_part_of_pool, offset) = res;
            let res = rec_resolve(rhs, s, offset).unwrap();
            let (right_part_of_pool, offset) = res;

            Ok(resolve_pool(s, offset, left_part_of_pool, right_part_of_pool)?)
        }

        // let merge_count = f64::log2(sz as f64) as usize;
        // let mut known_relations = vec![vec![None; vals.len()]; vals.len()];

        let (vals, offset) = rec_resolve(vals, s, 0)?;
        match offset.cmp(&s.len()) {
            Ordering::Less => Err(FailReason::TooManyMerges),
            Ordering::Greater => Err(FailReason::NotEnoughMerges),

            Ordering::Equal => {
                let mut ans = vec![0; vals.len()];
                for (i, pos) in vals.into_iter().enumerate() {
                    ans[pos] = i + 1;
                }
                Ok(ans)
            }
        }
    }

    let mut lower_bound = 2;
    let mut upper_bound = 1e5 as usize;
    // let mut lower_bound = upper_bound;
    let mut vals = Vec::with_capacity(upper_bound);
    for i in 0..upper_bound {
        vals.push(i)
        // vals.push(Val { val: i, history: Cell::new(vec![]) });
    }
    let mut prev_assumed_size = None;
    loop {
        // let f = File::open("C:\\Users\\nikol\\Documents\\Jupyter\\log.txt").unwrap();
        // let mut f = BufReader::new(f);
        let assumed_size = (|| {
            let assumed_size = lower_bound + (upper_bound - lower_bound) / 2;
            if let Some(prev_assumed_size) = prev_assumed_size {
                if assumed_size == prev_assumed_size {
                    return assumed_size + 1;
                }
            }
            assumed_size
        })();
        let mut vals_to_pass = vec![];
        for i in 0..assumed_size {
            vals_to_pass.push(i);
            // let val = &mut vals[i];
            // vals_to_pass.push(Val {
            //     val: val.val,
            //     history: Cell::new(val.history.get_mut().clone()),
            // })
        }
        match solve_with_assumed_size(s, vals_to_pass) {
            Ok(ans) => return ans,
            Err(FailReason::NotEnoughMerges) => {
                upper_bound = assumed_size;
            }
            Err(FailReason::TooManyMerges) => {
                lower_bound = assumed_size;
            }
        }
        prev_assumed_size = Some(assumed_size);
    }
}

