fn main() {
    const M: usize = 'z' as usize - 'a' as usize + 1;

    let (n, l, k) = read_tuple!(usize, usize, usize);
    let s = read_str();
    let nums = s.citer().fold(vec![0; M], |mut nums, c| {
        nums[c as usize - 'a' as usize] += 1;
        nums
    });

    let (words, ..) = nums.citer().enumerate().fold(
        (vec![vec![]; n], 0, 0, 0),
        |(mut words, i, st, j), (c, m)| {
            let (mut mm, i1, st1) = (i..l)
                .flat_map(|ii| (st..k).map(move |p| (ii, p)))
                .take(m)
                .fold((m, l, 0), |(mm, _, _), (ii, p)| {
                    words[p].push((c + 'a' as usize) as u8 as char);

                    (
                        mm - 1,
                        ii + (p + 1 - st) / (k - st),
                        (p + 1 - st) % (k - st) + st,
                    )
                });

            for jj in j..n {
                while words[jj].len() < l {
                    if mm == 0 {
                        return (words, i1, st1, jj);
                    }

                    words[jj].push((c + 'a' as usize) as u8 as char);
                    mm -= 1;
                }
            }

            return (words, i1, st1, n);
        },
    );

    use io::{BufWriter, Write};
    let stdout = io::stdout();
    let mut stdout = BufWriter::new(stdout.lock());
    for word in words {
        writeln!(stdout, "{}", word.citer().join("")).unwrap();
    }
}

