use std::collections::HashSet;
use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|x| x.unwrap());
    let n: usize = lines.next().unwrap().parse().unwrap();

    let mut possible_moves: Vec<String> = Vec::new();
    for _ in 0..n {
        possible_moves.push(lines.next().unwrap());
    }

    let mut possible_positions: HashSet<(i32, i32)> = HashSet::new();
    possible_positions.insert((0, 0));

    for moves in possible_moves {
        let mut new_positions: HashSet<(i32, i32)> = HashSet::new();
        for position in possible_positions {
            let (x, y) = position;
            match moves.as_str() {
                "UL" => {
                    new_positions.insert((x - 1, y));
                    new_positions.insert((x, y + 1));
                }
                "UR" => {
                    new_positions.insert((x + 1, y));
                    new_positions.insert((x, y + 1));
                }
                "DL" => {
                    new_positions.insert((x - 1, y));
                    new_positions.insert((x, y - 1));
                }
                "DR" => {
                    new_positions.insert((x + 1, y));
                    new_positions.insert((x, y - 1));
                }
                "ULDR" => {
                    new_positions.insert((x - 1, y));
                    new_positions.insert((x + 1, y));
                    new_positions.insert((x, y + 1));
                    new_positions.insert((x, y - 1));
                }
                _ => panic!("Invalid movement string"),
            }
        }
        possible_positions = new_positions;
    }

    println!("{}", possible_positions.len());
}

