        println!("YES");
    } else {
        println!("NO");
    }
}
fn join(a: usize, b: usize, arr: &mut Vec<usize>) {
    let a = find(a, arr);
    let b = find(b, arr);
    arr[a] = b;
}
fn find(mut x: usize, arr: &mut Vec<usize>) -> usize {
    while x != arr[x] { arr[x] = arr[arr[x]]; x = arr[x]; }
    x
}

