fn chmax(s: &mut Vec<u8>, t: &[u8]) {
    if s.len() < t.len() {
        *s = t.to_vec();
    }
}

const S: usize = 26;
fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let s: Vec<_> = it.next().unwrap().bytes().map(|x| x - b'A').collect();
    let t: Vec<_> = it.next().unwrap().bytes().map(|x| x - b'A').collect();
    let v: Vec<_> = it.next().unwrap().bytes().map(|x| x - b'A').collect();
    let mut next = vec![[0; S]; v.len()];
    for i in 0..v.len() {
        for j in 0u8..(S as u8) {
            let mut curs = v[..i].to_vec();
            curs.push(j);
            let mut curs: &[u8] = &curs;
            while curs != &v[..curs.len()] {
                curs = &curs[1..];
            }
            next[i][j as usize] = curs.len();
        }
    }
    let mut dp = vec![vec![vec![vec![]; v.len()]; t.len() + 1]; s.len() + 1];
    for i in 0..s.len() {
        for j in 0..t.len() {
            for k in 0..v.len() {
                let tmp = dp[i][j][k].clone();
                let _m = next[k][s[i] as usize];
                if s[i] == t[j] && _m != v.len() {
                    let m = _m;
                    let mut tmp = tmp.clone();
                    tmp.push(s[i]);
                    chmax(&mut dp[i + 1][j + 1][m], &tmp);
                } else {
                    chmax(&mut dp[i + 1][j + 1][k], &tmp);
                }
                chmax(&mut dp[i + 1][j][k], &tmp);
                chmax(&mut dp[i][j + 1][k], &tmp);
            }
        }
    }
    let mut ret = vec![];
    for i in 0..=s.len() {
        for j in 0..=t.len() {
            for k in 0..v.len() {
                chmax(&mut ret, &dp[i][j][k]);
            }
        }
    }
    let ret: String = ret.iter().map(|&b| (b + b'A') as char).collect();
    if ret.len() == 0 {
        println!("{}", 0);
    } else {
        println!("{}", ret);
    }
}

