fn main() {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    let s: Vec<u32> = s.split_whitespace().map(|x| x.parse().unwrap()).collect();

    let n = s[0];
    let m = s[1];

    let mut cols: Vec<u32> = [].to_vec();
    let mut rows: Vec<u32> = [].to_vec();
    let mut board: Vec<Vec<char>> = [].to_vec();

    for k in 0..n {
        let mut x = String::new();
        std::io::stdin().read_line(&mut x).unwrap();
        let x: Vec<char> = x.chars().collect::<Vec<char>>()[..m as usize].to_vec();
        board.push(x.clone());

        rows.push(0);

        for (i, &e) in x.iter().enumerate() {
            if e == '*' {
                rows[k as usize] += 1;
            }
            if k == 0 {
                cols.push(if e == '*' { 1 } else { 0 });
            }
            else {
                if e == '*' {
                    cols[i] += 1;
                }
            }
        }
    }

    let mut count = 0;

    for i in 0..n {
        for j in 0..m {
            if board[i as usize][j as usize] == '*' {
                count += (rows[i as usize] - 1) * (cols[j as usize] - 1);
            }
        }
    }

    println!("{}", count);
}

