use std::io::{self, BufReader, Read, Stdin, Bytes};
use std::fmt::Debug;
use std::cmp;
use std::str::FromStr;

/// A stdin helper to deal with normal oj input.
pub struct OjReader<R> {
    bs: Bytes<BufReader<R>>,
}

pub fn from_stdin() -> OjReader<Stdin> {
    let input = io::stdin();
    let reader = BufReader::new(input);
    OjReader { bs: reader.bytes() }
}

impl<R: Read> OjReader<R> {
    pub fn next<E, T>(&mut self) -> T
        where E: Debug,
              T: FromStr<Err = E>
    {
        loop {
            match self.next_opt() {
                Some(t) => return t,
                None => {},
            }
        }
    }

    pub fn next_opt<E, T>(&mut self) -> Option<T>
        where E: Debug,
              T: FromStr<Err = E>
    {
        self.next_trunk(|b| b == b' ' || b == b'\t' || b == b'\n' || b == b'\r')
    }

    // TODO: handle windows style line seperator \r\n
    fn next_trunk<E, T, F>(&mut self, is_sep: F) -> Option<T>
        where E: Debug,
              T: FromStr<Err = E>,
              F: Fn(u8) -> bool
    {
        let mut res = vec![];
        loop {
            match self.bs.next() {
                None => {
                    assert!(!res.is_empty());
                    break;
                },
                Some(r) => {
                    let b = r.unwrap();
                    if is_sep(b) {
                        break;
                    }
                    res.push(b);
                }
            }
        }
        if res.is_empty() {
            return None;
        }
        unsafe { Some(String::from_utf8_unchecked(res).parse::<T>().unwrap()) }
    }

    pub fn next_line(&mut self) -> String {
        self.next_line_opt().unwrap()
    }

    pub fn next_line_opt(&mut self) -> Option<String> {
        self.next_trunk(|b| b == b'\n' || b == b'\r')
    }
}

macro_rules! odiv {
    ($lhs:expr, $rhs:expr) => ({
        if $lhs < 0 {
            0
        } else {
            $lhs / $rhs + 1
        }
    });
}

#[derive(Debug)]
struct Problem {
    a: isize,
    b: isize,
    thls: Vec<isize>,
}

fn search(p: &mut Problem, i: usize, tmp_sol: &mut Vec<usize>, sol: &mut Vec<usize>) {
    assert!(i > 0);
    if i == p.thls.len() - 2 {
        let res = cmp::max(odiv!(p.thls[i], p.a), odiv!(cmp::max(p.thls[i - 1], p.thls[i + 1]), p.b)) as usize;
        if !sol.is_empty() && sol.len() <= tmp_sol.len() + res {
            return;
        }
        *sol = tmp_sol.clone();
        for _ in 0..res {
            sol.push(i + 1);
        }
    } else if i < p.thls.len() - 2 {
        let min = odiv!(p.thls[i - 1], p.b) as usize;
        let max = cmp::max(odiv!(p.thls[i], p.a), odiv!(p.thls[i + 1], p.b)) as usize;
        let (old_one, old_two, last_moves) = (p.thls[i], p.thls[i + 1], tmp_sol.len());
        p.thls[i] -= p.a * min as isize;
        p.thls[i + 1] -= p.b * min as isize;
        tmp_sol.resize(last_moves + min, i + 1);
        for _ in min..cmp::max(min + 1, max) {
            search(p, i + 1, tmp_sol, sol);
            p.thls[i] -= p.a;
            p.thls[i + 1] -= p.b;
            tmp_sol.push(i + 1);
            if tmp_sol.len() > sol.len() {
                break;
            }
        }
        p.thls[i] = old_one;
        p.thls[i + 1] = old_two;
        tmp_sol.truncate(last_moves);
    } else {
        unreachable!();
    }
}

// Simple a + b example
fn main() {
    let mut reader = from_stdin();
    let (n, a, b) = (reader.next(), reader.next(), reader.next());
    let mut problem = Problem {
        a: a,
        b: b,
        thls: Vec::with_capacity(n),
    };
    for _ in 0..n {
        problem.thls.push(reader.next());
    }
    let (mut tmp_sol, mut sol) = (vec![], vec![]);
    search(&mut problem, 1, &mut tmp_sol, &mut sol);
    println!("{}", sol.len());
    for idx in sol {
        print!("{} ", idx);
    }
    print!("\n");
}

