macro_rules! parse_line {
    ($t: ty) => ({
        let mut a_str = String::new();
        std::io::stdin().read_line(&mut a_str).expect("read error");
        let a_str = a_str.trim();
        a_str.parse::<$t>().expect("parse error")
    });
    ($($t: ty),+) => ({
        let mut a_str = String::new();
        std::io::stdin().read_line(&mut a_str).expect("read error");
        let mut a_iter = a_str.split_whitespace();
        (
            $(
            a_iter.next().unwrap().parse::<$t>().expect("parse error"),
            )+
        )
    })
}

#[allow(unused_macros)]
macro_rules! parse_line_to_vec {
    ($t: ty) => {{
        let mut a_str = String::new();
        std::io::stdin().read_line(&mut a_str).expect("read error");
        (a_str
            .split_whitespace()
            .map(|x| x.parse::<$t>().unwrap())
            .collect::<Vec<$t>>())
    }};
}

use std::io::Write;

fn solve(writer: &mut std::io::BufWriter<std::io::Stdout>) {
    let (n, m) = parse_line!(usize, usize);
    let mut a = Vec::new();
    let mut pro = vec![0; n];
    let mut con = vec![0; n];
    let mut cons = 0;
    for _ in 0..n {
        let x = parse_line!(i32);
        a.push(x);
        if x > 0 {
            pro[(x - 1) as usize] += 1;
        }else{
            con[(-x - 1) as usize] += 1;
            cons += 1;
        }
    }
    let mut candidates = vec![false; n];
    let mut single = false;
    let mut more = false;
    for i in 0..n {
        if pro[i] + cons - con[i] == m {
            more = single;
            single = true;
            candidates[i] = true;
        }
    }
    for x in a {
        if x > 0 {
            if candidates[(x - 1) as usize] {
                if single && !more {
                    writeln!(writer, "Truth").unwrap();
                }else{
                    writeln!(writer, "Not defined").unwrap();
                }
            }else{
                writeln!(writer, "Lie").unwrap();
            }
        }else{
            if !candidates[(-x - 1) as usize] {
                writeln!(writer, "Truth").unwrap();
            }else{
                writeln!(writer, "Not defined").unwrap();
            }
        }
    }
}

fn main() {
    let mut writer = std::io::BufWriter::new(std::io::stdout());
    let tests = 1; // parse_line!(usize);
    for _ in 0..tests {
        solve(&mut writer);
    }
}

