import std.algorithm, std.functional;
import std.array, std.container;
import std.conv;
import std.math, std.numeric;
import std.range, std.range.interfaces;
import std.stdio, std.string;
import std.typecons;

immutable long INF = 10L ^^ 18 + 23;

immutable int A = 100;

void main()
{   
    int n;
    readf("%s", &n);
    readln;
    
    auto a = readln.chomp.split.map!(to!int).array;
    
    auto sm = a.sum();
    
    if (n == 1) {
        sm.writeln;
        return;
    }
    
    int mxgain = 0;
    for (int i = 2; i < A; ++i) {
        int curbig = -1;
        for (int j = 0; j < n; ++j) {
            if (a[j] % i != 0) continue;
            
            if (curbig == -1 || a[j] > a[curbig]) curbig = j;
        }
        
        if (curbig == -1) continue;
        
        int cursm = -1;
        for (int j = 0; j < n; ++j) {
            if (j == curbig) continue;
            
            if (cursm == -1 || a[j] < cursm) cursm = j;
        }
        
        int curgain = (a[curbig] + a[cursm]) - (a[curbig] / i + a[cursm] * i);
        mxgain = max(mxgain, curgain);
    }
    
    int ans = sm - mxgain;
    ans.writeln;
}

