    int n, m;
    char[MAX_SIZE][MAX_SIZE] field;
    PigPosition[] wolfsForPig;

    readf("%d %d\n", &n, &m);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            readf("%c", &field[i][j]);
            writefln("<%c>", field[i][j]);
            if (field[i][j] == 'P') {
                wolfsForPig ~= PigPosition(i, j, 0);
                for (int k = 0; k < DX.length; ++k) {
                    int dx = i + DX[k];
                    int dy = j + DY[k];

                    if (dx >= 0 && dx < n && dy >= 0 && dy < m && field[dx][dy] == 'W') {
                        ++wolfsForPig[$ - 1].wolfs;
                    }
                }
            }
        }

        char temporary; // skip new line character
        readf("%c", &temporary);
    }

    sort!((a, b) { return a.wolfs < b.wolfs; })(wolfsForPig);

    int eatenPigs = 0;
    for (int i = 0; i < wolfsForPig.length; ++i) {
        for (int j = 0; j < DX.length; ++j) {
            int dx = wolfsForPig[i].x + DX[j];
            int dy = wolfsForPig[i].y + DY[j];

            if (dx >= 0 && dx < n && dy >= 0 && dy < m && field[dx][dy] == 'W') {
                field[dx][dy] = '.';

                ++eatenPigs;
                break;
            }
        }
    }

    writeln(eatenPigs);
}

