/**
 * CodeForces Problem 344.B (1)
 * ACM summer training contest (3b)
 * Noein
 */
 
import std.stdio;
 
T mut(T)(in T inval) {
    import std.traits;
 
    Unqual!T new_val = inval;
 
    return new_val;
}
 
T imut(T)(in T inval) {
    immutable new_val = inval;
 
    return new_val;
}

/*
  T abs(T)(in T inval) { return ((inval < 0) ? -inval : inval); }
  T min(T)(in T l, in T r) { return ((l < r) ? l : r); }
*/

char to_lower(const ref char ch, bool f = true) {
    if(f) {
        if(ch >= 'A' && ch <= 'Z') {
            int dl = ('a' - 'A');
            return cast(char)(ch + dl);
        } 
    }
    else if(ch >= 'a' && ch <= 'z') {
        int dl = ('a' - 'A');
        return cast(char)(ch - dl);
    }
    
    return ch;
}

bool chk_caps_locked(const char[] in_str) {
    bool f = true;
    foreach(c; in_str[1..$]) {
        f &= (c <= 'Z' && c >= 'A');
    }
    return f;
}

void main() {
    string maybe_caps_locked;
    
    readf("%s ", &maybe_caps_locked);
    string res;
    if(chk_caps_locked(maybe_caps_locked))
    {
        foreach(c; maybe_caps_locked) {
            res ~= c.to_lower();
        }
        res = to_lower(maybe_caps_locked[0], false) ~ res[1..$];
    }
    
    writeln(res);
}

