import std.stdio, std.algorithm, std.string, std.conv, std.range;

void main() {
    int n, a, b, c;
    readf("%d %d %d %d\n", &n, &a, &b, &c);
    dp(n, a, b, c).writeln;
}

int dp(int n, int a, int b, int c) {
    int[] r = new int[n + 1];
    foreach (e; [ a, b, c ]) {
        r[e] = 1;
    }

    foreach (int i, ref e; r) {
        if (e > 0) {
            foreach (cut; [ a, b, c ]) {
                if (i + cut <= n) {
                    r[i + cut] = max(r[i] + 1, r[i + cut]);
                }
            }
        }
    }

    return r[n];
}

