import std.stdio, std.math;

int s(long n) {
	int t = 0;
	while (n > 0) {
		t += n % 10;
		n /= 10;
	}
	return t;
}

int m(long n) {
	int t = 0;
	while (n > 0) { t++; n /= 10; }
	return t * 9;
}

/*
x^2 + tx > n
x^2 + tx + t^2/4 > n + t^2/4
x + t/2 > sqrt(4n^2+t^2)/2
x > sqrt(4n^2+t^2)/2-t/2
*/

long solve(long n) {
	long r = cast(long) sqrt(n * 1.0);
	long t = m(r);
	long l = cast(long) (sqrt(4.0 * n + 1.0 * t * t) / 2 - t / 2);
	if (l == 0) l++;
	while (l <= r) {
		if (n % l == 0) {
			if (l * (l + s(l)) == n) return l;
		}
		l++;
	}
	return -1;
}

void main() {
	long n;
	readf("%d", &n);
	writeln(solve(n));
}

