	while (readf (" %s", &n) > 0)
	{
		readln;
		auto d = readln.splitter.map !(to !(long)).array;
		auto s = readln.strip;

		auto need = new long [n + 1];
		auto grassAhead = new long [n + 1];
		long cur = 0;
		need[n] = cur;
		grassAhead[n] = 0;
		foreach_reverse (i; 0..n)
		{
			grassAhead[i] = grassAhead[i + 1];
			switch (s[i])
			{
				case 'G': cur -= d[i];
				    grassAhead[i] += d[i]; break;
				case 'W': cur -= d[i]; break;
				case 'L': cur += d[i]; break;
				default: assert (false);
			}
			cur = max (cur, 0);
			need[i] = cur;
		}
		debug {writeln (need);}

		bool seenWater = false;
		long res = 0;
		long energy = 0;
		long walkDist = 0;
		long swimDist = 0;
		long grassFlown = 0;
		foreach (i; 0..n)
		{
			switch (s[i])
			{
				case 'G': energy += d[i];
				    res += d[i] * 5; break;
				case 'W': energy += d[i];
				    seenWater = true;
				    res += d[i] * 3; break;
				case 'L': energy -= d[i];
				    res += d[i] * 1; break;
				default: assert (false);
			}
			if (energy < 0)
			{
				res += (seenWater ? 3 : 5) * (-energy);
				energy = 0;
