import std.stdio;
import std.container;
import std.random;
import std.range;
import std.algorithm;
import std.typecons;
import std.conv;
import std.format;

int[] par;
long[] smallest;

int find_set(int v) {
	if (v == par[v]) return v;
	return par[v] = find_set(par[v]);
}

Mt19937 rng;

void unite(int a, int b) {
	a = find_set(a);
	b = find_set(b);
	if (rng.front % 2) swap(a, b);
	rng.popFront();
	par[b] = a;
	smallest[a] = min(smallest[a], smallest[b]);
}

void main() 
{
	par = iota(200000).array;

	int n, m;
	stdin.byLine.front.formattedRead!"%d %d"(n, m);

	auto S = redBlackTree!(Tuple!(long, int));
	auto offers = redBlackTree!(Tuple!(long, int, int));

	smallest = stdin.byLine.front.split(" ").map!`parse!long(a)`.array;

	smallest.writeln;

	foreach (i, e; smallest) {
		S.insert(tuple(e, i.to!int));
	}

	for (int i = 0; i < m; i++) {
		int a, b;
		long w;
		stdin.byLine.front.formattedRead!"%d %d %d"(a, b, w);

		a--; b--;
		offers.insert(tuple(w, a, b));
	}

	long totalCost = 0;
	while (true) {
		if (S.length == 1) {
			writeln(totalCost);
			return;
		}

		while (offers.length > 0 && find_set(offers.front[1]) == find_set(offers.front[2]))
			offers.removeFront();

		auto c1 = S.front; S.removeFront();
		auto c2 = S.front; S.removeFront();
		auto cost = c1[0] + c2[0];

		if (offers.length > 0 && offers.front[0] < cost) {
			S.insert([c1, c2]);
			totalCost += offers.front[0];
			int x = offers.front[1];
			int y = offers.front[2];

			int setx = find_set(x);
			int sety = find_set(y);

			S.removeKey(tuple(smallest[setx], setx));
			S.removeKey(tuple(smallest[sety], sety));
			unite(x, y);
			int setxy = find_set(x);
			S.insert(tuple(smallest[setxy], setxy));
		} else {
			totalCost += cost;
			int x = c1[1];
			int y = c2[1];
			unite(x, y);

			int setxy = find_set(x);
			S.insert(tuple(smallest[setxy], setxy));
		}
	}
}

