void main() {
    auto s = readln.split.map!(to!int);
    auto N = s[0];
    auto M = s[1];
    auto A = readln.split.map!(to!long).array;
    auto X = new Tuple!(int, long)[][](N);
    foreach (i; 0..M) {
        auto t = readln.split;
        auto u = t[0].to!int - 1;
        auto v = t[1].to!int - 1;
        auto w = t[2].to!long;
        X[u] ~= tuple(v, w);
        X[v] ~= tuple(u, w);
    }

    long ans = 0;
    int S = A.minIndex.to!int;
    auto pq = new BinaryHeap!(Array!(Tuple!(int, long)), "a[1] > b[1]")();
    auto used = new bool[](N);
    used[S] = true;

    foreach (i; 0..N) {
        if (i == S) continue;
        pq.insert(tuple(i, A[S] + A[i]));
    }

    foreach (t; X[S]) {
        pq.insert(tuple(t[0], t[1]));
    }

    while (!pq.empty) {
        auto t = pq.front;
        pq.removeFront;
        auto u = t[0];
        auto w = t[1];
        if (used[u]) continue;
        ans += w;
        used[u] = true;
        foreach (v; X[u]) {
            if (used[v[0]]) continue;
            pq.insert(tuple(v[0], v[1]));
        }
    }

    ans.writeln;
}

