import std.stdio;
import std.ascii;
import std.range;
import std.array;
import std.functional;
import std.algorithm;
import std.conv;
import std.container;
import std.math;
import std.numeric;
import std.string;
import std.c.string;
import std.random;
import std.regex;
import std.typecons;

string s; int K;

struct R {
    int from, to;
    int diff;
}

string modify(in string s) {
    int N = cast(int)(s.length);
    auto t = s[0 .. N / 2].dup;
    t.reverse;
    if (N & 1) {
        return s[0 .. N / 2] ~ s[N / 2] ~ t.idup;
    } else {
        return s[0 .. N / 2] ~ t.idup;
    }
}

void main() {
    s = readln.chomp;
    scanf("%d\n", &K);
    int N = cast(int)s.length;

    R[] rs;
    foreach (int i; 0 .. N) {
        foreach (int j; i + 1 .. N + 1) {
            int count(in string s) {
                int n = cast(int)s.length;
                int ret = 0;
                foreach (int i, c; s) {
                    if (c != s[n - 1 - i]) ret++;
                }
                return ret / 2;
            }
            rs ~= R(i, j, count(s[i .. j]));
        }
    }

    rs.sort!"a.from < b.from";
    const INF = 1<<28;
    auto dp = new int[][](K + 1, N + 1);
    auto prev = new int[][](K + 1, N + 1);
    foreach (k; 0 .. K + 1) dp[k][] = INF;
    for (int i = 0; i < N && rs[i].from == 0; i++) {
        dp[1][rs[i].to] = rs[i].diff;
        prev[1][rs[i].to] = rs[i].from;
    }
    foreach (k; 1 .. K) {
        foreach (n; 0 .. N) dp[k + 1][n] = min(dp[k + 1][n], dp[k][n]);
        foreach (r; rs) {
            if (dp[k + 1][r.to] > dp[k][r.from] + r.diff) {
                dp[k + 1][r.to] = dp[k][r.from] + r.diff;
                prev[k + 1][r.to] = r.from;
            }
        }
    }
    int ansCount = INF;
    int ansK = 0;
    foreach (int k; 0 .. K + 1) {
        if (ansCount > dp[k][N]) {
            ansCount = dp[k][N];
            ansK = k;
        }
    }
    writeln(ansCount);
    int n = N;
    int p = prev[ansK][N];
    string[] ans;
    int k = ansK;
    while (k > 0) {
        ans ~= s[p .. n];
        n = p;
        p = prev[--k][n];
    }
    writeln(ans.map!(modify).join("+"));
    //foreach (l; dp[1 .. $]) l.writeln;
}

