import std.stdio;
import std.math;
import std.numeric;
import std.container;
import std.typecons;
import std.conv;
import std.array;
import std.string;
import std.range;
import std.algorithm;
import core.bitop;
import core.stdc.stdio : scanf;

T read(T)() { return readln.chomp.to!T; }
T[] readarray(T)() { return readln.chomp.split(" ").map!(to!T).array; }
void chmin(T)(ref T a, in T b) { a = min(a, b); }
void chmax(T)(ref T a, in T b) { a = max(a, b); }

void main() {
    int T = read!int;
    foreach (t; 0 .. T) solve();
}

void solve() {
    long P, F; readf("%d %d\n", &P, &F);
    int Cs, Cw; readf("%d %d\n", &Cs, &Cw);
    long S, W; readf("%d %d\n", &S, &W);

    long ans = 0;
    for (int np = 0; np <= Cs; np++) {
        long r = P - np * S;
        if (r < 0) break;
        long mp = min(r / W, Cw);
        long Rs = Cs - np;
        long Rw = Cw - mp;
        if (S < W) {
            long nf, mf;
            if (F / S <= Rs) {
                nf = F / S;
                mf = 0;
            } else {
                nf = Rs;
                mf = min((F - nf * S) / W, Rw);
            }
            ans.chmax(np + mp + nf + mf);
        } else {
            long nf, mf;
            if (F / W <= Rw) {
                mf = F / W;
                nf = 0;
            } else {
                mf = Rw;
                nf = min((F - mf * W) / W, Rs);
            }
            ans.chmax(np + mp + nf + mf);
        }
    }
    writeln(ans);
}

