import std.math, std.numeric;
import std.range, std.range.interfaces;
import std.stdio, std.string;
import std.ascii, std.typecons;

void main()
{
    auto t = readln.chomp.to!int;
    
    auto rln = () => readln.chomp.split.map!(to!int).array;
    
    while (t--) {
        auto cap = rln();
        auto cnt = rln();
        auto w = rln();
        
        if (w[0] > w[1]) {
            swap(w[0], w[1]);
            swap(cnt[0], cnt[1]);
        }
        
        int fitItem(ref int sz, const int w, ref int cnt) {
            int fit = min(cnt, sz / w);
            sz -= fit * w;
            cnt -= fit;
            return fit;
        }
        
        int mxinfst = min(cnt[0], cap[0] / w[0]);
        int ans = 0;
        foreach (oneinfst; 0 .. mxinfst + 1) {
            auto sz = cap.dup;
            auto cnttmp = [cnt[0] - oneinfst, cnt[1]];
            
            int cur = fitItem(sz[0], w[0], oneinfst);
            cur += fitItem(sz[0], w[1], cnttmp[1]);
            
            cur += fitItem(sz[1], w[0], cnttmp[0]);
            cur += fitItem(sz[1], w[1], cnttmp[1]);
            
            ans = max(ans, cur);
        }
        
        ans.writeln;
    }
}

