import core.bitop, std.bitmanip;
import core.checkedint;
import std.algorithm, std.functional;
import std.array, std.container;
import std.bigint;
import std.conv;
import std.datetime.stopwatch;
import std.math, std.numeric;
import std.range, std.range.interfaces;
import std.stdio, std.string;
import std.typecons;

immutable int MD = 10 ^^ 9 + 7;

void main()
{
    int n, len;
    readf("%s %s", &n, &len);
    readln;

    int[][] arr;
    foreach (i; 0 .. n) {
        int x, y;
        readf("%s %s", &x, &y);
        readln;
        
        arr ~= [x, y];
    }
    
    debug { arr.writeln; }
    
    auto dp = new int[][][] (len+1, n, 2);
    foreach (i, e; arr) {
        dp[e[0]][i][0] = 1;
        if (e[0] != e[1]) { dp[e[1]][i][1] = 1; }
    }
    
    debug { dp.writeln; }
    
    foreach (clen; 2 .. len+1) {
        foreach (i, e; arr) {
            foreach (turn; 0 .. 2) {
                if (turn == 1 && e[0] == e[1]) { continue; }
                
                int elen = e[turn];
                if (elen >= clen) { continue; }
                
                foreach (j, p; arr) {
                    if (i == j) { continue; }
                    
                    foreach (pTurn; 0 .. 2) {
                        if (pTurn == 1 && p[0] == p[1]) { continue; }
                        
                        int pMatch = p[1 - pTurn];
                        if (elen != pMatch) { continue; }
                        
                        debug { if (clen == 3 && i == 1) { writeln(turn, ' ', j, ' ', pTurn, ' ', pMatch, ' ', dp[clen-elen][j][pTurn]); } }
                        dp[clen][i][turn] = (dp[clen][i][turn] + dp[clen-elen][j][pTurn]) % MD;
                    }
                }
            }
        }
    }
    
    debug { dp.each!writeln; }
    
    int ans = 0;
    foreach (ref e; dp[len]) {
        foreach (et; e) { ans = (ans + et) % MD; }
    }
    
    ans.writeln;
}

