bool read(T...)(T ptrs) if (ptrs.length > 0) {
    return readf(' ' ~ replicate("%s ", ptrs.length), ptrs) == ptrs.length;
}

T[ ] allocate(T)(size_t n) {
    return (cast(T*)malloc(n * T.sizeof))[0 .. n];
}

auto pairwise(R)(R range) if (isForwardRange!R) {
    return lockstep(range, dropOne(range));
}

struct Node {
    int len;
    Node*[char] next;
    Node* link;
    int[int] dp;

    Node* append(char c, Node* last) {
        auto cur = createNode(Node(last.len + 1));
        for (; last !is null && c !in last.next; last = last.link)
            last.next[c] = cur;
        if (last is null) {
            cur.link = &this;
            return cur;
        }
        auto q = last.next[c];
        if (q.len == last.len + 1) {
            cur.link = q;
            return cur;
        }
        auto clone = createNode(*q);
        clone.len = last.len + 1;
        cur.link = q.link = clone;
        for (; last !is null && last.next.get(c, null) == q; last = last.link)
            last.next[c] = clone;
        return cur;
    }

    int calc(int badTaken) {
        if (badTaken > k)
            return 0;
        if (auto p = badTaken in dp)
            return *p;
        int result = 1;
        foreach (c, node; next)
            result += node.calc(badTaken + (good[c - 'a'] == '0'));
        dp[badTaken] = result;
        return result;
    }
}

