import std.algorithm;
import std.container;
import std.exception;
import std.math;
import std.stdio;
import std.string;
import std.typecons;

immutable int MAX_N = 54;
immutable int MOD = 1_000_000_007;

long [MAX_N] [MAX_N] c;

void main ()
{
    foreach (i; 0..MAX_N)
    {
        c[i][0] = 1;
        foreach (j; 1..i + 1)
        {
            c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % MOD;
        }
    }

    int n, k;
    while (readf (" %s %s", &n, &k) > 0)
    {
        auto a = new int [n];
        k /= 50;
        int x = 0;
        int y = 0;
        foreach (i; 0..n)
        {
            readf (" %s", &a[i]);
            a[i] /= 50;
            if (a[i] == 1)
            {
                x++;
            }
            else if (a[i] == 2)
            {
                y++;
            }
            else
            {
                enforce (false);
            }
        }

        alias Tuple !(int, "b", int, "x", int, "y") state;
        alias Tuple !(int, "dist", int, "num") value;
        state [] q;
        q.reserve (2 * (x + 1) * (y + 1));
        auto f = new value [] [] [] (2, x + 1, y + 1);

        f[0][0][0] = value (0, 1);
        q ~= state (0, 0, 0);
        while (q.length > 0)
        {
            state cur = q[0];
            q = q[1..$];
            int cb = cur.b;
            int cx = cur.x;
            int cy = cur.y;
            int cd = f[cb][cx][cy].dist + 1;
            int cn = f[cb][cx][cy].num;
            debug {writefln ("%s %s %s", cb, cx, cy);}
            int nb = 1 - cb;
            foreach (dx; 0..x + 1)
            {
                foreach (dy; 0..y + 1)
                {
                    if (!dx && !dy)
                    {
                        continue;
                    }
                    if (dx + dy * 2 > k)
                    {
                        break;
                    }
                    int nx, ny;
                    long mult;
                    if (cb) // back
                    {
                        nx = cx - dx;
                        ny = cy - dy;
                        mult = (c[cx][dx] *
                                c[cy][dy]) % MOD;
                        if (nx < 0 || ny < 0)
                        {
                            continue;
                        }
                    }
                    else // forward
                    {
                        nx = cx + dx;
                        ny = cy + dy;
                        mult = (c[x - cx][dx] *
                                c[y - cy][dy]) % MOD;
                        if (nx > x || ny > y)
                        {
                            continue;
                        }
                    }
                    if (!f[nb][nx][ny].num)
                    {
                        f[nb][nx][ny].dist = cd;
                        q ~= state (nb, nx, ny);
                    }
                    if (f[nb][nx][ny].dist != cd)
                    {
                        continue;
                    }
                    f[nb][nx][ny].num =
                      (f[nb][nx][ny].num +
                       mult * cn) % MOD;
                }
            }
        }

        writefln ("%s", f[1][x][y].dist == int.max ?
                  -1 : f[1][x][y].dist);
        writefln ("%s", f[1][x][y].num);
    }
}

