                    if (f[nb][nx][ny].dist == int.max)
                    {
                        f[nb][nx][ny].dist = cd;
                        q ~= state (nb, nx, ny);
                    }
                    if (f[nb][nx][ny].dist != cd)
                    {
                        continue;
                    }
                    f[nb][nx][ny].num =
                      (f[nb][nx][ny].num +
                       mult * cn) % MOD;
                }
            }
        }

        writefln ("%s", f[1][x][y].dist == int.max ?
                  -1 : f[1][x][y].dist);
        writefln ("%s", f[1][x][y].num);
    }
}

