            ll take = min(freq[i]<<i, memory[k]<<k);
            ll taken = take/(1L<<i);
            freq[i] -= taken;
            ll left = (memory[k]<<k) - (taken << i);
            /* debug if(left)writeln(left, " ", memory[k]<<k, " ", memory[k], " ", k, " ", take); */
            memory[k] = 0;
