import std.stdio, std.string, std.algorithm;
import std.conv, std.array;
import std.container;
import std.typecons;

void check(T...)(T args) {
    args.map!(to!string).array.join(" ").writeln;
}

int f(ref int[] b, ref int[] p, int a, int m) {
    for (int i = 0; i < m; i++) {
        a -= [p[i] - b[m - 1 - i], 0].reduce!max;
        if (a < 0) {
            return -1;
        }
    }
    return a;
}

void main() {
    int n, m, a; readf("%d %d %d\n", &n, &m, &a);
    int[] b = new int[n];
    int[] p = new int[m];
    foreach (i; 0 .. n) {
        scanf("%d", &b[i]);
    }
    foreach (i; 0 .. m) {
        scanf("%d", &p[i]);
    }
    b.sort!("a > b");
    p.sort;
    int x = 0;
    int l, r;
    int s = 0;
    for (l = 0, r = [n, m].reduce!min + 1; l + 1 < r; ) {
        x = (l + r) / 2;
        s = f(b, p, a, x);
        if (s >= 0) {
            l = x;
        } else {
            r = x;
        }
    }
    [l, [0, p[0 .. l].reduce!"a + b" - a].reduce!max].check;
}

