import core.bitop, std.bitmanip;
import core.checkedint;
import std.algorithm, std.functional;
import std.array, std.container;
import std.bigint;
import std.conv;
import std.datetime.stopwatch;
import std.math, std.numeric;
import std.range, std.range.interfaces;
import std.stdio, std.string;
import std.typecons;

void main()
{
    int n, mx, reg;
    readf("%s %s %s", &n, &mx, &reg);
    readln;
    
    struct scroll { int id, pw, dmg; }
    
    scroll[] scs;
    foreach (i; 1 .. n+1) {
        int pw, dmg;
        readf("%s %s", &pw, &dmg);
        readln;
        
        scs ~= scroll(i, pw, dmg);
    }
    
    auto used = new bool[] (n+1);
    Tuple!(int, int)[] ans;
    int cur = mx;
    int sec = 0;
    int sm = 0;
    for (; sec <= 2100; ++sec) {
        cur = min(cur - sm + reg, mx);
        if (cur <= 0) { break; }
        
        foreach (i, e; scs) {
            if (used[i]) { continue; }
            
            if (e.pw * mx >= cur * 100) {
                used[i] = true;
                sm += e.dmg;
                ans ~= tuple(sec, e.id);
            }
        }
    }
    
    if (sec > 2100) {
        writeln("NO");
        return;
    }
    
    writeln("YES");
    writeln(sec, ' ', ans.length);
    ans.each!(e => writeln(e[0], ' ', e[1]));
}

