immutable int MOD   =  1_000_000_007;
immutable int HALF  = (MOD >> 1) + 1;
immutable int MAX_N =             54;

void main ()
{
	auto c = new long [] [] (MAX_N, MAX_N);

	foreach (n; 0..MAX_N)
	{
		c[n][0] = 1;
		foreach (k; 1..n + 1)
		{
			c[n][k] = (c[n - 1][k - 1] + c[n - 1][k]) % MOD;
		}
	}

	auto f = new long [] [] [] (MAX_N, MAX_N, 2);
	// 0 is occupied, 1 is free
	f[1][0][1] = 1;

	foreach (n; 2..MAX_N)
	{
		foreach (k; 0..n + 1)
		{
			foreach (b; 0..2)
			{
				// one child
				int pk = k - (b == 0);
				if (pk >= 0)
				{
					long mult = n - 1;
					f[n][k][b] = (mult *
					    f[n - 1][pk][!b]) % MOD;
				}
			}

			// two children
			for (int x = 1; x < n - 1; x++)
			{
				int y = n - 1 - x;
				assert (x > 0 && y > 0);
				long mult = c[n - 1][x];
				mult = (mult * x) % MOD;
				mult = (mult * y) % MOD;

				for (int xk = 0; xk <= k; xk++)
				{
					int yk = void;

					debug {if (n == 3 && k == 1)
					    writeln (x, ' ', y, ' ',
					             k, ' ', xk);}
					// occupied
					yk = k - xk - 1;
					if (yk >= 0)
					{
						f[n][k][0] = (f[n][k][0] +
						    (f[x][xk][1] *
						    f[y][yk][0]) % MOD *
						    mult) % MOD;
						if (x < y ||
						    (x <= y && xk <= yk))
						{
							long mult2 = mult;
							if (x == y
							    /* && xk == yk */)
							{
								mult2 =
								    (mult2 *
								    HALF) %
								    MOD;
							}
							f[n][k][0] =
							    (f[n][k][0] +
							    (f[x][xk][1] *
							    f[y][yk][1]) %
							    MOD *
							    mult2) % MOD;
						}
					}

					// free
					yk = k - xk;
					if (x < y || (x <= y && xk <= yk))
					{
						f[n][k][1] = (f[n][k][1] +
						    (f[x][xk][0] *
						    f[y][yk][0]) % MOD *
						    mult) % MOD;
					}
				}
			}
			debug {writefln ("f[%s][%s] = %s, %s",
			                 n, k, f[n][k][0], f[n][k][1]);}
		}
	}

	int n, k;
	while (readf (" %s %s", &n, &k) > 0)
	{
		writeln ((f[n][k][0] + f[n][k][1]) % MOD);
	}
}

