import std.stdio;

immutable int MOD   = 1_000_000_007;
immutable int HALF  = (MOD / 2) + 1;
immutable int MAX_N =            54;

struct modint
{
	long value;

	alias value this;

	this (long nvalue)
	{
		value = nvalue;
	}

	modint opBinary (string op) (long other)
	{
		return mixin ("modint ((value " ~ op ~ " other) % MOD)");
	}

	modint opOpAssign (string op, T) (T other)
	{
		return mixin ("this = this " ~ op ~ " other");
	}
}

void main ()
{
	auto c = new modint [] [] (MAX_N, MAX_N);

	foreach (n; 0..MAX_N)
	{
		c[n][0] = 1;
		foreach (k; 1..n + 1)
		{
			c[n][k] = c[n - 1][k - 1] + c[n - 1][k];
		}
	}

	auto f = new modint [] [] [] (MAX_N, MAX_N, 2);
	f[1][0][1] = 1;

	foreach (n; 2..MAX_N)
	{
		foreach (k; 0..n + 1)
		{
			foreach (b; 0..2)
			{
				int pk = k - (b == 0);
				if (pk >= 0)
				{
					f[n][k][b] = f[n - 1][pk][!b] *
					             (n - 1);
				}
			}

			foreach (x; 1..n - 1)
			{
				int y = n - 1 - x;
				assert (x > 0 && y > 0);
				modint mult = c[n - 1][x] * x * y;

				foreach (xk; 0..k + 1)
				{
					int yk = void;

					yk = k - xk - 1;
					if (yk >= 0)
					{
						f[n][k][0] += f[x][xk][1] *
						    f[y][yk][0] * mult;
						if (x < y ||
						    (x <= y && xk <= yk))
						{
							modint mult2 = mult;
							if (x == y && xk == yk)
							{
								mult2 *= HALF;
							}
							f[n][k][0] += mult2 *
							    f[x][xk][1] *
							    f[y][yk][1];
						}
					}

					yk = k - xk;
					if (x < y || (x <= y && xk <= yk))
					{
						modint mult2 = mult;
						if (x == y && xk == yk)
						{
							mult2 *= HALF;
						}
						f[n][k][1] += f[x][xk][0] *
						    f[y][yk][0] * mult2;
					}
				}
			}
		}
	}

	int n, k;
	while (readf (" %s %s", &n, &k) > 0)
	{
		writeln (f[n][k][0] + f[n][k][1]);
	}
