alias Point = Tuple !(int, q{x}, int, q{y});
long sp (Point a, Point b, Point c) {return (b.x - a.x) * 1L * (c.x - a.x) + (b.y - a.y) * 1L * (c.y - a.y);}
long vp (Point a, Point b, Point c) {return (b.x - a.x) * 1L * (c.y - a.y) - (b.y - a.y) * 1L * (c.x - a.x);}
void main () {
	int k, n, res;
	readf (" %s %s", &k, &n);
	auto a = new Point [k], b = new Point [n], s = new int [] [] [] (k, n);
	foreach (ref p; a) readf (" %s %s", &p.x, &p.y);
	foreach (ref q; b) readf (" %s %s", &q.x, &q.y);
	foreach (p; 0..k) foreach (q; 0..n) s[p][q] = n.iota.filter !(r => vp (b[r], a[p], b[q]) == 0 && sp (b[r], a[p], b[q]) < 0).take (k).array;
	bool go (int mask, int depth, int [] t) {
		if (t.empty) return true;
		if (depth < t.length) return false;
		foreach (p; 0..k) if (mask & (1 << p)) foreach (i, q; t) {
			auto next = t[0..i] ~ t[i + 1..$] ~ s[p][q];
			if (go (mask ^ (1 << p), depth - 1, next.sort ().uniq.array)) return true;
		}
		return false;
	}
	foreach (q; 0..n) res += k.iota.any !(p => go (-1, k, [p]));
	writeln (res);
}

