long calc(int u, int p, int ip, int a, int b) {
  assert(b > 0);
  auto ret = &cache[u][p][a][b];
  if (*ret == -1) {
    debug {
      writeln("calc ", u, " ", p, " ", ip, " ", a, " ", b);
    }
    if (G[u].length == 1) {
      // leaf
      if (a == 0) {
        *ret = 0;
      } else {
        *ret = W[G[u][0]] + calc(p, u, ip, 0, a);
      }
    } else {
      assert(b > 0);
      // c_j for j-th child
      // maximize min { W[i] + calc(u, v_j, i_j, a + b - c_j, c_j) | c_j > 0 }
      auto crt = new long[b + 1];
      crt[] = -INF;
      crt[0] = INF;
      foreach (i; G[u]) {
