import std.algorithm;
import std.array;
import std.container;
import std.conv;
import std.math;
import std.range;
import std.stdio;
import std.typecons, std.traits;

alias Query = Tuple!(long, "index", long, "l", long, "r", long, "ans"); 
void main() {
  long[long] cnt;
  long sum = 0;
  int n, t;
  readf(" %d %d\n", &n, &t);
  auto a = readln.split.map!(to!long);
  auto queries = new Query[](t);
  foreach(i; 0..t) {
    readf(" %d %d", &queries[i].l, &queries[i].r);
    queries[i].index = i;
    queries[i].l--;
  }
  long k = n.intsqrt;

  queries.sort!(delegate(a,b) {
      if (a.l/k < b.l/k) return true; 
      return a.r < b.r;
      });

  int l,r;
  void add(long elem) {
    debug { writeln("add: ", elem); }
    if (elem in cnt) {
      sum += elem*((cnt[elem]+1)^^2 - cnt[elem]^^2);
    } else {
      sum += elem;
    }
    cnt[elem]++;
  }
  void del(long elem) {
    debug { writeln("del: ", elem); }
    assert(cnt[elem] > 0);
    cnt[elem]--;
    sum -= elem*((cnt[elem]+1)^^2 - cnt[elem]^^2);
  }

  foreach(ref q; queries) {
    debug { writeln("query: ", a[q.l..q.r]); }
    while (r < q.r) {
      add(a[r]);
      r++;
    }
    while (r > q.r) {
      del(a[r-1]);
      r--;
    }
    while (l < q.l) {
      del(a[l]);
      l++;
    }
    while (l > q.l) {
      add(a[l]);
      l--;
    }
    q.ans = sum;
  }
  queries.sort!((a,b) => a.index < b.index);
  queries.each!(a => writeln(a.ans));
}

T intsqrt(T)(T i) {
   T bitMask = 1;
   T result = 0;

   bitMask <<= T.sizeof * 4 - 1;

   while (bitMask) {
       result |= bitMask;
       if ((result * result) > i) {
           result &= ~bitMask;
       }
       bitMask >>= 1;
   }

   return result;
}

