void main() {
    int N, T; scanf("%d %d\n", &N, &T);
    auto A = new int[N]; {
        foreach (ref a; A) {
            scanf("%d", &a);
        }
    }
    auto L = new int[T];
    auto R = new int[T]; {
        foreach (i; 0 .. T) {
            scanf("%d %d", &L[i], &R[i]);
            L[i]--;
        }
    }

    int p = cast(int)(sqrt(cast(real)N));
    auto I = iota(T).array.sort!((i, j) {
        int qi = L[i] / p, qj = L[j] / p;
        if (qi == qj) {
            return R[i] < R[j];
        } else {
            return qi < qj;
        }
    }).array;

    int x = 0, y = 0;
    long[] K = new long[A.reduce!max + 1];
    //long[long] K;
    long S = 0;
    auto ans = new long[T];
    foreach (i; I) {
        int l = L[i], r = R[i];
        int dy = (r - y > 0 ? +1 : -1);
        while (y != r) {
            int s = A[ dy > 0 ? y : y - 1 ];
            long pk = K[s];
            //long pk = K.get(s, 0);
            long nk = pk + (dy > 0 ? +1 : -1);
            S += s * (nk * nk - pk * pk);
            y += dy;
            K[s] = nk;
        }
        int dx = (l - x > 0 ? +1 : -1);
        while (x != l) {
            int s = A[ dx > 0 ? x : x - 1 ];
            long pk = K[s];
            //long pk = K.get(s, 0);
            long nk = pk + (dx > 0 ? -1 : +1);
            S += s * (nk * nk - pk * pk);
            x += dx;
            K[s] = nk;
        }
        ans[i] = S;
    }
    foreach (a; ans) writeln(a);
}

