import std.stdio, std.array, std.string, std.conv, std.algorithm;
import std.typecons, std.range, std.random, std.math, std.container;
import std.numeric, std.bigint, core.bitop, std.bitmanip;

void main() {
    immutable int INF = 1 << 29;

    int[] unfold(int n) {
        return [n / 1000 % 10, n / 100 % 10, n / 10 % 10, n % 10];
    }

    int fold(int[] a) {
        int[] b = a.dup;
        b.sort!"a > b";
        return b[0] + b[1] * 10 + b[2] * 100 + b[3] * 1000;
    }

    auto N = readln.chomp.to!int;
    auto src = new int[](N);
    auto dst = new int[](N);
    foreach (i; 0..N) {
        auto s = readln.split.map!(to!int);
        src[i] = s[0];
        dst[i] = s[1];
    }

    auto dp = new int[][](N+1, 10000);
    foreach (i; 0..N+1) dp[i].fill(INF);
    dp[0][0] = 0;

    foreach (i; 0..N) {
        int cur = i == 0 ? 1 : src[i-1];
        int tar = src[i];
        foreach (a; 0..10) {
            foreach (b; a..10) {
                foreach (c; b..10) {
                    foreach (d; c..10) {
                        foreach (k; 1..10) {
                            int[] v = [a, b, c, d];
                            int fv = fold(v);
                            if (dp[i][fv] >= INF) continue;
                            int hi = max(cur, tar, k);
                            int lo = min(cur, tar, k);
                            int cost = 1;
                            foreach (j; 0..4) if (lo <= v[j] && v[j] <= hi) v[j] = 0, cost += 1;
                            int z = -1;
                            foreach (j; 0..4) if (v[j] == 0) z = j;
                            if (z == -1) continue;
                            v[z] = dst[i];
                            int dist = abs(cur - k) + abs(k - tar);
                            dp[i+1][fv] = min(dp[i+1][fv], dp[i][d + c*10 + b*100 + a*1000] + dist + cost);
                        }
                    }
                }
            }
        }
    }


    int ans = INF;

    foreach (a; 0..10) {
        foreach (b; a..10) {
            foreach (c; b..10) {
                foreach (d; c..10) {
                    int[] v = [a, b, c, d];
                    if (v.all!"a == 0") {
                        ans = min(ans, dp[N][0]);
                        continue;
                    }
                    int hi = (src.back, v.filter!"a != 0".reduce!max);
                    int lo = (src.back, v.filter!"a != 0".reduce!min);
                    int cost = (a != 0) + (b != 0) + (c != 0) + (d != 0);
                    int dist = min(abs(src.back - hi) + abs(hi - lo), abs(src.back - lo) + abs(lo - hi));
                    ans = min(ans, dp[N][fold([a, b, c, d])] + dist + cost);
                }
            }
        }
    }

    ans.writeln;
}

