		auto dst = new int [n];
		foreach (i; 0..n)
		{
			readf (" %s %s", &src[i], &dst[i]);
		}
		src[] -= 1;
		dst[] -= 1;

		alias State = int [4];
		State [] states;
		int [State] stateNum;
		foreach (a; NA..totalLevels)
		{
			foreach (b; a..totalLevels)
			{
				foreach (c; b..totalLevels)
				{
					foreach (d; c..totalLevels)
					{
						State state = [a, b, c, d];
						do
						{
							stateNum[state] =
							    states.length
							    .to !(int);
						}
						while (nextPermutation
						    (state[]));
						states ~= state;
					}
				}
			}
		}
		immutable int totalStates = 715;
		assert (totalStates == states.length);

		auto f = new int [totalLevels] [] [] (n + 1, totalStates);
		foreach (i; 0..n + 1)
		{
			foreach (stateIndex; 0..totalStates)
			{
				f[i][stateIndex][] = infinity;
			}
