					{
						if (v == NA)
						{
							continue;
						}
						auto nextValue = cur + abs
						    (level - v) + 1;
						auto nextState = curState;
						nextState[j] = NA;
						auto nextIndex =
						    stateNum[nextState];
						f[i][nextIndex][v] =
						    min (f[i][nextIndex][v],
						    nextValue);
					}

					if (i < n && curState[0] == NA)
					{
						auto u = src[i];
						auto nextValue = cur + abs
						    (level - u) + 1;
						auto nextState = curState;
						nextState[0] = dst[i];
						auto nextIndex =
