void main()
{
    int le, r, x, y;
    readf("%s %s %s %s", &le, &r, &x, &y);
    readln;
    
    int g = y / x;
    
    int[] dvs;
    int k = 2;
    while (g > 1 && k <= g / k) {
        while (g % k == 0) {
            dvs ~= k;
            g /= k;
        }
        k += 1;
    }
    if (g > 1) dvs ~= g;
    
    int mx = 1 << dvs.length;
    bool[int] chckd;
    int ans = 0;
    for (int i = 0; i < mx; ++i) {
        int a = x, b = x;
        for (int j = 0; j < dvs.length; ++j) {
            if (i & (1 << j)) {
                a *= dvs[j];
            } else {
                b *= dvs[j];
            }
        }
        
        if (chckd.get(a, false)) continue;
        if (a < le || a > r) continue;
        if (b < le || b > r) continue;
        if (gcd(a, b) != x) continue;
        
        ++ans;
        chckd[a] = true;
        debug { a.writeln; }
    }
    
