    my $ones = 0;

    my ($xx, $yy);

    for ($yy = 1; $yy <= $size-2; $yy++) {
        for ($xx = 1; $xx <= $size-2; $xx++) {
            $ones = 0;

            $ones++ if ($$matrix{$xx, $yy} eq 1);
            $ones++ if ($$matrix{$xx + 1, $yy} eq 1 and $ones eq 1);
