#!/usr/bin/perl
use strict;
use warnings;
use List::Util qw(min);

sub find {
    my ($x, $parent) = @_;
    if ($parent->[$x] != $x) {
        $parent->[$x] = find($parent->[$x], $parent);
    }
    return $parent->[$x];
}

sub union {
    my ($x, $y, $parent, $rank) = @_;
    my $px = find($x, $parent);
    my $py = find($y, $parent);
    if ($px != $py) {
        if ($rank->[$px] > $rank->[$py]) {
            $parent->[$py] = $px;
        } else {
            $parent->[$px] = $py;
            if ($rank->[$px] == $rank->[$py]) {
                $rank->[$py]++;
            }
        }
    }
}

my ($n, $m) = split / /, <>;
my @a = split / /, <>;
my @parent = (0..$n);
my @rank = (0) x ($n+1);
my @edges;
my $min_a = min @a;
my $min_i = 0;
for my $i (0..$#a) {
    if ($a[$i] == $min_a) {
        $min_i = $i;
        last;
    }
}
for my $i (0..$#a) {
    if ($i != $min_i) {
        push @edges, [$min_i+1, $i+1, $min_a + $a[$i]];
    }
}
for my $i (0..$m-1) {
    my ($x, $y, $w) = split / /, <>;
    push @edges, [$x, $y, $w];
}
@edges = sort {$a->[2] <=> $b->[2]} @edges;
my $res = 0;
for my $edge (@edges) {
    my ($x, $y, $w) = @$edge;
    if (find($x, \@parent) != find($y, \@parent)) {
        union($x, $y, \@parent, \@rank);
        $res += $w;
    }
}
print "$res\n";

