use strict;
use warnings;

# Read input
my $n = <STDIN>;
chomp $n;

my @poles;
for (my $i = 0; $i < $n; $i++) {
    my $line = <STDIN>;
    chomp $line;
    my ($x, $y) = split ' ', $line;
    push @poles, { x => $x, y => $y };
}

# Count intersecting pairs
my $count = 0;
for (my $i = 0; $i < $n; $i++) {
    for (my $j = $i + 1; $j < $n; $j++) {
        for (my $k = $j + 1; $k < $n; $k++) {
            my $x1 = $poles[$i]->{x};
            my $y1 = $poles[$i]->{y};
            my $x2 = $poles[$j]->{x};
            my $y2 = $poles[$j]->{y};
            my $x3 = $poles[$k]->{x};
            my $y3 = $poles[$k]->{y};

            if ((($x2 - $x1) * ($y3 - $y1)) == (($x3 - $x1) * ($y2 - $y1))) {
                $count++;
            }
        }
    }
}

# Print the result
print $count;

