#!/usr/bin/perl

use strict;
use warnings;

sub gcd {
    my ($a, $b) = @_;
    return $b == 0 ? $a : gcd($b, $a % $b);
}

my $n = <>;
chomp $n;
my @points;
my %lines;

for (1..$n) {
    my $line = <>;
    chomp $line;
    my ($x, $y) = split / /, $line;
    push @points, [$x, $y];
}

for my $i (0..$#points) {
    for my $j ($i+1..$#points) {
        my $dx = $points[$i][0] - $points[$j][0];
        my $dy = $points[$i][1] - $points[$j][1];
        my $g = gcd($dx, $dy);
        $dx /= $g; $dy /= $g;
        if ($dx < 0 || $dx == 0 && $dy < 0) {
            $dx = -$dx;
            $dy = -$dy;
        }
        my $c = $dx * $points[$i][1] - $dy * $points[$i][0];
        $lines{"$dx $dy"}{$c}++;
    }
}

my $total = 0;
my $pairs = 0;

for my $slope (keys %lines) {
    my $lines_on_slope = scalar keys %{$lines{$slope}};
    $total += $lines_on_slope;
    $pairs += $lines_on_slope * ($lines_on_slope - 1) / 2;
}

print $total * ($total - 1) / 2 - $pairs;

