use strict;
use warnings;

sub count_threats {
    my ($n, $m, @queens) = @_;

    my @threats = (0) x 9;

    for (my $i = 0; $i < $m; $i++) {
        my ($row, $col) = split(' ', $queens[$i]);

        # Count threats in horizontal and vertical directions
        for (my $j = 1; $j <= $n; $j++) {
            if ($j != $row) {
                $threats[1]++ if ($queens[$i] =~ /^$j $col$/);
            }
            if ($j != $col) {
                $threats[1]++ if ($queens[$i] =~ /^$row $j$/);
            }
        }

        # Count threats in diagonal directions
        for (my $j = 1; $j <= $n; $j++) {
            if ($j != $row && $j != $col) {
                $threats[1]++ if ($queens[$i] =~ /^$j $j$/);
                $threats[1]++ if ($queens[$i] =~ /^$j @{[ $col - $row + $j ]}$/);
                $threats[1]++ if ($queens[$i] =~ /^$j @{[ $col + $row - $j ]}$/);
            }
        }
    }

    foreach my $threat (@threats) {
        print "$threat ";
    }
}

