use strict;
use warnings;

sub check_queen {
    my ($x, $y, $dx, $dy, $n, $board) = @_;
    $x += $dx;
    $y += $dy;
    while ($x >= 0 && $y >= 0 && $x < $n && $y < $n) {
        if ($board->[$x][$y]) {
            return 1;
        }
        $x += $dx;
        $y += $dy;
    }
    return 0;
}

sub count_threats {
    my ($x, $y, $n, $board) = @_;
    my $threats = 0;
    for my $dx (-1..1) {
        for my $dy (-1..1) {
            if ($dx != 0 || $dy != 0) {
                $threats += check_queen($x, $y, $dx, $dy, $n, $board);
            }
        }
    }
    return $threats;
}

my $input = <>;
chomp($input);
my ($n, $m) = split(' ', $input);
my @board = map { [(0) x $n] } (1..$n);
my @threats = (0) x 9;
for my $i (1..$m) {
    my $input = <>;
    chomp($input);
    my ($x, $y) = split(' ', $input);
    $x--;
    $y--;
    $board[$x][$y] = 1;
}
for my $x (0..$n-1) {
    for my $y (0..$n-1) {
        if ($board[$x][$y]) {
            my $threats = count_threats($x, $y, $n, \@board);
            $threats[$threats]++;
        }
    }
}
print join(' ', @threats), "\n";

