use strict;
use warnings;

sub count_triangles {
    my ($n, $m, $red_points, $blue_points) = @_;

    my $count = 0;

    for (my $i = 0; $i < $n - 2; $i++) {
        for (my $j = $i + 1; $j < $n - 1; $j++) {
            for (my $k = $j + 1; $k < $n; $k++) {
                my ($x1, $y1) = @{$red_points->[$i]};
                my ($x2, $y2) = @{$red_points->[$j]};
                my ($x3, $y3) = @{$red_points->[$k]};

                my $is_triangle = 1;

                for (my $l = 0; $l < $m; $l++) {
                    my ($bx, $by) = @{$blue_points->[$l]};

                    my $cross_product = ($x2 - $x1) * ($by - $y1) - ($y2 - $y1) * ($bx - $x1);

                    if ($cross_product > 0 && ($x3 - $x1) * ($by - $y1) - ($y3 - $y1) * ($bx - $x1) > 0 && ($x1 - $x2) * ($by - $y2) - ($y1 - $y2) * ($bx - $x2) > 0) {
                        $is_triangle = 0;
                        last;
                    }
                }

                $count += $is_triangle;
            }
        }
    }

    return $count;
}

my $input = <STDIN>;
chomp $input;
my ($n, $m) = split ' ', $input;

my @red_points;
for (my $i = 0; $i < $n; $i++) {
    my $point = <STDIN>;
    chomp $point;
    my ($x, $y) = split ' ', $point;
    push @red_points, [$x, $y];
