# Function to check if a point is inside a triangle
sub is_inside_triangle {
    my ($p, $p1, $p2, $p3) = @_;
    my $d1 = ($p1->[0] - $p->[0]) * ($p2->[1] - $p1->[1]) - ($p2->[0] - $p1->[0]) * ($p1->[1] - $p->[1]);
    my $d2 = ($p2->[0] - $p->[0]) * ($p3->[1] - $p2->[1]) - ($p3->[0] - $p2->[0]) * ($p2->[1] - $p->[1]);
    my $d3 = ($p3->[0] - $p->[0]) * ($p1->[1] - $p3->[1]) - ($p1->[0] - $p3->[0]) * ($p3->[1] - $p->[1]);
    return ($d1 >= 0 && $d2 >= 0 && $d3 >= 0) || ($d1 <= 0 && $d2 <= 0 && $d3 <= 0);
}

# Count the number of distinct triangles
my $count = 0;
for my $i (0..$N-1) {
    for my $j ($i+1..$N-1) {
        for my $k ($j+1..$N-1) {
            my $triangle = [$red_points[$i], $red_points[$j], $red_points[$k]];
            my $is_valid = 1;
            for my $blue_point (@blue_points) {
                if (is_inside_triangle($blue_point, @$triangle)) {
                    $is_valid = 0;
                    last;
                }
            }
            $count++ if $is_valid;
        }
    }
}

# Print the result
print $count;

use strict;
use warnings;

my $MOD = 1000000007;

sub count_coinciding_words {
    my ($word) = @_;
    my $length = length($word);
    my $count = 0;

    # Calculate the number of words that coincide with the given word
    # by considering each possible position for the operation
    for (my $p = 0; $p < $length - 1; $p++) {
        my $letter_p = substr($word, $p, 1);
        my $letter_p_next = substr($word, $p + 1, 1);

        # Calculate the number of words that can be formed by replacing
        # letter p with the letter that follows it and letter p+1 with the
        # letter that precedes it
        my $count_follows = ord('z') - ord($letter_p) + ord($letter_p_next) - ord('a') + 1;

        # Calculate the number of words that can be formed by replacing
        # letter p with the letter that precedes it and letter p+1 with the
        # letter that follows it
        my $count_precedes = ord($letter_p) - ord('a') + ord('z') - ord($letter_p_next) + 1;

        # Add the counts modulo $MOD
        $count = ($count + $count_follows + $count_precedes) % $MOD;
    }

    return $count;
}

# Read the number of tests
my $t = <STDIN>;
chomp($t);

# Process each test case
for (my $i = 0; $i < $t; $i++) {
    # Read the word
    my $word = <STDIN>;
    chomp($word);

    # Calculate the number of coinciding words
    my $coinciding_words = count_coinciding_words($word);

    # Print the result modulo $MOD
    print($coinciding_words % $MOD . "\n");
}

#!/usr/bin/perl

use strict;
use warnings;
use List::Util qw[max];

sub trolley_time {
    my ($n, $a, $d, @trolley_info) = @_;
    my @arrival_times;
    my $prev_time = 0;
    for my $i (0 .. $n-1) {
        my ($t, $v) = @{$trolley_info[$i]};
        my $time_to_reach_v = $v / $a;
        my $dist_to_reach_v = 0.5 * $a * $time_to_reach_v**2;
        my $total_time;
        if ($dist_to_reach_v <= $d) {
            my $remaining_dist = $d - $dist_to_reach_v;
            my $remaining_time = $remaining_dist / $v;
            $total_time = $t + $time_to_reach_v + $remaining_time;
        } else {
            $total_time = $t + sqrt(2*$d/$a);
        }
        $prev_time = max($prev_time, $total_time);
        push @arrival_times, $prev_time;
    }
    return @arrival_times;
}

my $input_line = <STDIN>;
chomp $input_line;
my ($n, $a, $d) = split ' ', $input_line;
my @trolley_info;
for my $i (0 .. $n-1) {
    my $trolley_line = <STDIN>;
    chomp $trolley_line;
    push @trolley_info, [split ' ', $trolley_line];
}
my @arrival_times = trolley_time($n, $a, $d, @trolley_info);
for my $time (@arrival_times) {
    printf("%.10f\n", $time);
}

