sub fibonacci_strings {
    my ($k, $m, @queries) = @_;
    my @fibonacci = ('a', 'b');
    for (my $i = 2; $i < $k; $i++) {
        $fibonacci[$i] = $fibonacci[$i-1] . $fibonacci[$i-2];
    }
    my @results;
    foreach my $query (@queries) {
        my $count = 0;
        foreach my $fib_str (@fibonacci) {
            while ($fib_str =~ /$query/g) {
                $count++;
            }
        }
        push @results, $count;
    }
    return \@results;
}

