use strict;
use warnings;

sub fibonacci_strings {
    my ($k, $m, @queries) = @_;
    my @fibonacci = ('a', 'b');

    for (my $i = 2; $i < $k; $i++) {
        $fibonacci[$i] = $fibonacci[$i-1] . $fibonacci[$i-2];
    }

    my @results;
    foreach my $query (@queries) {
        my $count = 0;
        my $pos = 0;
        while (($pos = index($fibonacci[$k-1], $query, $pos)) != -1) {
            $count++;
            $pos++;
        }
        push @results, $count;
    }

    return @results;
}

