use warnings;

my %hash;

sub gcd {
  my $a = shift;
  my $b = shift;
  while ($b > 0) {
    $b ^= $a ^= $b ^= $a %= $b;
  }
  return $a;
}

my $n = <>;
for(1..$n) {
  my $line = <>;
  my @arr = split(/ /, $line);
  my $k = $arr[0];
  my $b = $arr[1];
  next if (0 == $k);
  my $g = gcd($k, $b);
  $k /= $g;
  $b /= $g;
  if ($k < 0) {
    $k = -$k;
    $b = -$b;
  }
  $hash{($k, $b)} = 1;
}
print "".keys( %hash )."\n";

