sub get_sum {
    $data = shift;
    my $sum = 0;
    for my $key (keys(%{$data})) {
        if ($data->{$key}) {
            $sum += $key * $data->{$key};
        }
    }

    return $sum;
}

sub func {
    my ($data, $rest) = @_;
    if ($rest == 1) {
        for my $i (1, 4, 7) {
