    result := -1;
    exit;
  end;
  if a = 0 then begin
    result := 0;
    exit;
  end;
  result := 1;
end;

function getline(var a, b : tp) : tl;
begin
  result.a := a.y - b.y;
  result.b := b.x - a.x;
  result.c := a.x * b.y - b.x * a.y;
end;

function dist(var l : tl; var p : tp) : int64;
begin
  result := l.a * p.x + l.b * p.y + l.c;
end;

function more(var a, b : tp) : boolean;
begin
  result := a.x > b.x;
end;

