procedure swap(var x, y: integer);
var
 z: integer;
begin
 z := x;
 x := y;
 y := z;
end;

function sqrr(a, b: integer): int64;
var
 dega: int64;
begin
 dega := a;
 result := 1;
 while b > 0 do
 begin
  if odd(b) then result := result * dega mod base;
  dega := dega * dega mod base;
  b := b div 2;
 end;
end;

var
 n, m, x, y: integer;
 i: integer;
 a, b: TArray;
 vsp, ans: int64;

procedure QSort(var a: TArray; l, r: integer);
var
 i, j, x: integer;
begin
 if l >= r then exit;
 i := l;
 j := r;
 x := a[l + random(r - l + 1)];
 repeat
  while a[i] < x do inc(i);
  while a[j] > x do dec(j);
  if i <= j then
  begin
   swap(a[i], a[j]);
   inc(i);
   dec(j);
  end;
 until i > j;
 QSort(a, l, j);
 QSort(a, i, r);
end;

