    read(n, l, r);
    if n < 3 then
    begin
        if n = 1 then write(r - l + 1)
        else write((r - l + 1)*(r - l));
        halt(0);
    end;
    m := sqrtn(n - 1, r);
    k := 0;
    for y := 1 to m do
    for x := y + 1 to m do
    if nod(x, y) = 1 then
    if (r div st(x, n - 1)) - ((l - 1) div st(y, n - 1)) >= 0 then
    k := k + (r div st(x, n - 1)) - ((l - 1) div st(y, n - 1));
    write(k*2);
end.

