procedure scanf;
var
	c : char;
begin
	readln(n, t);
	for i := 1 to n do begin
	for j := 1 to n do begin
		read(c);
		a[i][j] := ord(c)-ord('0');
		if (c = 'Y') then a[i][j] := -1 else
		if (c = 'Z') then begin
			a[i][j] := -1; 
			qx[1] := i;
			qy[1] := j;
		end;
	end;
		readln;
	end;
  readln;
	for i := 1 to n do begin
	for j := 1 to n do begin
		read(c);
		b[i][j] := ord(c)-ord('0');
		if (c in['Y','Z']) then b[i][j] := -1;
	end;
		readln;
	end;
end;
procedure bfs;
begin
	was[qx[1]][qy[1]] := true;
  for i := 1 to n do
  for j := 1 to n do
    d[i][j] := inf;
  d[qx[1]][qy[1]] := 0;
	i := 1; j := 1;
	while (i <= j) do begin
		for k := 1 to 4 do begin
			x := qx[i] + ux[k];
			y := qy[i] + uy[k];
			if (not was[x][y]) and (a[x][y] <> -1) and (1 <= x) and (x <= n) and (1 <= y) and (y <= n) then begin
				inc(j);
				qx[j] := x;
				qy[j] := y;
				was[x][y] := true;
				d[x][y] := d[qx[i]][qy[i]] + 1;
			end;
		end;
		inc(i);
	end;
end;
procedure precalc;
begin
	for i := 1 to n do
	for j := 1 to n do
    if (a[i][j] <> -1) then
  		can[0][i][j][i][j] := true;
	for tt := 1 to t do
	for i := 1 to n do
	for j := 1 to n do begin
		if (a[i][j] = -1) then continue;
		for ii := 1 to n do
		for jj := 1 to n do begin
    if (tt > d[ii][jj]) or (a[ii][jj] = -1) then continue;
		for k := 1 to 4 do begin
			x := ii + ux[k];
			y := jj + uy[k];
			if (tt-1 < d[x][y]) and (1 <= x) and (x <= n) and (1 <= y) and (y <= n) and (can[tt-1][i][j][x][y]) then begin
				can[tt][i][j][ii][jj] := true;
				break;
			end;
		end;
    end;
	end;
end;
procedure add(x, y, z : int);
begin
	inc(len);
	v[len] := y;
	next[len] := s[x];
	w[len] := z;
	s[x] := len;
end;
procedure findpath(x, y : int);
var
  rev : int;
begin
	while (x <> 0) do begin
		mn := min(mn, w[x]-f[x]);
		x := p[x];
	end;
	while (y <> 0) do begin
		if (y and 1 = 1) then rev := y + 1
		else rev := y - 1;
		f[y] := f[y] + mn;
		f[rev] := f[rev] - mn;
		y := p[y];
	end;
end;
procedure bfsflow;
var
  pos : int;
begin
	i := 1; j := 1;
	fillchar(used, sizeof(used), false);
	q[1] := 0; used[0] := true;
	while (i <= j) do begin
		pos := s[q[i]];
		while (pos <> 0) do begin
			if (not used[v[pos]]) and (w[pos]-f[pos] > 0) then begin
				inc(j);
				q[j] := v[pos];
				used[q[j]] := true;
				u[j] := pos;
				p[pos] := u[i];
				if (q[j] = 2*n*n+1) then begin
					findpath(pos, pos);
					exit;
				end;
			end;
			pos := next[pos];
		end;
		inc(i);
	end;
end;
procedure flow;
begin
	for i := 1 to n do
	for j := 1 to n do begin
    if (a[i][j] > 0) then begin
	  	add(0, (i-1)*n+j, a[i][j]);
  		add((i-1)*n+j, 0, 0);
    end;
    if (b[i][j] > 0) then begin
		  add(n*n+(i-1)*n+j, 2*n*n+1, b[i][j]);
	  	add(2*n*n+1, n*n+i*(n-1)+j, 0);
  	end;
  end;
	for i := 1 to n do
	for j := 1 to n do
	for ii := 1 to n do
	for jj := 1 to n do
	for tt := 0 to t do
		if (can[tt][i][j][ii][jj]) and (b[ii][jj] > 0) and (a[i][j] > 0) then begin
			add((i-1)*n+j, n*n+(ii-1)*n+jj, inf);
			add(n*n+(ii-1)*n+jj, (i-1)*n+j, 0);
      break;
		end;
	res := 0;
	while (true) do begin
		mn := inf;
		bfsflow;
		if (mn = inf) then begin
			write(res);
			halt;
		end;
		res := res + mn;
	end;
end;
begin
//	reset(input, 'a.in'); rewrite(output, 'a.out');
	scanf;
	bfs;
	precalc;
	flow;
end.

