import java.util.Scanner;
import java.util.StringTokenizer;
import java.util.zip.GZIPInputStream;

import javax.imageio.ImageIO;

public class Main {
	public static void main(String args[]) throws IOException {
		Scanner s = new Scanner(System.in);

		String[] cpt = s.nextLine().split(" ");
		int n = Integer.parseInt(cpt[0]);

		String dom = s.nextLine();
		int total = 0;

		char wait = '0';
		int interval = 0;
		for (char c : dom.toCharArray()) {
			if (c == '.') {
				interval++;
			} else if (wait == '0' && c == 'R') {
				total += interval;
				wait = 'L';
				interval = 0;
			} else if (c == 'R') {
				if (wait == '0') {
					total += interval;
				}
				interval = 0;
				wait = 'L';
			} else if (c == 'L') {
				if (wait != '0') {
					total += interval % 2;
					wait = 'R';
				}
				interval = 0;
			}
		}

		if (wait != 'L') {
			total += interval;
		}

		System.out.println(total);
	}
}

